    ListeningText(id = "de-listen-language-class", languageID = "de", title = "Der Sprachkurs", level = "A1", topic = "Vorstellungen", unitID = "de-foundations-u1", text = "Marta besucht ihren ersten Portugiesischkurs in einem kleinen Institut. Im Kurs sind sechs Personen, und alle möchten sprechen. Die Lehrerin bittet um Vorstellungen. „Ich heiße Marta und ich bin aus Bolivien“, sagt eine Dame. „Ich bin Andrés, ich komme aus Peru und arbeite in einem Restaurant“, sagt ein junger Mann. Marta stellt sich auch vor: „Ich bin Marta, ich bin Argentinierin und ich bin Krankenschwester.“ Die Lehrerin ist aus Madrid und unterrichtet mit viel Humor. Am Ende des Kurses tauschen die Teilnehmer ihre Telefonnummern aus. Sie sind noch keine Freunde, aber nächste Woche gehen sie zusammen einen Kaffee trinken und üben.", questions = listOf(Exercise(id = "de-listen-language-class-q1", kind = "choice", prompt = "Wie viele Personen sind im Kurs?", options = listOf("Sechs", "Drei", "Zehn", "Vierzehn"), answers = listOf("Sechs"), explain = "Im Kurs sind sechs Personen."), Exercise(id = "de-listen-language-class-q2", kind = "choice", prompt = "Woher kommt Andrés?", options = listOf("Aus Peru", "Aus Bolivien", "Aus Argentinien", "Aus Mexiko"), answers = listOf("Aus Peru"), explain = "Andrés kommt aus Peru und arbeitet in einem Restaurant."), Exercise(id = "de-listen-language-class-q3", kind = "choice", prompt = "Was ist Marta von Beruf?", options = listOf("Krankenschwester", "Lehrerin", "Kellnerin", "Studentin"), answers = listOf("Krankenschwester"), explain = "Marta ist Argentinierin und sie ist Krankenschwester."), Exercise(id = "de-listen-language-class-q4", kind = "written", prompt = "Woher ist die Lehrerin?", options = listOf(), answers = listOf("madrid", "aus madrid", "sie ist aus madrid"), explain = "Die Lehrerin ist aus Madrid."), Exercise(id = "de-listen-language-class-q5", kind = "choice", prompt = "Was machen sie am Ende des Kurses?", options = listOf("Sie tauschen ihre Telefon