    ListeningText(id = "de-listen-little-sister", languageID = "de", title = "Meine kleine Schwester", level = "A1", topic = "Familie", unitID = "de-foundations-u1", text = "Meine kleine Schwester heißt Carla und ist neun Jahre alt. Sie ist sehr nett und sehr gesprächig. Carla ist nicht schüchtern: Sie spricht mit allen, mit den Nachbarn, mit den Lehrern und mit den Hunden im Park. Sie ist blond, wie unsere Mutter, und hat braune Augen wie unser Vater. Sie ist nicht groß für ihr Alter, aber sie ist sehr schnell und spielt riesig gern Fußball. Ihre Mannschaft ist nicht sehr gut, aber das ist ihr egal. „Ich bin keine Profispielerin“, sagt sie, „ich bin nur glücklich mit dem Ball.“ Meine Schwester ist klein, aber ihre Freude ist riesig.", questions = listOf(Exercise(id = "de-listen-little-sister-q1", kind = "choice", prompt = "Wie alt ist Carla?", options = listOf("Neun", "Neunzehn", "Sieben", "Zehn"), answers = listOf("Neun"), explain = "Carla ist neun Jahre alt."), Exercise(id = "de-listen-little-sister-q2", kind = "choice", prompt = "Wie ist Carla?", options = listOf("Nett und gesprächig", "Schüchtern und still", "Ernst", "Traurig"), answers = listOf("Nett und gesprächig"), explain = "Sie ist sehr nett und sehr gesprächig."), Exercise(id = "de-listen-little-sister-q3", kind = "written", prompt = "Welche Augenfarbe hat sie?", options = listOf(), answers = listOf("braun", "braune augen"), explain = "Sie hat braune Augen wie ihr Vater."), Exercise(id = "de-listen-little-sister-q4", kind = "choice", prompt = "Welche Haare hat sie?", options = listOf("Blond, wie ihre Mutter", "Dunkel, wie ihr Vater", "Rot", "Kurz und schwarz"), answers = listOf("Blond, wie ihre Mutter"), explain = "Sie ist blond, wie unsere Mutter."), Exercise(id = "de-listen-little-sister-q5", kind = "choice", prompt = "Was spielt sie riesig gern?", options = listOf("Fußball", "Schwimmen", "Musik", "Videospiele"), answers = listOf("Fußball"), explain = "Sie ist sehr schnell und spielt riesig gern Fußbal