    ListeningText(id = "de-listen-new-flatmate", languageID = "de", title = "Ein neuer Mitbewohner", level = "A1", topic = "Wohnung", unitID = "de-foundations-u1", text = "Tom hat einen neuen Mitbewohner. Er heißt Leo und ist dreiundzwanzig Jahre alt. Leo kommt aus einem kleinen Dorf im Norden, arbeitet aber jetzt in der Stadt. Er hat zwei Kartons, eine Gitarre und ein Fahrrad. Die Wohnung hat zwei Zimmer und eine helle Küche. Tom hofft, dass Leo gern kocht, denn Tom kocht überhaupt nicht gern.", questions = listOf(Exercise(id = "de-listen-new-flatmate-q1", kind = "choice", prompt = "Wie alt ist Leo?", options = listOf("Dreiundzwanzig", "Zweiunddreißig", "Zwanzig", "Dreißig"), answers = listOf("Dreiundzwanzig"), explain = "Leo ist dreiundzwanzig Jahre alt."), Exercise(id = "de-listen-new-flatmate-q2", kind = "choice", prompt = "Was hat Leo NICHT?", options = listOf("Einen Fernseher", "Zwei Kartons", "Eine Gitarre", "Ein Fahrrad"), answers = listOf("Einen Fernseher"), explain = "Er hat zwei Kartons, eine Gitarre und ein Fahrrad — keinen Fernseher."), Exercise(id = "de-listen-new-flatmate-q3", kind = "written", prompt = "Was macht Tom ungern?", options = listOf(), answers = listOf("kochen", "er kocht nicht gern", "tom kocht nicht gern"), explain = "Tom kocht überhaupt nicht gern."), Exercise(id = "de-listen-new-flatmate-q4", kind = "choice", prompt = "Wie ist die Wohnung?", options = listOf("Zwei Zimmer und eine helle Küche", "Ein Zimmer und ein Balkon", "Ein Garten", "Zwei Badezimmer"), answers = listOf("Zwei Zimmer und eine helle Küche"), explain = "Die Wohnung hat zwei Zimmer und eine helle Küche."), Exercise(id = "de-listen-new-flatmate-q5", kind = "choice", prompt = "Wo arbeitet Leo jetzt?", options = listOf("In der Stadt", "In einem kleinen Dorf", "Im Norden", "Er arbeitet nicht"), answers = listOf("In der Stadt"), explain = "Er kommt aus einem kleinen Dorf, arbeitet aber jetzt in der Stadt."), Exercise(id = "de-listen-new-flatmate-q6", kind = "written", prompt 