    ListeningText(id = "de-listen-new-neighbour", languageID = "de", title = "Die neue Nachbarin", level = "A1", topic = "Leute", unitID = "de-foundations-u1", text = "Im Haus gibt es eine neue Nachbarin. Sie heißt Amélie und kommt aus Frankreich. Sie ist keine Studentin; sie ist Fotografin. Sie arbeitet nicht in einem Büro: Sie arbeitet von zu Hause und reist viel. Die Nachbarn sind neugierig, aber sie sind auch schüchtern, deshalb sprechen sie nicht mit ihr. Dann trifft Ben sie eines Morgens an der Tür. „Bist du die neue Nachbarin?“, fragt er. „Ja, das bin ich“, antwortet sie, „und ich bin froh, hier zu sein.“ Jetzt sind sie Freunde, und sie ist nicht mehr allein im Haus.", questions = listOf(Exercise(id = "de-listen-new-neighbour-q1", kind = "choice", prompt = "Woher kommt Amélie?", options = listOf("Aus Frankreich", "Aus Italien", "Aus Japan", "Aus Brasilien"), answers = listOf("Aus Frankreich"), explain = "Amélie kommt aus Frankreich."), Exercise(id = "de-listen-new-neighbour-q2", kind = "choice", prompt = "Was ist ihr Beruf?", options = listOf("Fotografin", "Studentin", "Büroangestellte", "Lehrerin"), answers = listOf("Fotografin"), explain = "Sie ist keine Studentin; sie ist Fotografin."), Exercise(id = "de-listen-new-neighbour-q3", kind = "choice", prompt = "Arbeitet sie in einem Büro?", options = listOf("Nein, sie arbeitet von zu Hause", "Ja, jeden Tag", "Nur im Sommer", "Das sagt sie nicht"), answers = listOf("Nein, sie arbeitet von zu Hause"), explain = "Sie arbeitet nicht in einem Büro: Sie arbeitet von zu Hause."), Exercise(id = "de-listen-new-neighbour-q4", kind = "written", prompt = "Warum sprechen die Nachbarn nicht mit ihr?", options = listOf(), answers = listOf("sie sind schüchtern", "weil sie schüchtern sind", "schüchtern"), explain = "Sie sind neugierig, aber sie sind auch schüchtern."), Exercise(id = "de-listen-new-neighbour-q5", kind = "choice", prompt = "Wo trifft Ben sie?", options = listOf("An der Tür", "Im Aufzug", "Auf der Straße", "Im Café"), answers = listOf("An der Tür"), explain = "Eines Morgens trifft Ben sie an der Tür."), Exercise(id = "de-listen-new-neighbour-q6", kind = "written", prompt = "Wie fühlt sich Amélie am Ende?", options = listOf(), answers = listOf("froh", "glücklich", "sie ist froh"), explain = "Sie sagt, sie ist froh, hier zu sein.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")),
    ListeningText(id = "de-listen-sunday-market", languageID = "de", title = "Der Sonntagsmarkt", level = "A1", topic = "Einkaufen", unitID = "de-foundations-u1", text = "Sonntags gibt es einen Markt auf dem Dorfplatz. Anna und ihr Vater gehen um neun Uhr dorthin, bevor er voll wird. Sie kaufen Obst, Brot und Blumen. Anna möchte Erdbeeren, aber ihr Vater sagt, sie sind diese Woche zu teuer. Am Ende nehmen sie eine große Tüte Orangen und weiße Rosen für den Küchentisch mit nach Hause.", questions = listOf(Exercise(id = "de-listen-sunday-market-q1", kind = "choice", prompt = "Wann gehen Anna und ihr Vater zum Markt?", options = listOf("Um neun Uhr", "Um zwölf Uhr", "Am Nachmittag", "Um halb sieben"), answers = listOf("Um neun Uhr"), explain = "Sie gehen um neun Uhr, bevor er voll wird."), Exercise(id = "de-listen-sunday-market-q2", kind = "written", prompt = "Warum bekommt Anna keine Erdbeeren?", options = listOf(), answers = listOf("sie sind zu teuer", "zu teuer", "weil sie zu teuer sind"), explain = "Ihr Vater sagt, sie sind diese Woche zu teuer."), Exercise(id = "de-listen-sunday-market-q3", kind = "choice", prompt = "Was nehmen sie mit nach Hause?", options = listOf("Orangen und Rosen", "Erdbeeren und Brot", "Äpfel und Tulpen", "Brot und Käse"), answers = listOf("Orangen und Rosen"), explain = "Sie nehmen Orangen und weiße Rosen mit."), Exercise(id = "de-listen-sunday-market-q4", kind = "choice", prompt = "Wo ist der Markt?", options = listOf("Auf dem Dorfplatz", "Am Fluss", "Am Bahnhof", "In einem Supermarkt"), answers = listOf("Auf dem Dorfplatz"), explain = "Sonntags gibt es einen Markt auf dem Dorfplatz."), Exercise(id = "de-listen-sunday-market-q5", kind = "choice", prompt = "Was kaufen sie?", options = listOf("Obst, Brot und Blumen", "Fisch und Gemüse", "Käse und Fleisch", "Nur Blumen"), answers = listOf("Obst, Brot und Blumen"), explain = "Sie kaufen Obst, Brot und Blumen."), Exercise(id = "de-listen-sunday-market-q6", kind = "written", prompt = "Was möchte