    ListeningText(id = "de-listen-wohnung-gewaehlt", languageID = "de", title = "Die gewählte Wohnung", level = "A2", topic = "wohnungen", unitID = "de-foundations-u4", text = "Anna und Ben suchen eine Wohnung. Die erste ist billiger, aber sie liegt weiter vom Bahnhof: vierzig Minuten zu Fuß. Die zweite kostet hundert Euro mehr im Monat, aber sie ist heller und hat einen Balkon. Für Anna ist das Licht am wichtigsten, weil sie von zu Hause arbeitet. Am Ende bitten sie um eine Besichtigung der zweiten: sie ist teurer, aber für sie die beste von beiden.", questions = listOf(Exercise(id = "de-listen-wohnung-gewaehlt-q1", kind = "choice", prompt = "Wie viele Wohnungen vergleichen sie ?", options = listOf("Zwei", "Drei", "Vier"), answers = listOf("Zwei"), explain = "Sie vergleichen zwei Wohnungen."), Exercise(id = "de-listen-wohnung-gewaehlt-q2", kind = "choice", prompt = "Was ist das Problem der billigeren ?", options = listOf("Sie liegt weit vom Bahnhof", "Sie hat keinen Balkon", "Sie ist sehr teuer", "Sie ist klein"), answers = listOf("Sie liegt weit vom Bahnhof"), explain = "Vierzig Minuten zu Fuß."), Exercise(id = "de-listen-wohnung-gewaehlt-q3", kind = "written", prompt = "Wie viel kostet die zweite mehr pro Monat ?", options = listOf(), answers = listOf("hundert euro", "100 euro"), explain = "Hundert Euro mehr im Monat."), Exercise(id = "de-listen-wohnung-gewaehlt-q4", kind = "choice", prompt = "Was ist für Anna am wichtigsten ?", options = listOf("Das Licht", "Der Preis", "Der Balkon", "Die Küche"), answers = listOf("Das Licht"), explain = "Sie arbeitet von zu Hause."), Exercise(id = "de-listen-wohnung-gewaehlt-q5", kind = "choice", prompt = "Was beschließen sie am Ende ?", options = listOf("Eine Besichtigung der zweiten", "Bei der ersten bleiben", "Weiter suchen", "Rabatt fragen"), answers = listOf("Eine Besichtigung der zweiten"), explain = "Die beste von beiden für sie.")), skills = listOf("listening:gist", "listening:inference", "grammar:comparatives"), exposu