    ListeningText(id = "de-listen-samstag-geplant", languageID = "de", title = "Der geplante Samstag", level = "A2", topic = "pläne", unitID = "de-foundations-u4", text = "Mia ruft ihren Bruder an, um den Samstag zu planen. Er schlägt den Berg vor, aber es wird regnen, deshalb schlägt Mia das neue Museum vor. Sie treffen sich um zehn Uhr am Haupteingang und essen im Markt nebenan, der billiger ist als die Restaurants im Zentrum. Am Abend haben sie keinen Plan: sie entscheiden vor Ort, wenn sie das Wetter kennen.", questions = listOf(Exercise(id = "de-listen-samstag-geplant-q1", kind = "choice", prompt = "Wer schlägt den Berg vor ?", options = listOf("Der Bruder", "Mia", "Die Mutter", "Ein Freund"), answers = listOf("Der Bruder"), explain = "Ihr Bruder schlägt den Berg vor."), Exercise(id = "de-listen-samstag-geplant-q2", kind = "choice", prompt = "Warum nicht der Berg ?", options = listOf("Es wird regnen", "Sie sind müde", "Das Museum ist gratis", "Der Berg ist weit"), answers = listOf("Es wird regnen"), explain = "Es wird regnen, deshalb Museum."), Exercise(id = "de-listen-samstag-geplant-q3", kind = "written", prompt = "Um wie viel Uhr treffen sie sich ?", options = listOf(), answers = listOf("um zehn uhr", "zehn uhr"), explain = "Um zehn Uhr am Haupteingang."), Exercise(id = "de-listen-samstag-geplant-q4", kind = "choice", prompt = "Wo essen sie ?", options = listOf("Im Markt nebenan", "In einem Restaurant im Zentrum", "Zu Hause", "Im Museum"), answers = listOf("Im Markt nebenan"), explain = "Billiger als die Restaurants im Zentrum."), Exercise(id = "de-listen-samstag-geplant-q5", kind = "choice", prompt = "Was machen sie am Abend ?", options = listOf("Vor Ort entscheiden", "Ins Kino gehen", "Früh heimgehen", "Freunde treffen"), answers = listOf("Vor Ort entscheiden"), explain = "Je nach Wetter.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("grammar:future-forms")),
    ListeningText(id = "de-listen-nie-gemacht", languageID = "de", title = "Was ich nie gemacht habe", level = "B1", topic = "reisen", unitID = "de-foundations-u6", text = "In der Küche einer Herberge vergleichen drei Reisende ihr Leben. Jonas ist in zwanzig Ländern gewesen, aber er hat nie schwimmen gelernt: « Ich weiß, es ist lächerlich ». Amira ist schon zweimal mit Schildkröten getaucht, aber sie hat Afrika vor dieser Reise nie verlassen. Und Coco, die seit sechs Jahren unterwegs ist, ist noch nie geflogen: sie überquert die Ozeane mit dem Schiff und die Grenzen mit dem Bus. « Nie ? » fragt Jonas. « Nie. Die Angst ist älter als ich. » Sie lachen über die Dinge, die sie nicht gemacht haben, und Coco sagt einen Satz, der bleibt: « Man muss nicht alles gemacht haben. Man muss nur noch wollen ».", questions = listOf(Exercise(id = "de-listen-nie-gemacht-q1", kind = "choice", prompt = "Was hat Jonas nie gemacht ?", options = listOf("Schwimmen lernen", "Zwanzig Länder besuchen", "Mit dem Schiff fahren", "Afrika verlassen"), answers = listOf("Schwimmen lernen"), explain = "Er ist in zwanzig Ländern gewesen, aber nie schwimmen gelernt."), Exercise(id = "de-listen-nie-gemacht-q2", kind = "written", prompt = "Wie oft ist Amira getaucht ?", options = listOf(), answers = listOf("zweimal", "2 mal", "zwei mal"), explain = "Amira ist schon zweimal mit Schildkröten getaucht."), Exercise(id = "de-listen-nie-gemacht-q3", kind = "choice", prompt = "Wie überquert Coco die Ozeane ?", options = listOf("Mit dem Schiff", "Mit dem Flugzeug", "Mit dem Bus", "Zu Fuß"), answers = listOf("Mit dem Schiff"), explain = "Sie überquert die Ozeane mit dem Schiff."), Exercise(id = "de-listen-nie-gemacht-q4", kind = "choice", prompt = "Was sagt Coco über die Angst ?", options = listOf("Sie ist älter als sie", "Sie ist jünger", "Es ist lächerlich", "Sie ist weg"), answers = listOf("Sie ist älter als sie"), explain = "Die Angst ist älter als ich."), Exercise(id = "de-listen-nie-gemacht-q5", kind = "written", prompt = "Was reicht, laut Coco ?", options = listOf(), answers = listOf("noch wollen", "man muss noch wollen"), explain = "Man muss nur noch wollen.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")),
    ListeningText(id = "de-listen-stadt-dorf", languageID = "de", title = "Von der Stadt ins Dorf", level = "B1", topic = "veränderungen", unitID = "de-foundations-u6", text = "Lukas erzählt, warum er Berlin verlassen hat. Früher hat er in einer kleinen Wohnung gewohnt und elf Stunden am Tag gearbeitet: « Ich habe gut verdient, aber kein Leben gehabt ». Einen Winter wurde er krank, und da hat er verstanden: so konnte es nicht weitergehen. Heute wohnt er in einem Dorf mit tausend Einwohnern, arbeitet morgens von zu Hause und gartelt nachmittags. « Ich verdiene weniger, aber ich habe Zeit. » Am Anfang haben seine Eltern es nicht verstanden; heute kommen sie jeden Monat. « Bereust du etwas ? » fragt seine Freundin. « Dass ich es nicht früher gemacht habe ».", questions = listOf(Exercise(id = "de-listen-stadt-dorf-q1", kind = "choice", prompt = "Wo hat Lukas früher gewohnt ?", options = listOf("In Berlin", "In einem Dorf", "In Hamburg", "In einer Herberge"), answers = listOf("In Berlin"), explain = "Lukas erzählt, warum er Berlin verlassen hat."), Exercise(id = "de-listen-stadt-dorf-q2", kind = "written", prompt = "Wie viele Stunden hat er am Tag gearbeitet ?", options = listOf(), answers = listOf("elf stunden", "11 stunden", "elf"), explain = "Elf Stunden am Tag."), Exercise(id = "de-listen-stadt-dorf-q3", kind = "choice", prompt = "Was hat ihn verändert ?", options = listOf("Er wurde krank", "Er verlor seinen Job", "Er gewann im Lotto", "Er traf jemanden"), answers = listOf("Er wurde krank"), explain = "Einen Winter wurde er krank, und da hat er verstanden."), Exercise(id = "de-listen-stadt-dorf-q4", kind = "choice", prompt = "Was macht er nachmittags ?", options = listOf("Er gartelt", "Er arbeitet mehr Stunden", "Er reist jeden Monat", "Er lernt"), answers = listOf("Er gartelt"), explain = "Er arbeitet morgens und gartelt nachmittags."), Exercise(id = "de-listen-stadt-dorf-q5", kind = "written", prompt = "Was bereut Lukas ?", options = listOf(), answers = listOf("dass ich es nicht frueher gemacht habe", "dass ich es nicht früher gemacht habe", "nicht frueher", "nicht früher"), explain = "« Dass ich es nicht früher gemacht habe ».")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions")),
    ListeningText(id = "de-listen-handel-tisch", languageID = "de", title = "Das Feilschen um den Tisch", level = "B2", topic = "verhandeln", unitID = "de-foundations-u7", text = "Auf einer Gebraucht-App will Lena einen Holztisch für 80 Euro. « Wären Sie bei 60 dabei ? », fragt sie. Der Verkäufer lehnt ab: « Nur wenn Sie ihn heute abholen ». Lena überlegt: « Ich würde 65 geben, wenn Sie den Stuhl dazugeben ». « Unmöglich », lacht er, « aber ich würde Ihnen den Tisch für 70 lassen und ihn Ihnen hochtragen ». Lena zögert nicht: « Würden Sie ihn allein hochtragen ? ». « Ich habe einen Handwagen », antwortet er. « Abgemacht », sagt sie, und fügt hinzu: « Wenn er so schön ist wie auf dem Foto, gibt es fünf Sterne ».", questions = listOf(Exercise(id = "de-listen-handel-tisch-q1", kind = "choice", prompt = "Wie viel verlangt der Verkäufer ?", options = listOf("80 Euro", "60 Euro", "70 Euro", "65 Euro"), answers = listOf("80 Euro"), explain = "Der Tisch kostet 80 Euro."), Exercise(id = "de-listen-handel-tisch-q2", kind = "written", prompt = "Was schlägt Lena zuerst vor ?", options = listOf(), answers = listOf("60 euro", "bei 60 dabei", "sechzig euro"), explain = "« Wären Sie bei 60 dabei ? »."), Exercise(id = "de-listen-handel-tisch-q3", kind = "choice", prompt = "Welche Bedingung stellt der Verkäufer ?", options = listOf("Heute abholen", "Bar bezahlen", "Fünf Sterne geben", "Morgen kommen"), answers = listOf("Heute abholen"), explain = "« Nur wenn Sie ihn heute abholen »."), Exercise(id = "de-listen-handel-tisch-q4", kind = "choice", prompt = "Was bietet der Verkäufer für 70 ?", options = listOf("Den Tisch hochtragen", "Den Stuhl dazugeben", "Auf 60 sinken", "Einen Handwagen leihen"), answers = listOf("Den Tisch hochtragen"), explain = "« Ich würde ihn Ihnen hochtragen »."), Exercise(id = "de-listen-handel-tisch-q5", kind = "written", prompt = "Was verspricht Lena, wenn der Tisch gefällt ?", options = listOf(), answers = listOf("funf sterne", "fünf sterne", "5 sterne"), explain = "Fünf Sterne.")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors")),
    ListeningText(id = "de-listen-nachricht-viertel", languageID = "de", title = "Die Nachricht im Viertel", level = "B2", topic = "nachrichten", unitID = "de-foundations-u8", text = "Am Markt besprechen Hannah und Tom, was man sagt. « Man sagt, sie machen die Hauptstraße autofrei », erzählt Hannah. « Schon wieder ? », lacht Tom. « Die Nachricht, die ich gelesen habe, sagt, dass es im Frühling beginnt ». Laut Rathaus wäre es nur am Samstag, aber die Händler, deren Umsatz vom Tourismus abhinge, haben schon demonstriert. « Es stimmt, dass der Lärm sinken würde », räumt Tom ein, « aber, und die Parkplätze ? ». Hannah verteidigt die Maßnahme: « Einerseits würden mehr Leute laufen; andererseits hielten die Busse direkt vor der Tür ». Sie entscheiden es nicht, aber versprechen, wieder darüber zu sprechen, wenn der Plan veröffentlicht wird.", questions = listOf(Exercise(id = "de-listen-nachricht-viertel-q1", kind = "choice", prompt = "Was sagt man über die Hauptstraße ?", options = listOf("Dass sie autofrei wird", "Dass sie breiter wird", "Dass sie geschlossen wird", "Dass sie umbenannt wird"), answers = listOf("Dass sie autofrei wird"), explain = "« Man sagt, sie machen die Hauptstraße autofrei »."), Exercise(id = "de-listen-nachricht-viertel-q2", kind = "written", prompt = "Wann würde es beginnen ?", options = listOf(), answers = listOf("im fruhling", "im frühling", "frühling"), explain = "« …dass es im Frühling beginnt »."), Exercise(id = "de-listen-nachricht-viertel-q3", kind = "choice", prompt = "Was sagt das Rathaus ?", options = listOf("Nur am Samstag", "An allen Tagen", "Nur im Sommer", "An Feiertagen"), answers = listOf("Nur am Samstag"), explain = "Laut Rathaus wäre es nur am Samstag."), Exercise(id = "de-listen-nachricht-viertel-q4", kind = "choice", prompt = "Wer hat demonstriert ?", options = listOf("Die Händler", "Die Anwohner", "Die Taxifahrer", "Das Rathaus"), answers = listOf("Die Händler"), explain = "Die Händler haben schon demonstriert."), Exercise(id = "de-listen-nachricht-viertel-q5", kind = "written", prompt = "Was versprechen Hannah und Tom ?", options = listOf(), answers = listOf("daruber zu sprechen", "darüber zu sprechen", "wieder daruber sprechen"), explain = "Sie versprechen, wieder darüber zu sprechen.")), skills = listOf("listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors")),
    ListeningText(id = "en-listen-language-cafe", languageID = "en", title = "The language café", level = "A1", topic = "introductions", unitID = "en-foundations-u1", text = "Every Wednesday evening, a small café in the city centre is a language café. Students from many countries sit together at big tables. Lucas is twenty-five years old, and he is from Brazil. His Portuguese and Spanish are excellent, and his English is quite good now. At his table there is a woman from Japan and two men from Italy. They ask simple questions: Where are you from? What do you do? Lucas is a nurse, and he is happy to answer. At ten o'clock the café closes, but the new friends are not tired. They are only happy to talk.", questions = listOf(Exercise(id = "en-listen-language-cafe-q1", kind = "choice", prompt = "Where is the language café?", options = listOf("In a small café in the city centre", "In a school", "In a park", "In a hotel"), answers = listOf("In a small café in the city centre"), explain = "Every Wednesday evening, a small café in the city centre is a language café."), Exercise(id = "en-listen-language-cafe-q2", kind = "choice", prompt = "Where is Lucas from?", options = listOf("Brazil", "Japan", "Italy", "Portugal"), answers = listOf("Brazil"), explain = "Lucas is from Brazil."), Exercise(id = "en-listen-language-cafe-q3", kind = "written", prompt = "How old is Lucas?", options = listOf(), answers = listOf("twenty-five", "25", "he is twenty-five"), explain = "Lucas is twenty-five years old."), Exercise(id = "en-listen-language-cafe-q4", kind = "choice", prompt = "What is his job?", options = listOf("He is a nurse", "He is a teacher", "He is a waiter", "He is a student"), answers = listOf("He is a nurse"), explain = "Lucas is a nurse, and he is happy to answer."), Exercise(id = "en-listen-language-cafe-q5", kind = "choice", prompt = "Who sits at his table?", options = listOf("A woman from Japan and two men from Italy", "Two women from Brazil", "A man from Japan", "Four students from Spain"), answers = listOf("A woman from Japan and two men from Italy"), explain = "At his table there is a woman from Japan and two men from Italy."), Exercise(id = "en-listen-language-cafe-q6", kind = "written", prompt = "What time does the café close?", options = listOf(), answers = listOf("at ten o'clock", "ten o'clock", "ten"), explain = "At ten o'clock the café closes.")), skills = listOf("listening:gist", "listening:detail", "vocab:introductions", "function:introduce-yourself")),
    ListeningText(id = "en-listen-new-neighbour", languageID = "en", title = "The new neighbour", level = "A1", topic = "people", unitID = "en-foundations-u1", text = "There is a new neighbour in the building. Her name is Amélie, and she is from France. She is not a student; she is a photographer. She doesn't work in an office — she works at home, and she travels a lot. The people in the building are curious, but they are also shy, so they don't talk to her. Then one morning, Ben meets her at the door. \"Are you the new neighbour?\" he asks. \"Yes, I am,\" she says, \"and I am happy to be here.\" Now they are friends, and she isn't alone in the building.", questions = listOf(Exercise(id = "en-listen-new-neighbour-q1", kind = "choice", prompt = "Where is Amélie from?", options = listOf("France", "Italy", "Japan", "Brazil"), answers = listOf("France"), explain = "Amélie is from France."), Exercise(id = "en-listen-new-neighbour-q2", kind = "choice", prompt = "What is her job?", options = listOf("She is a photographer", "She is a student", "She works in an office", "She is a teacher"), answers = listOf("She is a photographer"), explain = "She is not a student; she is a photographer."), Exercise(id = "en-listen-new-neighbour-q3", kind = "choice", prompt = "Does she work in an office?", options = listOf("No, she works at home", "Yes, every day", "Only in summer", "She doesn't say"), answers = listOf("No, she works at home"), explain = "She doesn't work in an office — she works at home."), Exercise(id = "en-listen-new-neighbour-q4", kind = "written", prompt = "Why don't the people talk to her?", options = listOf(), answers = listOf("they are shy", "because they are shy", "shy"), explain = "They are curious, but they are also shy."), Exercise(id = "en-listen-new-neighbour-q5", kind = "choice", prompt = "Where does Ben meet her?", options = listOf("At the door", "In the lift", "In the street", "At the café"), answers = listOf("At the door"), explain = "One morning, Ben meets her at the door."), Exercise(id = "en-listen-new-neighbour-q6", kind = "written", prompt = "How does Amélie feel at the end?", options = listOf(), answers = listOf("happy", "she is happy", "happy to be here"), explain = "She says she is happy to be here.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")),
    ListeningText(id = "en-listen-lost-umbrella", languageID = "en", title = "The blue umbrella", level = "A1", topic = "things", unitID = "en-foundations-u2", text = "It is a rainy Monday, and the classroom is full of umbrellas. \"Whose umbrella is this?\" the teacher asks. It is a big blue umbrella, and it is next to my chair. \"It isn't mine,\" says Marta. \"My umbrella is green.\" \"Is it yours, Pedro?\" \"No, it isn't. My things are in my bag.\" Then Daniel comes in, wet and tired. He looks at the blue umbrella and laughs. \"That's my umbrella! It's my father's umbrella, and he needs it today.\" The class laughs too. Daniel takes his umbrella, and the teacher writes on the board: your, my, his, her.", questions = listOf(Exercise(id = "en-listen-lost-umbrella-q1", kind = "choice", prompt = "What is the weather like?", options = listOf("Rainy", "Sunny", "Snowy", "Windy and dry"), answers = listOf("Rainy"), explain = "It is a rainy Monday."), Exercise(id = "en-listen-lost-umbrella-q2", kind = "choice", prompt = "What colour is the umbrella next to the chair?", options = listOf("Blue", "Green", "Black", "Red"), answers = listOf("Blue"), explain = "It is a big blue umbrella."), Exercise(id = "en-listen-lost-umbrella-q3", kind = "written", prompt = "What colour is Marta's umbrella?", options = listOf(), answers = listOf("green", "it is green", "her umbrella is green"), explain = "Marta's umbrella is green."), Exercise(id = "en-listen-lost-umbrella-q4", kind = "choice", prompt = "Whose umbrella is the blue one?", options = listOf("Daniel's", "Marta's", "Pedro's", "The teacher's"), answers = listOf("Daniel's"), explain = "Daniel says it is his umbrella — his father's umbrella."), Exercise(id = "en-listen-lost-umbrella-q5", kind = "choice", prompt = "Where are Pedro's things?", options = listOf("In his bag", "At home", "In his car", "Under the chair"), answers = listOf("In his bag"), explain = "Pedro says his things are in his bag."), Exercise(id = "en-listen-lost-umbrella-q6", kind = "choice", prompt = "Why does Daniel need the umbrella today?", options = listOf("His father needs it", "It is a gift for Marta", "It is for the teacher", "He wants to sell it"), answers = listOf("His father needs it"), explain = "It is his father's umbrella, and his father needs it today.")), skills = listOf("listening:detail", "grammar:demonstratives", "vocab:social-expressions")),
    ListeningText(id = "en-listen-new-flatmate", languageID = "en", title = "A new flatmate", level = "A1", topic = "home", unitID = "en-foundations-u2", text = "Tom has got a new flatmate. His name is Leo and he is twenty-three years old. Leo comes from a small town in the north, but he works in the city now. He has got two boxes, a guitar and a bicycle. The flat has got two bedrooms and a sunny kitchen. Tom hopes Leo likes cooking, because Tom hates it.", questions = listOf(Exercise(id = "en-listen-new-flatmate-q1", kind = "choice", prompt = "How old is Leo?", options = listOf("Twenty-three", "Thirty-two", "Twenty", "Thirty"), answers = listOf("Twenty-three"), explain = "Leo is twenty-three years old."), Exercise(id = "en-listen-new-flatmate-q2", kind = "choice", prompt = "What has Leo NOT got?", options = listOf("A television", "Two boxes", "A guitar", "A bicycle"), answers = listOf("A television"), explain = "He has two boxes, a guitar and a bicycle — no television."), Exercise(id = "en-listen-new-flatmate-q3", kind = "written", prompt = "What does Tom hate doing?", options = listOf(), answers = listOf("cooking", "he hates cooking", "tom hates cooking"), explain = "Tom hates cooking."), Exercise(id = "en-listen-new-flatmate-q4", kind = "choice", prompt = "What does the flat have?", options = listOf("Two bedrooms and a sunny kitchen", "One bedroom and a balcony", "A garden", "Two bathrooms"), answers = listOf("Two bedrooms and a sunny kitchen"), explain = "The flat has got two bedrooms and a sunny kitchen."), Exercise(id = "en-listen-new-flatmate-q5", kind = "choice", prompt = "Where does Leo work now?", options = listOf("In the city", "In a small town", "In the north", "He doesn't work"), answers = listOf("In the city"), explain = "He comes from a small town, but he works in the city now."), Exercise(id = "en-listen-new-flatmate-q6", kind = "written", prompt = "Which instrument has Leo got?", options = listOf(), answers = listOf("a guitar", "guitar", "he has got a guitar"), explain = "Leo has got a guitar.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")),
    ListeningText(id = "en-listen-coffee-morning", languageID = "en", title = "A coffee before work", level = "A1", topic = "routine", unitID = "en-foundations-u3", text = "Every morning, Marta walks to a small café near her flat. The waiter knows her name, so she never has to order. Today she sits by the window with a coffee and a croissant. Her bus leaves at half past eight, but she is not worried. The café is very quiet at this hour. She drinks her coffee slowly and watches the city wake up.", questions = listOf(Exercise(id = "en-listen-coffee-morning-q1", kind = "choice", prompt = "Where does Marta go every morning?", options = listOf("To a small café", "To her office", "To the bus station", "To a park"), answers = listOf("To a small café"), explain = "She walks to a small café near her flat."), Exercise(id = "en-listen-coffee-morning-q2", kind = "choice", prompt = "What does she have for breakfast today?", options = listOf("Tea and toast", "A coffee and a croissant", "Orange juice", "Nothing"), answers = listOf("A coffee and a croissant"), explain = "She sits by the window with a coffee and a croissant."), Exercise(id = "en-listen-coffee-morning-q3", kind = "written", prompt = "What time does her bus leave?", options = listOf(), answers = listOf("at half past eight", "half past eight", "8:30"), explain = "Her bus leaves at half past eight."), Exercise(id = "en-listen-coffee-morning-q4", kind = "choice", prompt = "How does she feel about the time?", options = listOf("She is not worried", "She is very late", "She is angry", "She is sleepy"), answers = listOf("She is not worried"), explain = "The text says she is not worried."), Exercise(id = "en-listen-coffee-morning-q5", kind = "choice", prompt = "Who knows Marta's name?", options = listOf("The waiter", "The bus driver", "Her boss", "A neighbour"), answers = listOf("The waiter"), explain = "The waiter knows her name, so she never has to order."), Exercise(id = "en-listen-coffee-morning-q6", kind = "written", prompt = "Where does she sit today?", options = listOf(), answers = listOf("by the window", "next to the window", "at the window"), explain = "Today she sits by the window.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")),
    ListeningText(id = "en-listen-night-shift", languageID = "en", title = "The night shift", level = "A1", topic = "work", unitID = "en-foundations-u3", text = "Paolo is a baker, and he works at night. His shift starts at eleven o'clock in the evening, and it finishes at seven in the morning. First, he makes the bread; then he makes the cakes. He never works alone — his cousin works with him, and they talk while they work. Paolo usually sleeps from nine in the morning to three in the afternoon. On Sundays he doesn't work, and he has lunch with his family. His neighbours sometimes ask him: \"Do you like your job?\" \"Yes,\" he says, \"the city is quiet, the bread smells wonderful, and my mornings are free.\"", questions = listOf(Exercise(id = "en-listen-night-shift-q1", kind = "choice", prompt = "When does Paolo's shift start?", options = listOf("At eleven in the evening", "At seven in the morning", "At nine in the morning", "At three in the afternoon"), answers = listOf("At eleven in the evening"), explain = "His shift starts at eleven o'clock in the evening."), Exercise(id = "en-listen-night-shift-q2", kind = "written", prompt = "What does he make first?", options = listOf(), answers = listOf("bread", "the bread", "he makes the bread"), explain = "First, he makes the bread; then the cakes."), Exercise(id = "en-listen-night-shift-q3", kind = "choice", prompt = "Who works with him?", options = listOf("His cousin", "His brother", "His wife", "A friend from school"), answers = listOf("His cousin"), explain = "He never works alone — his cousin works with him."), Exercise(id = "en-listen-night-shift-q4", kind = "written", prompt = "When does Paolo usually sleep?", options = listOf(), answers = listOf("from nine to three", "from nine in the morning to three in the afternoon", "nine to three"), explain = "He usually sleeps from nine in the morning to three in the afternoon."), Exercise(id = "en-listen-night-shift-q5", kind = "choice", prompt = "What does he do on Sundays?", options = listOf("He has lunch with his family", "He sleeps all day", "He works alone", "He bakes cakes at home"), answers = listOf("He has lunch with his family"), explain = "On Sundays he doesn't work, and he has lunch with his family."), Exercise(id = "en-listen-night-shift-q6", kind = "choice", prompt = "Why does Paolo like his job?", options = listOf("The city is quiet and the bread smells wonderful", "It is very well paid", "He meets a lot of people", "The nights are long"), answers = listOf("The city is quiet and the bread smells wonderful"), explain = "He says the city is quiet, the bread smells wonderful and his mornings are free.")), skills = listOf("listening:number-time", "listening:detail", "grammar:third-person-s", "grammar:frequency-adverbs", "vocab:work")),
    ListeningText(id = "en-listen-city-walk", languageID = "en", title = "A walk in the new city", level = "A1", topic = "directions", unitID = "en-foundations-u4", text = "Nadia is new in town, and today she explores on foot. In her street there is a small supermarket, a bakery and a bookshop — everything is very close, so she doesn't need the bus. She walks to the river and turns left. There, she can see the old bridge and a big park. In the park there are children, dogs and a lot of green space. She can't visit the museum because it is closed on Mondays, but she can sit in the sun. A man with a dog gives her directions to the market: \"Go straight, cross the bridge, and the market is on your right.\" She thanks him and walks on.", questions = listOf(Exercise(id = "en-listen-city-walk-q1", kind = "choice", prompt = "How does Nadia explore the city?", options = listOf("On foot", "By bus", "By bike", "By tram"), answers = listOf("On foot"), explain = "Today she explores on foot."), Exercise(id = "en-listen-city-walk-q2", kind = "choice", prompt = "What is in her street?", options = listOf("A supermarket, a bakery and a bookshop", "A cinema and a café", "A school", "A hospital"), answers = listOf("A supermarket, a bakery and a bookshop"), explain = "In her street there is a small supermarket, a bakery and a bookshop."), Exercise(id = "en-listen-city-walk-q3", kind = "choice", prompt = "What can she see from the river?", options = listOf("The old bridge and a big park", "A castle", "The museum", "A shopping centre"), answers = listOf("The old bridge and a big park"), explain = "From the river she can see the old bridge and a big park."), Exercise(id = "en-listen-city-walk-q4", kind = "choice", prompt = "Why can't she visit the museum?", options = listOf("It is closed on Mondays", "She doesn't have time", "It is too expensive", "She can't find it"), answers = listOf("It is closed on Mondays"), explain = "The museum is closed on Mondays."), Exercise(id = "en-listen-city-walk-q5", kind = "written", prompt = "Where is the market?", options = listOf(), answers = listOf("on your right", "on the right", "on her right"), explain = "Cross the bridge, and the market is on your right."), Exercise(id = "en-listen-city-walk-q6", kind = "written", prompt = "Who gives her directions?", options = listOf(), answers = listOf("a man with a dog", "a man", "the man with the dog"), explain = "A man with a dog gives her directions.")), skills = listOf("listening:detail", "function:ask-for-directions", "vocab:directions", "grammar:imperatives")),
    ListeningText(id = "en-listen-bus-stop-chat", languageID = "en", title = "The bus stop chat", level = "A1", topic = "people", unitID = "en-foundations-out", text = "It's cold at the bus stop, and Ben doesn't like silence. 'Cold today, isn't it?' he says to the woman next to him. 'Freezing,' she says. 'Any plans for the weekend?' Ben asks. 'Nothing much — you?' 'My sister is visiting, so we'll walk by the river if it doesn't rain.' The woman smiles. 'Sounds nice. My plans are tea and a book!' The bus arrives — late, of course. 'Have a good one!' Ben says as she gets on. 'You too!' And that's it: a complete conversation with a stranger, sixty seconds long.", questions = listOf(Exercise(id = "en-listen-bus-stop-chat-q1", kind = "choice", prompt = "How does Ben open the conversation?", options = listOf("About the cold", "About the bus", "About the river", "About tea"), answers = listOf("About the cold"), explain = "'Cold today, isn't it?' — the weather opener."), Exercise(id = "en-listen-bus-stop-chat-q2", kind = "written", prompt = "What are the woman's plans for the weekend?", options = listOf(), answers = listOf("tea and a book", "tea", "a book"), explain = "Her plans are tea and a book."), Exercise(id = "en-listen-bus-stop-chat-q3", kind = "choice", prompt = "Who is visiting Ben?", options = listOf("His sister", "His mother", "A neighbour", "Nobody"), answers = listOf("His sister"), explain = "His sister is visiting, so they'll walk by the river."), Exercise(id = "en-listen-bus-stop-chat-q4", kind = "written", prompt = "Where will they walk if it doesn't rain?", options = listOf(), answers = listOf("by the river", "the river"), explain = "By the river."), Exercise(id = "en-listen-bus-stop-chat-q5", kind = "choice", prompt = "How does the bus arrive?", options = listOf("Late, of course", "Early", "Full", "It never arrives"), answers = listOf("Late, of course"), explain = "The bus arrives — late, of course."), Exercise(id = "en-listen-bus-stop-chat-q6", kind = "written", prompt = "How does Ben say goodbye?", options = listOf(), answers = listOf("have a good one", "have a good one!"), explain = "'Have a good one!' as she gets on.")), skills = listOf("vocab:social-expressions", "grammar:present-continuous", "function:talk-about-weather")),
    ListeningText(id = "en-listen-saturday-list", languageID = "en", title = "The Saturday list", level = "A1", topic = "shopping", unitID = "en-foundations-out", text = "Saturday morning, and Marta is at the supermarket with a long list. She needs bread, milk, eggs and tomatoes, but she can't find the tomatoes. A shop assistant is stacking apples nearby. 'Excuse me, where are the tomatoes?' Marta asks. 'Aisle three, next to the juice,' the assistant says. Marta finds them, checks the price — two euros fifty — and goes to the checkout. 'Anything else?' the cashier asks. 'No, that's all, thanks!' At home, she unpacks the bag and finds one thing missing: the bread. It's still on the kitchen table, next to her keys.", questions = listOf(Exercise(id = "en-listen-saturday-list-q1", kind = "choice", prompt = "What is NOT on Marta's list?", options = listOf("Tomatoes", "Bread", "Milk", "Apples"), answers = listOf("Apples"), explain = "The apples belong to the shop assistant, not the list."), Exercise(id = "en-listen-saturday-list-q2", kind = "written", prompt = "Where are the tomatoes?", options = listOf(), answers = listOf("aisle three", "in aisle three", "aisle 3"), explain = "Aisle three, next to the juice."), Exercise(id = "en-listen-saturday-list-q3", kind = "choice", prompt = "How much are the tomatoes?", options = listOf("Two euros fifty", "Three euros", "Two euros", "Fifty cents"), answers = listOf("Two euros fifty"), explain = "She checks the price: two euros fifty."), Exercise(id = "en-listen-saturday-list-q4", kind = "written", prompt = "What does the cashier ask?", options = listOf(), answers = listOf("anything else", "anything else?"), explain = "'Anything else?' — the cashier's question."), Exercise(id = "en-listen-saturday-list-q5", kind = "choice", prompt = "What is missing at home?", options = listOf("The bread", "The milk", "The eggs", "The tomatoes"), answers = listOf("The bread"), explain = "The bread is still on the kitchen table."), Exercise(id = "en-listen-saturday-list-q6", kind = "written", prompt = "What else is on the kitchen table?", options = listOf(), answers = listOf("her keys", "the keys", "keys"), explain = "Her keys are next to the bread.")), skills = listOf("vocab:food", "grammar:there-is-are", "grammar:present-simple", "function:go-shopping")),
    ListeningText(id = "en-listen-sunday-market", languageID = "en", title = "The Sunday market", level = "A1", topic = "shopping", unitID = "en-foundations-u4", text = "On Sundays there is a market in the town square. Anna and her father go there at nine o'clock, before it gets busy. They buy fruit, bread and flowers. Anna wants some strawberries, but her father says they are too expensive this week. In the end they take home a big bag of oranges and some white roses for the kitchen table.", questions = listOf(Exercise(id = "en-listen-sunday-market-q1", kind = "choice", prompt = "When do Anna and her father go to the market?", options = listOf("At nine o'clock", "At noon", "In the afternoon", "At half past six"), answers = listOf("At nine o'clock"), explain = "They go at nine o'clock, before it gets busy."), Exercise(id = "en-listen-sunday-market-q2", kind = "written", prompt = "Why doesn't Anna get the strawberries?", options = listOf(), answers = listOf("they are too expensive", "too expensive", "because they are too expensive"), explain = "Her father says they are too expensive this week."), Exercise(id = "en-listen-sunday-market-q3", kind = "choice", prompt = "What do they take home?", options = listOf("Oranges and roses", "Strawberries and bread", "Apples and tulips", "Bread and cheese"), answers = listOf("Oranges and roses"), explain = "They take home oranges and white roses."), Exercise(id = "en-listen-sunday-market-q4", kind = "choice", prompt = "Where is the market?", options = listOf("In the town square", "Near the river", "At the station", "In a supermarket"), answers = listOf("In the town square"), explain = "There is a market in the town square on Sundays."), Exercise(id = "en-listen-sunday-market-q5", kind = "choice", prompt = "What do they buy?", options = listOf("Fruit, bread and flowers", "Fish and vegetables", "Cheese and meat", "Only flowers"), answers = listOf("Fruit, bread and flowers"), explain = "They buy fruit, bread and flowers."), Exercise(id = "en-listen-sunday-market-q6", kind = "written", prompt = "What does Anna want?", options = listOf(), answers = listOf("strawberries", "some strawberries", "she wants strawberries"), explain = "Anna wants some strawberries.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")),
    ListeningText(id = "en-listen-new-neighbourhood", languageID = "en", title = "The new neighbourhood", level = "A1", topic = "town", unitID = "en-foundations-town", text = "Sofia just moved to Maple Street, and her new neighbour Tom is telling her everything. 'There's a bakery on the corner — the bread is fantastic. There are two schools, a park and a small library. There isn't a cinema, I'm afraid; the nearest one is two bus stops away.' Sofia asks about the park: 'Is there a chemist's near the park?' 'Yes, right next to it,' Tom says. 'And the people?' Sofia wants to know. 'They're friendly and very quiet,' Tom laughs, 'except on Saturdays, when the football starts.'", questions = listOf(Exercise(id = "en-listen-new-neighbourhood-q1", kind = "choice", prompt = "What is on the corner?", options = listOf("A bakery", "A park", "A library", "A cinema"), answers = listOf("A bakery"), explain = "There's a bakery on the corner — fantastic bread."), Exercise(id = "en-listen-new-neighbourhood-q2", kind = "written", prompt = "What is there two of?", options = listOf(), answers = listOf("schools", "two schools"), explain = "There are two schools."), Exercise(id = "en-listen-new-neighbourhood-q3", kind = "choice", prompt = "What is missing in the neighbourhood?", options = listOf("A cinema", "A library", "A bakery", "A park"), answers = listOf("A cinema"), explain = "There isn't a cinema — the nearest is two bus stops away."), Exercise(id = "en-listen-new-neighbourhood-q4", kind = "written", prompt = "Where is the chemist's?", options = listOf(), answers = listOf("next to the park", "near the park", "right next to the park"), explain = "Right next to the park."), Exercise(id = "en-listen-new-neighbourhood-q5", kind = "choice", prompt = "What are the people like?", options = listOf("Friendly and quiet", "Loud", "Unfriendly", "Always at football"), answers = listOf("Friendly and quiet"), explain = "Friendly and very quiet — except on Saturdays."), Exercise(id = "en-listen-new-neighbourhood-q6", kind = "written", prompt = "What starts on Saturdays?", options = listOf(), answers = listOf("the football", "football"), explain = "The football starts on Saturdays.")), skills = listOf("vocab:town", "grammar:there-is-are", "function:ask-simple-questions")),
    ListeningText(id = "en-listen-rainy-day", languageID = "en", title = "A rainy Saturday", level = "A1", topic = "weather", unitID = "en-foundations-now", text = "It is raining in Maple Street, and Anna is looking out of the window. Her brother Ben is playing a video game in the living room, and their mother is reading on the sofa. Outside, the neighbours are running to their cars with umbrellas. The cat is sleeping in its favourite chair, and the dog is watching the rain too. Anna is not bored — she is drawing the grey sky in her notebook. Her mother is making tea, and the kitchen smells wonderful. 'What are you doing?' Ben asks. 'I'm drawing the weather,' Anna says, 'because today the weather is interesting!'", questions = listOf(Exercise(id = "en-listen-rainy-day-q1", kind = "choice", prompt = "What is the weather doing?", options = listOf("It's raining", "It's snowing", "It's sunny", "It's windy"), answers = listOf("It's raining"), explain = "It is raining in Maple Street."), Exercise(id = "en-listen-rainy-day-q2", kind = "choice", prompt = "What is Ben doing?", options = listOf("He's playing a video game", "He's drawing", "He's making tea", "He's sleeping"), answers = listOf("He's playing a video game"), explain = "Her brother Ben is playing a video game."), Exercise(id = "en-listen-rainy-day-q3", kind = "written", prompt = "What is Anna drawing?", options = listOf(), answers = listOf("the grey sky", "the sky", "the weather"), explain = "She is drawing the grey sky in her notebook."), Exercise(id = "en-listen-rainy-day-q4", kind = "choice", prompt = "Where is the cat?", options = listOf("In its favourite chair", "Under the table", "Outside in the rain", "On Anna's bed"), answers = listOf("In its favourite chair"), explain = "The cat is sleeping in its favourite chair."), Exercise(id = "en-listen-rainy-day-q5", kind = "written", prompt = "What is the mother making?", options = listOf(), answers = listOf("tea", "making tea", "she is making tea"), explain = "Her mother is making tea."), Exercise(id = "en-listen-rainy-day-q6", kind = "choice", prompt = "How does Anna feel about the day?", options = listOf("She is not bored", "She is sad", "She is angry", "She is tired"), answers = listOf("She is not bored"), explain = "Anna is not bored — for her the weather is interesting.")), skills = listOf("listening:detail", "grammar:present-continuous", "vocab:weather")),
    ListeningText(id = "en-listen-busy-kitchen", languageID = "en", title = "Sunday in the kitchen", level = "A1", topic = "family", unitID = "en-foundations-now", text = "It is Sunday morning, and the whole family is in the kitchen. Grandma is cutting bread, and Grandpa is making coffee — his coffee is always too strong. Anna's father is singing while he is cooking eggs, and her mother is setting the table. The twins are helping, but they are eating more strawberries than they are putting in the bowl. Even the dog is working: he is waiting under the table for pieces of cheese. 'Is anyone NOT eating in this kitchen?' Grandpa laughs. Everyone is smiling. Sunday breakfast is the family's favourite moment of the week.", questions = listOf(Exercise(id = "en-listen-busy-kitchen-q1", kind = "choice", prompt = "Where is the whole family?", options = listOf("In the kitchen", "In the garden", "In the car", "At a café"), answers = listOf("In the kitchen"), explain = "The whole family is in the kitchen on Sunday morning."), Exercise(id = "en-listen-busy-kitchen-q2", kind = "written", prompt = "What is Grandma doing?", options = listOf(), answers = listOf("cutting bread", "she is cutting bread", "she's cutting bread"), explain = "Grandma is cutting bread."), Exercise(id = "en-listen-busy-kitchen-q3", kind = "choice", prompt = "What is Grandpa's coffee like?", options = listOf("Always too strong", "Cold", "Perfect", "Without sugar"), answers = listOf("Always too strong"), explain = "His coffee is always too strong."), Exercise(id = "en-listen-busy-kitchen-q4", kind = "written", prompt = "What is the father doing while he cooks?", options = listOf(), answers = listOf("singing", "he is singing", "he's singing"), explain = "He is singing while he is cooking eggs."), Exercise(id = "en-listen-busy-kitchen-q5", kind = "choice", prompt = "What are the twins really doing with the strawberries?", options = listOf("Eating them", "Washing them", "Selling them", "Cutting them"), answers = listOf("Eating them"), explain = "They are eating more strawberries than they are putting in the bowl."), Exercise(id = "en-listen-busy-kitchen-q6", kind = "written", prompt = "What is the dog waiting for?", options = listOf(), answers = listOf("pieces of cheese", "cheese", "some cheese"), explain = "He is waiting under the table for pieces of cheese.")), skills = listOf("listening:gist", "grammar:present-continuous", "vocab:family")),
    ListeningText(id = "en-listen-birthday-week", languageID = "en", title = "The birthday week", level = "A1", topic = "dates", unitID = "en-foundations-days", text = "This is a special week for Leo. His birthday is on Friday, 12 September, and his family is planning three small parties. On Monday, his colleagues are taking him to a café after work. On Wednesday, his friends are coming to his flat for a film night — his sister is making her famous chocolate cake on Thursday, so the flat smells of chocolate for two days. The family party is on Saturday at three o'clock, at his grandparents' house. Leo's favourite day? 'Sunday,' he laughs, 'because then I can finally rest — my birthday week is wonderful but very busy!'", questions = listOf(Exercise(id = "en-listen-birthday-week-q1", kind = "written", prompt = "When is Leo's birthday?", options = listOf(), answers = listOf("on friday 12 september", "friday 12 september", "12 september", "friday 12th september"), explain = "His birthday is on Friday, 12 September."), Exercise(id = "en-listen-birthday-week-q2", kind = "choice", prompt = "What are his colleagues doing on Monday?", options = listOf("Taking him to a café", "Cooking a cake", "Coming to his flat", "Resting"), answers = listOf("Taking him to a café"), explain = "On Monday, his colleagues are taking him to a café after work."), Exercise(id = "en-listen-birthday-week-q3", kind = "choice", prompt = "When is the family party?", options = listOf("On Saturday at three o'clock", "On Wednesday evening", "On Friday at work", "On Monday morning"), answers = listOf("On Saturday at three o'clock"), explain = "The family party is on Saturday at three o'clock."), Exercise(id = "en-listen-birthday-week-q4", kind = "written", prompt = "What is his sister making, and when?", options = listOf(), answers = listOf("chocolate cake on thursday", "a chocolate cake on thursday", "chocolate cake, on thursday"), explain = "She is making her famous chocolate cake on Thursday."), Exercise(id = "en-listen-birthday-week-q5", kind = "choice", prompt = "Where is the family party?", options = listOf("At his grandparents' house", "At a café", "At his flat", "At work"), answers = listOf("At his grandparents' house"), explain = "It is at his grandparents' house."), Exercise(id = "en-listen-birthday-week-q6", kind = "written", prompt = "What is Leo's favourite day of the week? Why? (one word for the day)", options = listOf(), answers = listOf("sunday", "on sunday", "sunday because he can rest"), explain = "Sunday — because then he can finally rest.")), skills = listOf("listening:number-time", "grammar:time-expressions", "function:tell-time"), exposureSkills = listOf("grammar:present-continuous")),
    ListeningText(id = "en-listen-not-feeling-well", languageID = "en", title = "Not feeling well", level = "A1", topic = "health", unitID = "en-foundations-days", text = "Daniel doesn't feel well this morning. He has got a headache and a sore throat, and his whole body is tired. At work, his colleague Sofia notices immediately. 'What's wrong?' she asks. 'I've got a cold, I think,' Daniel says. 'My throat hurts, and I can't stop sneezing.' Sofia is worried. 'Go home and rest! Drink hot tea with honey — my grandmother's recipe.' Daniel takes her advice. In the afternoon, he is in bed with a big cup of tea. His cat is sleeping next to him. On Friday he is back at work, and his colleagues say he looks great.", questions = listOf(Exercise(id = "en-listen-not-feeling-well-q1", kind = "choice", prompt = "How does Daniel feel this morning?", options = listOf("He doesn't feel well", "He feels great", "He is angry", "He is hungry"), answers = listOf("He doesn't feel well"), explain = "Daniel doesn't feel well this morning."), Exercise(id = "en-listen-not-feeling-well-q2", kind = "written", prompt = "What has Daniel got?", options = listOf(), answers = listOf("a cold", "he has got a cold", "he's got a cold", "a headache and a cold"), explain = "He thinks he has got a cold."), Exercise(id = "en-listen-not-feeling-well-q3", kind = "choice", prompt = "Who notices first?", options = listOf("His colleague Sofia", "His mother", "His cat", "His boss"), answers = listOf("His colleague Sofia"), explain = "His colleague Sofia notices immediately."), Exercise(id = "en-listen-not-feeling-well-q4", kind = "written", prompt = "What does Sofia recommend?", options = listOf(), answers = listOf("hot tea with honey", "tea with honey", "go home and rest"), explain = "Hot tea with honey — her grandmother's recipe."), Exercise(id = "en-listen-not-feeling-well-q5", kind = "choice", prompt = "Where is Daniel in the afternoon?", options = listOf("In bed with a cup of tea", "At the pharmacy", "At work", "At Sofia's house"), answers = listOf("In bed with a cup of tea"), explain = "He is in bed with a big cup of tea."), Exercise(id = "en-listen-not-feeling-well-q6", kind = "choice", prompt = "When is he back at work?", options = listOf("On Friday", "On Monday", "The same afternoon", "On Wednesday"), answers = listOf("On Friday"), explain = "On Friday he is back at work and looks great.")), skills = listOf("listening:detail", "vocab:health", "grammar:have-got", "grammar:can")),
    ListeningText(id = "en-listen-language-exchange", languageID = "en", title = "The language-exchange evening", level = "A2", topic = "languages", unitID = "en-foundations-u5", text = "Last Thursday, Ines went to a language exchange at a bar in the old town. She wanted to practise her English, so she sat with a group from Manchester. At first she could only smile and nod. But after half an hour the words started to come. They talked about films, football and the differences between Spanish and English breakfasts. She didn't leave until eleven, and she wrote down fifteen new expressions on the tram home.", questions = listOf(Exercise(id = "en-listen-language-exchange-q1", kind = "choice", prompt = "Why did Ines go to the exchange?", options = listOf("To practise her English", "To watch football", "To eat breakfast", "To teach maths"), answers = listOf("To practise her English"), explain = "She wanted to practise her English."), Exercise(id = "en-listen-language-exchange-q2", kind = "written", prompt = "What could she do at first?", options = listOf(), answers = listOf("she could only smile and nod", "smile and nod", "only smile and nod"), explain = "At first she could only smile and nod."), Exercise(id = "en-listen-language-exchange-q3", kind = "choice", prompt = "What did they NOT talk about?", options = listOf("Their jobs", "Films", "Football", "Breakfasts"), answers = listOf("Their jobs"), explain = "They talked about films, football and breakfasts — not jobs."), Exercise(id = "en-listen-language-exchange-q4", kind = "written", prompt = "What did she do on the tram home?", options = listOf(), answers = listOf("she wrote down fifteen new expressions", "she wrote down new expressions", "wrote down fifteen expressions"), explain = "She wrote down fifteen new expressions."), Exercise(id = "en-listen-language-exchange-q5", kind = "choice", prompt = "Where did the exchange take place?", options = listOf("In a bar in the old town", "In a school", "In a library", "In a 