    ListeningText(id = "en-listen-rainy-picnic", languageID = "en", title = "The rainy picnic", level = "A2", topic = "weather", unitID = "en-foundations-u5", text = "We were so excited about the picnic on Saturday. The weather was warm on Friday, so we didn't check the forecast. On Saturday morning it started to rain and it didn't stop all day. We moved everything into the kitchen and ate on the floor. Honestly, it was one of the best afternoons of the summer. Sometimes the plans that go wrong are the ones you remember.", questions = listOf(Exercise(id = "en-listen-rainy-picnic-q1", kind = "choice", prompt = "Why didn't they check the forecast?", options = listOf("The weather was warm on Friday", "They don't have a phone", "They were in a hurry", "They forgot"), answers = listOf("The weather was warm on Friday"), explain = "The weather was warm on Friday, so they didn't check."), Exercise(id = "en-listen-rainy-picnic-q2", kind = "written", prompt = "Where did they eat?", options = listOf(), answers = listOf("in the kitchen", "on the kitchen floor", "on the floor in the kitchen"), explain = "They moved everything into the kitchen and ate on the floor."), Exercise(id = "en-listen-rainy-picnic-q3", kind = "choice", prompt = "How did they feel about the day in the end?", options = listOf("It was one of the best afternoons", "It was a disaster", "They were bored", "They were angry"), answers = listOf("It was one of the best afternoons"), explain = "It was one of the best afternoons of the summer."), Exercise(id = "en-listen-rainy-picnic-q4", kind = "choice", prompt = "What was the weather like on Saturday?", options = listOf("It rained all day", "Sunny", "Cloudy but dry", "Snowy"), answers = listOf("It rained all day"), explain = "It started to rain and didn't stop all day."), Exercise(id = "en-listen-rainy-picnic-q5", kind = "choice", prompt = "Which day was the picnic planned for?", options = listOf("Saturday", "Friday", "Sunday", "Monday"), answers = listOf("Saturday"), explain = "They were excited about the picnic on Saturday."), Exercise(id = "en-listen-rainy-picnic-q6", kind = "written", prompt = "What was the weather like on Friday?", options = listOf(), answers = listOf("warm", "it was warm", "the weather was warm"), explain = "The weather was warm on Friday.")), skills = listOf("listening:inference", "listening:detail", "vocab:weather"), exposureSkills = listOf("grammar:past-was-were", "grammar:past-simple-regular")),
    ListeningText(id = "en-listen-first-day", languageID = "en", title = "Sofia's first day", level = "A2", topic = "jobs", unitID = "en-foundations-u6", text = "Yesterday was Sofia's first day at her new job. She woke up at six, took the tram and arrived early. The office was smaller than she expected, but everyone was friendly. Her manager gave her a laptop and a long list of things to read. At lunchtime she ate with two colleagues in the park next to the office. On the way home she felt tired but happy, and she called her mother to tell her everything.", questions = listOf(Exercise(id = "en-listen-first-day-q1", kind = "choice", prompt = "When did Sofia arrive at the office?", options = listOf("Early", "Late", "At noon", "She doesn't say"), answers = listOf("Early"), explain = "She woke up at six and arrived early."), Exercise(id = "en-listen-first-day-q2", kind = "written", prompt = "What did her manager give her?", options = listOf(), answers = listOf("a laptop and a long list", "a laptop and a list of things to read", "a laptop"), explain = "He gave her a laptop and a long list of things to read."), Exercise(id = "en-listen-first-day-q3", kind = "choice", prompt = "Where did she eat lunch?", options = listOf("In the park", "At her desk", "In a café", "At home"), answers = listOf("In the park"), explain = "She ate with two colleagues in the park next to the office."), Exercise(id = "en-listen-first-day-q4", kind = "choice", prompt = "How did she feel on the way home?", options = listOf("Tired but happy", "Angry", "Sad and lonely", "Nervous"), answers = listOf("Tired but happy"), explain = "She felt tired but happy."), Exercise(id = "en-listen-first-day-q5", kind = "choice", prompt = "How did she go to work?", options = listOf("By tram", "By bus", "On foot", "By car"), answers = listOf("By tram"), explain = "She took the tram."), Exercise(id = "en-listen-first-day-q6", kind = "written", prompt = "Who did she call on the way home?", options = listOf(), answers = 