    ListeningText(id = "en-listen-small-accident", languageID = "en", title = "A small accident", level = "A2", topic = "pets", unitID = "en-foundations-u6", text = "While Carlos was cooking dinner on Sunday, he heard a crash from the living room. His cat, Luna, had jumped onto the bookshelf and knocked down his favourite cup. The cup was in pieces on the floor. Luna sat next to the broken pieces, completely calm, as if nothing had happened. Carlos cleaned everything up carefully. The cup was from a trip to Lisbon five years ago, but he didn't shout. It was, after all, only a cup.", questions = listOf(Exercise(id = "en-listen-small-accident-q1", kind = "choice", prompt = "What was Carlos doing when he heard the crash?", options = listOf("Cooking dinner", "Cleaning the floor", "Reading", "Sleeping"), answers = listOf("Cooking dinner"), explain = "He was cooking dinner on Sunday."), Exercise(id = "en-listen-small-accident-q2", kind = "written", prompt = "Who broke the cup?", options = listOf(), answers = listOf("his cat luna", "luna", "the cat", "his cat"), explain = "Luna the cat jumped onto the bookshelf and knocked it down."), Exercise(id = "en-listen-small-accident-q3", kind = "choice", prompt = "Where was the cup from?", options = listOf("A trip to Lisbon", "A birthday", "His grandmother", "A market"), answers = listOf("A trip to Lisbon"), explain = "The cup was from a trip to Lisbon five years ago."), Exercise(id = "en-listen-small-accident-q4", kind = "choice", prompt = "How did Carlos react?", options = listOf("He didn't shout", "He shouted at Luna", "He cried", "He called his friend"), answers = listOf("He didn't shout"), explain = "He cleaned up carefully and didn't shout."), Exercise(id = "en-listen-small-accident-q5", kind = "choice", prompt = "Where was the bookshelf?", options = listOf("In the living room", "In the kitchen", "In the bedroom", "In the hall"), answers = listOf("In the living room"), explain = "He heard the crash from the living room, where the bookshelf was."), Exercise(id = "en-listen-small-accident-q6", kind = "written", prompt = "How old is the cup?", options = listOf(), answers = listOf("five years old", "five years", "five"), explain = "The cup was from a trip to Lisbon five years ago.")), skills = listOf("listening:detail", "grammar:past-simple-regular"), exposureSkills = listOf("grammar:past-continuous")),
    ListeningText(id = "en-listen-two-cities", languageID = "en", title = "Two cities, one decision", level = "A2", topic = "travel", unitID = "en-foundations-compare", text = "'So, Lisbon or Porto?' Marta asks. Her sister Lena is moving next month, and the decision is harder than she expected. 'Porto is smaller and cheaper,' Lena says, 'but Lisbon has more job opportunities.' Marta nods. 'And the weather? Lisbon is warmer in winter.' 'True, but Porto is greener — I love the rain on the river.' They compare the flats they found online: the Lisbon flat is more modern but noisier; the Porto flat is older but much bigger, and the rent is lower than in Lisbon. 'Which one do you prefer?' Marta asks. Lena smiles. 'Honestly, the people make the city. My best friend is in Porto — that's the most important thing.'", questions = listOf(Exercise(id = "en-listen-two-cities-q1", kind = "choice", prompt = "What is Lena's decision about?", options = listOf("Moving to Lisbon or Porto", "Two jobs", "Two flats in the same city", "A holiday"), answers = listOf("Moving to Lisbon or Porto"), explain = "She is moving next month and must choose between the two cities."), Exercise(id = "en-listen-two-cities-q2", kind = "written", prompt = "According to Lena, what does Lisbon have more of?", options = listOf(), answers = listOf("job opportunities", "more job opportunities", "jobs"), explain = "Lisbon has more job opportunities."), Exercise(id = "en-listen-two-cities-q3", kind = "choice", prompt = "How does Lena describe the Porto flat?", options = listOf("Older but much bigger", "More modern but noisier", "Cheaper but smaller", "Newer and greener"), answers = listOf("Older but much bigger"), explain = "The Porto flat is older but much bigger, and the rent is lower."), Exercise(id = "en-listen-two-cities-q4", kind = "written", prompt = "Which city is warmer in winter?", options = listOf(), answers = listOf("lisbon", "lisboa"), explain = "Marta says Lisbon is warmer in winter."), Exercise(id = "en-listen-two-cities-q5", kind = "choice", prompt = "What does Lena say is the most important thing?", options = listOf("Her best friend is in Porto", "The weather", "The rent", "The modern flat"), answers = listOf("Her best friend is in Porto"), explain = "For her, the people make the city."), Exercise(id = "en-listen-two-cities-q6", kind = "choice", prompt = "How hard was the decision?", options = listOf("Harder than she expected", "Easy", "Impossible", "She doesn't say"), answers = listOf("Harder than she expected"), explain = "The decision is harder than she expected.")), skills = listOf("listening:inference", "grammar:comparatives", "grammar:superlatives", "vocab:travel")),
    ListeningText(id = "en-listen-quiet-hotel", languageID = "en", title = "The quiet hotel problem", level = "A2", topic = "travel", unitID = "en-foundations-compare", text = "Tom booked a quiet hotel for his holiday, but on the first night a group arrived for a wedding. The music played until three in the morning, and Tom couldn't sleep. In the morning he went to reception. 'I booked a quiet room,' he said calmly. 'Last night I heard every song of the party.' The manager apologised. 'You're right — we shouldn't have given you room twelve. We're moving you to the garden side, and breakfast is on us today.' Tom thanked her. 'That's fair.' The new room was quieter than a library, and by the pool Tom finally started to enjoy his holiday.", questions = listOf(Exercise(id = "en-listen-quiet-hotel-q1", kind = "choice", prompt = "Why couldn't Tom sleep?", options = listOf("There was a wedding party", "The bed was uncomfortable", "It was too cold", "The street was noisy"), answers = listOf("There was a wedding party"), explain = "A wedding group arrived and the music played until three."), Exercise(id = "en-listen-quiet-hotel-q2", kind = "written", prompt = "What had Tom booked?", options = listOf(), answers = listOf("a quiet hotel", "a quiet room", "a quiet hotel room"), explain = "He booked a quiet hotel for his holiday."), Exercise(id = "en-listen-quiet-hotel-q3", kind = "choice", prompt = "How did Tom complain?", options = listOf("Calmly at reception", "He shouted at the manager", "He wrote a bad review", "He called the police"), answers = listOf("Calmly at reception"), explain = "He went to reception and spoke calmly."), Exercise(id = "en-listen-quiet-hotel-q4", kind = "written", prompt = "What did the manager offer?", options = listOf(), answers = listOf("a room on the garden side", "a quieter room", "a room on the garden side and free breakfast", "a new room and free breakfast"), explain = "A room on the garden side, and breakfast on the house."), Exercise(id = "en-listen-quiet-hotel-q5", kind = "choice", prompt = "How was the new room?", options = listOf("Quieter than a library", "Still noisy", "Bigger but expensive", "Next to the pool"), answers = listOf("Quieter than a library"), explain = "The new room was quieter than a library."), Exercise(id = "en-listen-quiet-hotel-q6", kind = "written", prompt = "What was Tom's reaction to the solution?", options = listOf(), answers = listOf("that's fair", "he thanked her", "he said that's fair"), explain = "He thanked her and said that was fair.")), skills = listOf("listening:detail", "function:solve-problems", "grammar:comparatives", "vocab:travel"), exposureSkills = listOf("grammar:past-continuous")),
    ListeningText(id = "en-listen-weekend-plans", languageID = "en", title = "The weekend plan", level = "A2", topic = "free time", unitID = "en-foundations-plans", text = "'What are you going to do this weekend?' Sara asks her flatmate Diego. 'Nothing special,' he says, 'I'm going to clean the flat and maybe watch a film.' Sara has a better idea. 'The weather is going to be sunny on Saturday — some friends are going to cycle to the lake. Are you going to come?' Diego thinks. 'I haven't got a bike.' 'You can rent one — it's only eight euros for the whole day. We're going to leave at nine, have lunch by the water and come back before six.' 'And if it rains?' 'We're going to take the train back — problem solved!' Diego laughs. 'OK, I'm in. But I'm not going to cycle uphill!'", questions = listOf(Exercise(id = "en-listen-weekend-plans-q1", kind = "choice", prompt = "What was Diego going to do this weekend?", options = listOf("Clean the flat and watch a film", "Cycle to the lake", "Visit Sara's friends", "Work"), answers = listOf("Clean the flat and watch a film"), explain = "He was going to clean the flat and maybe watch a film."), Exercise(id = "en-listen-weekend-plans-q2", kind = "written", prompt = "What is the weather going to be like on Saturday?", options = listOf(), answers = listOf("sunny", "it's going to be sunny", "sunny on saturday"), explain = "The weather is going to be sunny."), Exercise(id = "en-listen-weekend-plans-q3", kind = "choice", prompt = "What are Sara and her friends going to do?", options = listOf("Cycle to the lake", "Go to the cinema", "Visit a museum", "Have a picnic in the park"), answers = listOf("Cycle to the lake"), explain = "Some friends are going to cycle to the lake."), Exercise(id = "en-listen-weekend-plans-q4", kind = "written", prompt = "How much does renting a bike cost?", options = listOf(), answers = listOf("eight euros", "8 euros", "8€"), explain = "It's only eight euros for the whole day."), Exercise(id = "en-listen-weekend-plans-q5", kind = "choice", prompt = "What time are they going to leave?", options = listOf("At nine", "At six", "At noon", "At eight"), answers = listOf("At nine"), explain = "They're going to leave at nine and come back before six."), Exercise(id = "en-listen-weekend-plans-q6", kind = "written", prompt = "What is Diego NOT going to do?", options = listOf(), answers = listOf("cycle uphill", "go uphill", "cycle up hill"), explain = "He's in — but he's not going to cycle uphill!")), skills = listOf("listening:gist", "grammar:going-to", "function:make-future-plans", "vocab:hobbies")),
    ListeningText(id = "en-listen-office-rules", languageID = "en", title = "The office rules", level = "A2", topic = "work", unitID = "en-foundations-plans", text = "It's Nerea's first day, and Pablo is showing her around. 'A few rules,' he smiles. 'Everyone has to wear the badge — security is strict about that. You don't have to arrive at eight exactly, but meetings start at nine sharp, so don't be late for those.' 'Should I bring my own laptop?' Nerea asks. 'No — the company gives you one, and you mustn't install outside software on it. Lunch is at one; you can eat in the canteen or go out. On Fridays we don't have to wear formal clothes.' 'And coffee?' 'The machine is free — but you should try the bar next door. Their coffee is much better!'", questions = listOf(Exercise(id = "en-listen-office-rules-q1", kind = "choice", prompt = "What does everyone have to wear?", options = listOf("A badge", "A uniform", "Formal clothes", "A helmet"), answers = listOf("A badge"), explain = "Everyone has to wear the badge — security is strict."), Exercise(id = "en-listen-office-rules-q2", kind = "written", prompt = "What time do meetings start?", options = listOf(), answers = listOf("at nine", "nine", "9"), explain = "Meetings start at nine sharp."), Exercise(id = "en-listen-office-rules-q3", kind = "choice", prompt = "What mustn't Nerea do with the work laptop?", options = listOf("Install outside software", "Take it home", "Use it for email", "Charge it at night"), answers = listOf("Install outside software"), explain = "You mustn't install outside software on it."), Exercise(id = "en-listen-office-rules-q4", kind = "written", prompt = "What is different on Fridays?", options = listOf(), answers = listOf("no formal clothes", "you don't have to wear formal clothes", "informal clothes", "casual clothes"), explain = "On Fridays they don't have to wear formal clothes."), Exercise(id = "en-listen-office-rules-q5", kind = "choice", prompt = "What does Pablo recommend for coffee?", options = listOf("The bar next door", "The office machine", "Making it at home", "The canteen"), answers = listOf("The bar next door"), explain = "You should try the bar next door — much better coffee."), Exercise(id = "en-listen-office-rules-q6", kind = "choice", prompt = "Where can Nerea eat lunch?", options = listOf("In the canteen or out", "Only at her desk", "Only in the canteen", "At the bar next door"), answers = listOf("In the canteen or out"), explain = "Lunch is at one — canteen or out.")), skills = listOf("listening:detail", "grammar:modal-must-have-to", "grammar:modal-should", "vocab:work"), exposureSkills = listOf("grammar:going-to")),
    ListeningText(id = "en-listen-never-been", languageID = "en", title = "Things I've never done", level = "B1", topic = "travel", unitID = "en-foundations-experiences", text = "At a hostel kitchen table, three travellers compare lives. Jonas has visited twenty countries, but he's never learned to swim — 'I know, it's ridiculous.' Amara has swum with dolphins twice, yet she's never left Africa until this trip. And Coco, who has been on the road for six years, has never flown: she crosses oceans on ships and borders on buses. 'Never?' Jonas asks. 'Never. The fear is older than I am.' They laugh about the things they haven't done, and Coco says something that stays with them: 'You don't need to have done everything. You just need to still want to.'", questions = listOf(Exercise(id = "en-listen-never-been-q1", kind = "choice", prompt = "What has Jonas never done?", options = listOf("Learned to swim", "Visited twenty countries", "Flown on a plane", "Crossed a border"), answers = listOf("Learned to swim"), explain = "He has visited twenty countries but has never learned to swim."), Exercise(id = "en-listen-never-been-q2", kind = "written", prompt = "How many times has Amara swum with dolphins?", options = listOf(), answers = listOf("twice", "2 times", "two times"), explain = "She has swum with dolphins twice."), Exercise(id = "en-listen-never-been-q3", kind = "choice", prompt = "How does Coco travel across oceans?", options = listOf("On ships", "On buses", "By plane", "She doesn't cross them"), answers = listOf("On ships"), explain = "She crosses oceans on ships and borders on buses."), Exercise(id = "en-listen-never-been-q4", kind = "written", prompt = "How long has Coco been travelling?", options = listOf(), answers = listOf("six years", "6 years"), explain = "She has been on the road for six years."), Exercise(id = "en-listen-never-been-q5", kind = "choice", prompt = "Why has Coco never flown?", options = listOf("Her fear is older than she is", "She can't afford it", "She prefers trains", "She has never wanted to"), answers = listOf("Her fear is older than she is"), explain = "She says the fear is older than she is."), Exercise(id = "en-listen-never-been-q6", kind = "choice", prompt = "What does Coco say at the end?", options = listOf("You just need to still want to", "Everyone should fly once", "Travel is overrated", "Ships are better"), answers = listOf("You just need to still want to"), explain = "You don't need to have done everything — just to still want to.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")),
    ListeningText(id = "en-listen-traffic-tale", languageID = "en", title = "The day of the parade", level = "B1", topic = "stories", unitID = "en-foundations-experiences", text = "It was a quiet Sunday morning and Elena was cycling to work, as she always did. The streets were almost empty; a few runners were crossing the bridge, and a baker was setting out trays of bread. She was crossing the main square when she heard drums. Suddenly, the road ahead filled with people — a parade she had completely forgotten about. Dancers were spinning, children were waving flags, and a brass band was playing behind them. Elena stopped, one foot on the ground, and just watched. She was twenty minutes late for work, but her boss, who had also been stuck in the crowd, only laughed. 'Some mornings,' he said, 'you're exactly where you should be.'", questions = listOf(Exercise(id = "en-listen-traffic-tale-q1", kind = "choice", prompt = "What was Elena doing when she heard the drums?", options = listOf("She was crossing the main square", "She was working", "She was setting out bread", "She was at home"), answers = listOf("She was crossing the main square"), explain = "She was crossing the main square when she heard drums."), Exercise(id = "en-listen-traffic-tale-q2", kind = "written", prompt = "What were the runners doing on the bridge?", options = listOf(), answers = listOf("crossing it", "crossing the bridge", "running"), explain = "A few runners were crossing the bridge."), Exercise(id = "en-listen-traffic-tale-q3", kind = "choice", prompt = "What filled the road?", options = listOf("A parade", "Traffic", "Rain", "Runners"), answers = listOf("A parade"), explain = "Suddenly, the road filled with people — a forgotten parade."), Exercise(id = "en-listen-traffic-tale-q4", kind = "written", prompt = "What was the brass band doing?", options = listOf(), answers = listOf("playing", "playing behind the dancers", "playing music"), explain = "A brass band was playing behind the dancers."), Exercise(id = "en-listen-traffic-tale-q5", kind = "choice", prompt = "How late was Elena for work?", options = listOf("Twenty minutes", "Ten minutes", "An hour", "She never arrived"), answers = listOf("Twenty minutes"), explain = "She was twenty minutes late."), Exercise(id = "en-listen-traffic-tale-q6", kind = "choice", prompt = "Why did her boss only laugh?", options = listOf("He had also been stuck in the crowd", "It was a holiday", "She never told him", "He loves parades"), answers = listOf("He had also been stuck in the crowd"), explain = "Her boss had also been stuck — some mornings you're exactly where you should be.")), skills = listOf("listening:detail", "grammar:past-continuous", "grammar:past-simple-irregular", "function:tell-a-story"), exposureSkills = listOf("grammar:past-continuous")),
    ListeningText(id = "en-listen-if-it-rains", languageID = "en", title = "If it rains", level = "B1", topic = "plans", unitID = "en-foundations-connections", text = "'So what's the plan if it rains?' Sam asks, looking at the grey sky. Priya has thought about everything. 'If it rains before ten, we'll move the picnic into the greenhouse — my aunt said we can use it. If it starts while we're out, we'll walk fifteen minutes to the station and take the train back.' 'And if the trains stop?' 'They won't — but if they do, we'll call my brother; he loves an excuse to drive at night.' Sam laughs. 'And if the sun shines all day?' 'Then we'll have the best picnic of the year, and you'll owe me an apology for doubting my planning.'", questions = listOf(Exercise(id = "en-listen-if-it-rains-q1", kind = "choice", prompt = "Where will they go if it rains before ten?", options = listOf("To the greenhouse", "Home", "To the station", "To Sam's flat"), answers = listOf("To the greenhouse"), explain = "They'll move the picnic into the greenhouse."), Exercise(id = "en-listen-if-it-rains-q2", kind = "written", prompt = "What will they do if rain starts while they're out?", options = listOf(), answers = listOf("take the train back", "walk to the station and take the train", "walk to the station"), explain = "Walk to the station and take the train back."), Exercise(id = "en-listen-if-it-rains-q3", kind = "choice", prompt = "Who will pick them up if the trains stop?", options = listOf("Priya's brother", "Sam's sister", "Priya's aunt", "Nobody"), answers = listOf("Priya's brother"), explain = "Her brother loves an excuse to drive at night."), Exercise(id = "en-listen-if-it-rains-q4", kind = "written", prompt = "What does Priya say will happen if the sun shines all day?", options = listOf(), answers = listOf("the best picnic of the year", "they'll have the best picnic of the year", "it will be the best picnic of the year"), explain = "Then they'll have the best picnic of the year."), Exercise(id = "en-listen-if-it-rains-q5", kind = "choice", prompt = "Why does Sam owe an apology?", options = listOf("For doubting Priya's planning", "For being late", "For eating the food", "For losing the map"), answers = listOf("For doubting Priya's planning"), explain = "Priya says he'll owe an apology for doubting her planning."), Exercise(id = "en-listen-if-it-rains-q6", kind = "choice", prompt = "How does Priya seem about her plan?", options = listOf("She has thought about everything", "She is nervous", "She hasn't prepared", "She wants to cancel"), answers = listOf("She has thought about everything"), explain = "Priya has an answer for every condition.")), skills = listOf("listening:detail", "grammar:first-conditional", "function:make-future-plans")),
    ListeningText(id = "en-listen-job-change", languageID = "en", title = "Before the change", level = "B1", topic = "work", unitID = "en-foundations-connections", text = "Rosa remembers her office life the way you remember an old coat: familiar, slightly tight. She used to commute ninety minutes each way. She used to eat lunch at her desk and answer emails at midnight. 'I used to think that was normal,' she says. 'Everyone around me did the same.' Two years ago she moved to a small town and opened a bookshop. At first, the silence was unbearable — she didn't use to have quiet, and it felt like something was wrong. Now she closes at six and reads in the evenings. 'People ask if I miss the city. Although I loved parts of it, I don't miss the person I was becoming there.'", questions = listOf(Exercise(id = "en-listen-job-change-q1", kind = "written", prompt = "How long did Rosa use to commute each way?", options = listOf(), answers = listOf("ninety minutes", "90 minutes", "an hour and a half"), explain = "She used to commute ninety minutes each way."), Exercise(id = "en-listen-job-change-q2", kind = "choice", prompt = "What did she use to do at midnight?", options = listOf("Answer emails", "Sleep", "Read", "Cook"), answers = listOf("Answer emails"), explain = "She used to answer emails at midnight."), Exercise(id = "en-listen-job-change-q3", kind = "written", prompt = "What did she open in the small town?", options = listOf(), answers = listOf("a bookshop", "a book shop", "a bookstore"), explain = "She opened a bookshop."), Exercise(id = "en-listen-job-change-q4", kind = "choice", prompt = "How did the silence feel at first?", options = listOf("Unbearable", "Wonderful", "Normal", "Exciting"), answers = listOf("Unbearable"), explain = "She didn't use to have quiet, and it felt like something was wrong."), Exercise(id = "en-listen-job-change-q5", kind = "written", prompt = "What does she do in the evenings now?", options = listOf(), answers = listOf("she reads", "reads"), explain = "Now she closes at six and reads in the evenings."), Exercise(id = "en-listen-job-change-q6", kind = "choice", prompt = "What doesn't she miss about the city?", options = listOf("The person she was becoming", "Her colleagues", "The food", "The salary"), answers = listOf("The person she was becoming"), explain = "Although she loved parts of it, she doesn't miss who she was becoming.")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:work")),
    ListeningText(id = "en-listen-monday-predictions", languageID = "en", title = "The Monday pool", level = "B1", topic = "work", unitID = "en-foundations-change", text = "Every Monday, the design team runs a small prediction pool. 'Ten euros says the client changes the brief by Wednesday,' says Jonas. Petra shakes her head. 'The brief will survive — but the printer will break. It always does.' Newcomer Ana smiles nervously. 'I'll just predict something safe: we'll all complain about the coffee.' Everyone writes their bets on the whiteboard, and the week starts. By Wednesday, the client has indeed changed the brief, twice. Jonas collects his ten euros without a word. The printer, loyal to tradition, jams on Thursday morning — Petra's turn to smile. And on Friday, Ana looks at her line on the board, at the empty coffee machine, and says what everyone is thinking: 'Will anyone else complain, or is it just me?'", questions = listOf(Exercise(id = "en-listen-monday-predictions-q1", kind = "choice", prompt = "What does Jonas predict on Monday?", options = listOf("The client will change the brief", "The printer will break", "The coffee will run out", "Ana will win"), answers = listOf("The client will change the brief"), explain = "'Ten euros says the client changes the brief by Wednesday.'"), Exercise(id = "en-listen-monday-predictions-q2", kind = "written", prompt = "What is Petra's prediction?", options = listOf(), answers = listOf("the printer will break", "the printer breaks", "printer will break"), explain = "The brief will survive, but the printer will break."), Exercise(id = "en-listen-monday-predictions-q3", kind = "written", prompt = "What does newcomer Ana predict?", options = listOf(), answers = listOf("they will all complain about the coffee", "everyone will complain about the coffee", "they'll complain about the coffee"), explain = "A safe prediction: everyone complains about the coffee."), Exercise(id = "en-listen-monday-predictions-q4", kind = "choice", prompt = "What happened by Wednesday?", options = listOf("The client changed the brief twice", "The printer broke", "The coffee machine died", "Nothing"), answers = listOf("The client changed the brief twice"), explain = "The client changed the brief, twice — Jonas wins his bet."), Exercise(id = "en-listen-monday-predictions-q5", kind = "choice", prompt = "When did the printer jam?", options = listOf("Thursday morning", "Wednesday", "Monday", "It didn't"), answers = listOf("Thursday morning"), explain = "Loyal to tradition, it jammed on Thursday morning."), Exercise(id = "en-listen-monday-predictions-q6", kind = "choice", prompt = "How did Jonas collect his winnings?", options = listOf("Without a word", "With a speech", "He never did", "He bought coffee"), answers = listOf("Without a word"), explain = "He collected his ten euros without a word — the quiet winner.")), skills = listOf("listening:inference", "grammar:future-forms", "function:make-future-plans")),
    ListeningText(id = "en-listen-office-rumours", languageID = "en", title = "The rumour mill", level = "B1", topic = "work", unitID = "en-foundations-change", text = "Carmen came back from one day off and the office had invented three futures. 'Marco said the company was moving to Lisbon,' whispered Diego. 'Lena told me they were hiring twenty people,' said Carmen. 'And Priya swears she heard we were all getting new laptops.' Carmen put down her bag and applied the office rule: trace every rumour to its source. The Lisbon story started with a photo Marco took of a moving van — which was moving his neighbour's piano. The twenty hires were real, but Lena had read 'over the next five years' and skipped that part. And the laptops were true: an email had gone out at seven that morning. One truth, one exaggeration, one piano.", questions = listOf(Exercise(id = "en-listen-office-rumours-q1", kind = "choice", prompt = "How many futures had the office invented?", options = listOf("Three", "Two", "Five", "One"), answers = listOf("Three"), explain = "The office had invented three futures in one day."), Exercise(id = "en-listen-office-rumours-q2", kind = "written", prompt = "What did Marco say, according to Diego?", options = listOf(), answers = listOf("the company was moving to lisbon", "they were moving to lisbon", "the company was moving"), explain = "Marco said the company was moving to Lisbon."), Exercise(id = "en-listen-office-rumours-q3", kind = "choice", prompt = "What was the moving van actually moving?", options = listOf("A piano", "Office furniture", "Twenty laptops", "Files"), answers = listOf("A piano"), explain = "Marco's photo showed his neighbour's piano being moved."), Exercise(id = "en-listen-office-rumours-q4", kind = "written", prompt = "What was true about the twenty hires?", options = listOf(), answers = listOf("over the next five years", "they were real but over five years", "over five years"), explain = "Real — but 'over the next five years', which Lena skipped."), Exercise(id = "en-listen-office-rumours-q5", kind = "choice", prompt = "Which rumour was completely true?", options = listOf("The new laptops", "Lisbon", "Twenty hires immediately", "None"), answers = listOf("The new laptops"), explain = "An email had gone out at seven that morning."), Exercise(id = "en-listen-office-rumours-q6", kind = "choice", prompt = "What is the office rule Carmen applies?", options = listOf("Trace every rumour to its source", "Never believe Lena", "Ignore all emails", "Trust Diego"), answers = listOf("Trace every rumour to its source"), explain = "Her rule: trace every rumour to its source.")), skills = listOf("listening:inference", "grammar:reported-speech-basic", "grammar:future-forms", "vocab:work")),
    ListeningText(id = "en-listen-news-swap", languageID = "en", title = "The news swap", level = "B1", topic = "people", unitID = "en-foundations-telling", text = "Café table, two old friends, forty-eight hours of accumulated news. 'You first,' says Ines. 'OK — I got the promotion!' 'No way! Congratulations! When do you start?' 'Monday. And the office is ten minutes from my flat.' 'That IS great news.' Then Ines takes a breath. 'Mine isn't all good. I crashed my bike — I'm fine, but the bike is gone.' 'Oh no, I'm so sorry. Are you OK though? Really?' 'Honestly, yes. Just angry about the bike.' Ines nods, then smiles. 'But there's more: I'm going to Italy in June.' 'Stop it! You're kidding!' 'I'm not. Two weeks, Tuscany, and you're coming with me.'", questions = listOf(Exercise(id = "en-listen-news-swap-q1", kind = "choice", prompt = "What is Ines's good news at the end?", options = listOf("A trip to Italy", "A new bike", "A promotion", "A new job"), answers = listOf("A trip to Italy"), explain = "Two weeks in Tuscany in June."), Exercise(id = "en-listen-news-swap-q2", kind = "written", prompt = "What is the friend's good news?", options = listOf(), answers = listOf("a promotion", "she got the promotion", "the promotion"), explain = "She got the promotion — starting Monday."), Exercise(id = "en-listen-news-swap-q3", kind = "choice", prompt = "What happened to the bike?", options = listOf("It's gone after a crash", "It was stolen", "It needs repair", "She sold it"), answers = listOf("It's gone after a crash"), explain = "Ines crashed her bike; she's fine, but the bike is gone."), Exercise(id = "en-listen-news-swap-q4", kind = "written", prompt = "What is the friend's reaction to the crash?", options = listOf(), answers = listOf("im so sorry", "oh no im so sorry"), explain = "'Oh no, I'm so sorry' — then the care question."), Exercise(id = "en-listen-news-swap-q5", kind = "choice", prompt = "How does the friend react to the promotion?", options = listOf("'No way! Congratulations!'", "'That's awful.'", "'Really? Are you OK?'", "'Good luck.'"), answers = listOf("'No way! Congratulations!'"), explain = "React + congratulate."), Exercise(id = "en-listen-news-swap-q6", kind = "choice", prompt = "What does Ines invite her friend to do?", options = listOf("Come to Tuscany", "Buy a new bike", "Visit the new office", "Start in June"), answers = listOf("Come to Tuscany"), explain = "'You're coming with me.'")), skills = listOf("vocab:social-expressions", "function:express-opinion", "grammar:future-forms")),
    ListeningText(id = "en-listen-grandpas-garden", languageID = "en", title = "Grandpa's garden", level = "A2", topic = "family", text = "When Pablo was a child, he spent every summer at his grandpa's house. The garden was enormous, full of tomato plants and lemon trees. Every morning they watered the plants together and every afternoon they played cards under the big tree. His grandpa didn't talk much, but he laughed easily. Pablo didn't like vegetables then. Now he grows his own tomatoes and understands why his grandpa smiled at them.", questions = listOf(Exercise(id = "en-listen-grandpas-garden-q1", kind = "choice", prompt = "What was in grandpa's garden?", options = listOf("Tomato plants and lemon trees", "Only flowers", "Vegetable soup", "Apple trees"), answers = listOf("Tomato plants and lemon trees"), explain = "It was full of tomato plants and lemon trees."), Exercise(id = "en-listen-grandpas-garden-q2", kind = "written", prompt = "What did they do every afternoon?", options = listOf(), answers = listOf("they played cards", "played cards under the big tree", "they played cards under the big tree"), explain = "They played cards under the big tree."), Exercise(id = "en-listen-grandpas-garden-q3", kind = "choice", prompt = "What was grandpa like?", options = listOf("Quiet but quick to laugh", "Loud and serious", "He never smiled", "He talked all day"), answers = listOf("Quiet but quick to laugh"), explain = "He didn't talk much, but he laughed easily."), Exercise(id = "en-listen-grandpas-garden-q4", kind = "written", prompt = "What does Pablo grow now?", options = listOf(), answers = listOf("tomatoes", "his own tomatoes", "he grows tomatoes"), explain = "Now he grows his own tomatoes."), Exercise(id = "en-listen-grandpas-garden-q5", kind = "choice", prompt = "What did they do every morning?", options = listOf("They watered the plants", "They played cards", "They cooked lunch", "They went shopping"), answers = listOf("They watered the plants"), explain = "Every morning they watered the plants together."), Exercise(id = "en-listen-grandpas-garden-q6", kind = "written", prompt = "What didn't Pablo like as a child?", options = listOf(), answers = listOf("vegetables", "he didn't like vegetables"), explain = "Pablo didn't like vegetables then.")), skills = listOf("listening:inference", "grammar:past-simple-irregular", "vocab:family")),
    ListeningText(id = "en-listen-lost-jacket", languageID = "en", title = "The lost jacket", level = "A2", topic = "clothes", text = "Last week Daniel lost his favourite jacket. He left it on the number twelve bus on Friday evening. He called the lost property office on Monday, but nobody had seen it. Two days later a neighbour knocked on his door and gave him the jacket. She found it on the bus seat with his name and address inside the pocket. Daniel was amazed and invited her in for a cup of tea.", questions = listOf(Exercise(id = "en-listen-lost-jacket-q1", kind = "written", prompt = "Where did Daniel leave his jacket?", options = listOf(), answers = listOf("on the number twelve bus", "on the bus", "on the 12 bus"), explain = "He left it on the number twelve bus."), Exercise(id = "en-listen-lost-jacket-q2", kind = "choice", prompt = "When did he call the lost property office?", options = listOf("On Monday", "On Friday", "Two days later", "The same evening"), answers = listOf("On Monday"), explain = "He called on Monday, but nobody had seen it."), Exercise(id = "en-listen-lost-jacket-q3", kind = "choice", prompt = "Who found the jacket?", options = listOf("A neighbour", "A bus driver", "His mother", "A colleague"), answers = listOf("A neighbour"), explain = "A neighbour knocked on his door and gave him the jacket."), Exercise(id = "en-listen-lost-jacket-q4", kind = "written", prompt = "How did the neighbour know it was Daniel's jacket?", options = listOf(), answers = listOf("his name and address were inside the pocket", "there was a name and address in the pocket", "his name and address in the pocket"), explain = "His name and address were inside the pocket."), Exercise(id = "en-listen-lost-jacket-q5", kind = "choice", prompt = "How did Daniel feel when he got the jacket back?", options = listOf("Amazed", "Angry", "Sad", "Sleepy"), answers = listOf("Amazed"), explain = "Daniel was amazed."), Exercise(id = "en-listen-lost-jacket-q6", kind = "written", prompt = "What did he invite the neighbour for?", options = listOf(), answers = listOf("a cup of tea", "cup of tea", "tea"), explain = "He invited her in for a cup of tea.")), skills = listOf("listening:detail", "grammar:past-simple-regular", "vocab:transport")),
    ListeningText(id = "en-listen-night-train", languageID = "en", title = "The night train", level = "A2", topic = "travel", text = "Ella took the night train to the coast because the morning tickets were too expensive. She shared a small compartment with a woman who worked as a nurse and a student who talked for hours about football. Ella couldn't sleep, but she didn't mind. The train arrived at five in the morning, before the sun came up. She walked out of the station, smelled the sea and knew the trip was worth it.", questions = listOf(Exercise(id = "en-listen-night-train-q1", kind = "written", prompt = "Why did Ella take the night train?", options = listOf(), answers = listOf("the morning tickets were too expensive", "because the morning tickets were too expensive", "morning tickets were too expensive"), explain = "The morning tickets were too expensive."), Exercise(id = "en-listen-night-train-q2", kind = "choice", prompt = "What did the student talk about?", options = listOf("Football", "Nursing", "The coast", "Music"), answers = listOf("Football"), explain = "The student talked for hours about football."), Exercise(id = "en-listen-night-train-q3", kind = "choice", prompt = "When did the train arrive?", options = listOf("At five in the morning", "At five in the evening", "At sunrise", "At midnight"), answers = listOf("At five in the morning"), explain = "It arrived at five, before the sun came up."), Exercise(id = "en-listen-night-train-q4", kind = "written", prompt = "How did Ella know the trip was worth it when she arrived?", options = listOf(), answers = listOf("she smelled the sea", "she smelled the sea and knew the trip was worth it", "because she smelled the sea"), explain = "She walked out and smelled the sea."), Exercise(id = "en-listen-night-train-q5", kind = "choice", prompt = "What was the woman in the compartment?", options = listOf("A nurse", "A teacher", "A doctor", "A driver"), answers = listOf("A nurse"), explain = "She worked as a nurse."), Exercise(id = "en-listen-night-train-q6", kind = "choice", prompt = "Did Ella sleep on the train?", options = listOf("No, but she didn't mind", "Yes, all night", "Yes, for two hours", "She doesn't say"), answers = listOf("No, but she didn't mind"), explain = "She couldn't sleep, but she didn't mind.")), skills = listOf("listening:inference", "grammar:past-simple-irregular", "vocab:travel")),
    ListeningText(id = "en-listen-doctor-call", languageID = "en", title = "The doctor's phone call", level = "A2", topic = "health", unitID = "en-foundations-health", text = "The receptionist answers on the second ring. 'Good morning, Riverside Clinic.' 'Hello, I'd like to make an appointment. It's not an emergency, but I've had back pain for two weeks and it's getting worse.' The receptionist types. 'Dr Lee has a slot today at 16:40. Is that OK?' 'Perfect.' 'Just so I know you've got it: today, 16:40, Dr Lee. Bring your ID and your medication list. And drink water — it helps everything.' The caller laughs. 'Thank you very much.' 'See you this afternoon. Take care!'", questions = listOf(Exercise(id = "en-listen-doctor-call-q1", kind = "choice", prompt = "What does the caller want?", options = listOf("To make an appointment", "A prescription now", "To cancel", "To speak to Dr Lee"), answers = listOf("To make an appointment"), explain = "I'd like to make an appointment."), Exercise(id = "en-listen-doctor-call-q2", kind = "written", prompt = "How long has the back pain lasted?", options = listOf(), answers = listOf("two weeks", "for two weeks"), explain = "For two weeks — and getting worse."), Exercise(id = "en-listen-doctor-call-q3", kind = "choice", prompt = "When is the appointment?", options = listOf("Today at 16:40", "Tomorrow morning", "This evening", "Next week"), answers = listOf("Today at 16:40"), explain = "Dr Lee has a slot today at 16:40."), Exercise(id = "en-listen-doctor-call-q4", kind = "written", prompt = "What should the caller bring?", options = listOf(), answers = listOf("id and medication list", "her id and medication list", "id and a medication list"), explain = "ID and the medication list."), Exercise(id = "en-listen-doctor-call-q5", kind = "choice", prompt = "What does the receptionist recommend for everything?", options = listOf("Drinking water", "Resting", "Painkillers", "Walking"), answers = listOf("Drinking water"), explain = "Drink water — it helps everything (she's joking, half)."), Exercise(id = "en-listen-doctor-call-q6", kind = "written", prompt = "How does the receptionist close the call?", options = listOf(), answers = listOf("see you this afternoon take care", "take care"), explain = "'See you this afternoon. Take care!'")), skills = listOf("function:talk-about-health", "grammar:present-perfect", "vocab:health")),
    ListeningText(id = "en-listen-four-day-week", languageID = "en", title = "The four-day week", level = "B2", topic = "work", unitID = "en-foundations-viewpoints", text = "At the town-hall debate, both speakers agreed on the problem — burnout — and disagreed on nearly everything else. The union representative argued that a four-day week was the obvious fix: trials in Iceland, she said, had been judged a success by almost every measure, and productivity had been maintained with happier staff. The chamber-of-commerce speaker pushed back. Those trials, he replied, were small and self-selected; forcing the change on small businesses could raise costs and reduce service hours. An audience member proposed the middle path nobody had mentioned: keep five contract days but cut meetings by half. Both speakers, perhaps unexpectedly, said they could live with that — which is usually the sign of a good compromise.", questions = listOf(Exercise(id = "en-listen-four-day-week-q1", kind = "choice", prompt = "What did both speakers agree on?", options = listOf("The problem: burnout", "The solution", "The costs", "Nothing"), answers = listOf("The problem: burnout"), explain = "They agreed on the problem and disagreed on nearly everything else."), Exercise(id = "en-listen-four-day-week-q2", kind = "written", prompt = "Which country's trials did the union representative mention?", options = listOf(), answers = listOf("iceland", "trials in iceland"), explain = "Trials in Iceland had been judged a success."), Exercise(id = "en-listen-four-day-week-q3", kind = "choice", prompt = "What was the counter-argument?", options = listOf("The trials were small and self-selected", "Workers don't want it", "It is illegal", "Productivity would double"), answers = listOf("The trials were small and self-selected"), explain = "He replied the trials were small and self-selected."), Exercise(id = "en-listen-four-day-week-q4", kind = "written", prompt = "What middle path did an audience member propose?", options = listOf(), answers = listOf("keep five days but cut meetings by half", "cut meetings by half", "five days with half the meetings"), explain = "Keep five contract days but cut meetings by half."), Exercise(id = "en-listen-four-day-week-q5", kind = "choice", prompt = "How did the speakers react to the compromise?", options = listOf("They said they could live with it", "They rejected it", "They laughed", "They left"), answers = listOf("They said they could live with it"), explain = "Both said they could live with it — a good compromise."), Exercise(id = "en-listen-four-day-week-q6", kind = "choice", prompt = "What does the passive voice of the report emphasise?", options = listOf("The trials and their judgement, not who judged them", "The speaker's anger", "The costs", "The audience"), answers = listOf("The trials and their judgement, not who judged them"), explain = "Had been judged a success — the doer doesn't matter.")), skills = listOf("listening:inference", "grammar:connectors", "function:express-opinion", "grammar:passive-intro")),
    ListeningText(id = "en-listen-negotiation-standoff", languageID = "en", title = "The salary standoff", level = "B2", topic = "work", unitID = "en-foundations-viewpoints", text = "'Let's start with the number you want, and I'll tell you honestly if it's possible,' said the manager. Nadia appreciated the directness. 'Forty-eight thousand — that's the market rate for this role, and I can show you three listings that prove it.' The manager didn't flinch. 'I believe you. If I approved that today, I'd have to rewrite three other salaries, and I don't have the budget for that this quarter.' 'What if we phased it?' Nadia offered. 'Forty-four now, a review in March with clear targets, and forty-eight if I hit them.' The manager was quiet for a moment. 'If you put those targets in writing and hit them, I'll defend that raise upstairs. Shall we say we have a deal?' Nadia smiled. 'We have a deal — in writing.'", questions = listOf(Exercise(id = "en-listen-negotiation-standoff-q1", kind = "written", prompt = "What salary did Nadia ask for?", options = listOf(), answers = listOf("forty-eight thousand", "48.000", "48000", "forty-eight thousand euros"), explain = "Forty-eight thousand — the market rate, she said."), Exercise(id = "en-listen-negotiation-standoff-q2", kind = "choice", prompt = "Why couldn't the manager approve it today?", options = listOf("He'd have to rewrite three other salaries", "She didn't deserve it", "It's illegal", "The company is closing"), answers = listOf("He'd have to rewrite three other salaries"), explain = "Approving it would force three rewrites — and there's no budget this quarter."), Exercise(id = "en-listen-negotiation-standoff-q3", kind = "written", prompt = "What was Nadia's phased proposal?", options = listOf(), answers = listOf("44 now and 48 in march with targets", "forty-four now a review in march and forty-eight if she hit targets", "44 now 48 later"), explain = "Forty-four now, review in March, forty-eight if she hits the targets."), Exercise(id = "en-listen-negotiation-standoff-q4", kind = "choice", prompt = "What condition did the manager add?", options = listOf("The targets in writing", "A six-month wait", "No review at all", "A different role"), answers = listOf("The targets in writing"), explain = "If the targets are in writing and hit, he'll defend the raise."), Exercise(id = "en-listen-negotiation-standoff-q5", kind = "choice", prompt = "Which negotiation move is 'What if we phased it?'", options = listOf("Offering a middle path", "Rejecting the deal", "Buying time", "Closing"), answers = listOf("Offering a middle path"), explain = "What if… proposes the middle path between the two positions."), Exercise(id = "en-listen-negotiation-standoff-q6", kind = "choice", prompt = "How did Nadia make sure the deal would hold?", options = listOf("She asked for it in writing", "She shook hands", "She lowered her ask", "She threatened to leave"), answers = listOf("She asked for it in writing"), explain = "'We have a deal — in writing.'")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:first-conditional")),
    ListeningText(id = "en-listen-news-desk", languageID = "en", title = "At the news desk", level = "B2", topic = "work", unitID = "en-foundations-media", text = "The 18:00 bulletin is being assembled at the news desk. The editor reads the running order aloud: 'Lead story: the city council has announced a new flood-prevention plan — measures are expected to cost four million euros, according to documents seen by our reporters. Second: the bridge is believed to be safe after emergency inspections; it is thought that traffic will return to normal by Monday. And the sports close: the match was postponed because the pitch was flooded — the third postponement this season.' A young reporter raises her hand. 'Should we say who saw the documents?' The editor shakes his head. 'We protect sources. The documents exist; the audience can decide what they mean.'", questions = listOf(Exercise(id = "en-listen-news-desk-q1", kind = "written", prompt = "What has the city council announced?", options = listOf(), answers = listOf("a new flood-prevention plan", "a flood-prevention plan"), explain = "A new flood-prevention plan."), Exercise(id = "en-listen-news-desk-q2", kind = "choice", prompt = "How is the cost being reported?", options = listOf("According to documents seen by reporters", "The council said it", "It is a rumour", "It is not mentioned"), answers = listOf("According to documents seen by reporters"), explain = "According to documents seen by our reporters."), Exercise(id = "en-listen-news-desk-q3", kind = "written", prompt = "What is believed about the bridge?", options = listOf(), answers = listOf("that it is safe", "it is believed to be safe", "it is safe"), explain = "It is believed to be safe after inspections."), Exercise(id = "en-listen-news-desk-q4", kind = "choice", prompt = "Why was the match postponed?", options = listOf("The pitch was flooded", "The teams were tired", "The bridge closed", "It wasn't"), answers = listOf("The pitch was flooded"), explain = "Postponed because the pitch was flooded."), Exercise(id = "en-listen-news-desk-q5", kind = "choice", prompt = "Why does the editor protect the source?", options = listOf("The audience can decide what the documents mean", "The documents are fake", "It is illegal", "He doesn't know the source"), answers = listOf("The audience can decide what the documents mean"), explain = "The documents exist; the audience decides."), Exercise(id = "en-listen-news-desk-q6", kind = "written", prompt = "How many postponements has the season had?", options = listOf(), answers = listOf("three", "3"), explain = "The third postponement this season.")), skills = listOf("grammar:passive-intro", "grammar:present-perfect", "function:talk-about-work")),
    ListeningText(id = "en-listen-bridge-news", languageID = "en", title = "The morning news: bridge reopened", level = "B2", topic = "town", unitID = "en-foundations-viewpoints", text = "Good morning. The Millbrook bridge, which was closed in March after cracks were discovered in two support beams, was reopened to traffic shortly after six this morning — three weeks ahead of schedule. Repair work, which was carried out by a local firm, was funded jointly by the council and the regional government, though the exact split has not been disclosed. Drivers are being asked to observe the fifty-kilometre limit for the first fortnight while the surface settles. Bus route nine, which was diverted via the ring road, returns to its original route today. And in a surprise twist, the ferry that was launched as a temporary replacement — will keep running until September, after commuters, apparently, fell in love with it.", questions = listOf(Exercise(id = "en-listen-bridge-news-q1", kind = "written", prompt = "When was the bridge reopened?", options = listOf(), answers = listOf("shortly after six this morning", "after six this morning", "this morning at six"), explain = "Reopened shortly after six this morning."), Exercise(id = "en-listen-bridge-news-q2", kind = "choice", prompt = "Why had it been closed?", options = listOf("Cracks were found in support beams", "A flood", "It was repainted", "An accident"), answers = listOf("Cracks were found in support beams"), explain = "Closed in March after cracks were discovered in two beams."), Exercise(id = "en-listen-bridge-news-q3", kind = "choice", prompt = "Who carried out the repairs?", options = listOf("A local firm", "The council itself", "The regional government", "It doesn't say"), answers = listOf("A local firm"), explain = "Carried out by a local firm — the passive keeps focus on the work."), Exercise(id = "en-listen-bridge-news-q4", kind = "written", prompt = "What are drivers asked to do for the first fortnight?", options = listOf(), answers = listOf("observe the fifty kilometre limit", "observe the 50 km limit", "drive at fifty"), explain = "Observe the 50 km/h limit while the surface settles."), Exercise(id = "en-listen-bridge-news-q5", kind = "choice", prompt = "What happens to the temporary ferry?", options = listOf("It keeps running until September", "It stops today", "It was cancelled", "It becomes permanent"), answers = listOf("It keeps running until September"), explain = "Commuters apparently fell in love with it."), Exercise(id = "en-listen-bridge-news-q6", kind = "choice", prompt = "Why does this report rely so heavily on the passive?", options = listOf("The doers matter less than the facts", "The doers are famous", "It is an error", "To hide the costs"), answers = listOf("The doers matter less than the facts"), explain = "News reports the event: was closed, was reopened, was carried out.")), skills = listOf("listening:connected-speech", "listening:detail", "grammar:passive-intro", "grammar:relative-clauses")),
    ListeningText(id = "en-listen-podcast-habits", languageID = "en", title = "Podcast: the habits episode", level = "B2", topic = "free time", unitID = "en-foundations-viewpoints", text = "HOST: Welcome back. Today, habits — the ones that stick and the ones that don't. With me, Dr Amaia Ruiz, who has spent a decade researching behaviour. Amaia, quick version: why do most New Year's resolutions fail? DR RUIZ: Because they're ambitions, not systems. People say 'I'll get fit' — that's a wish. A system is 'I run on Tuesdays with Sam.' HOST: So the friend is part of the system? DR RUIZ: The friend is the system. Accountability beats motivation roughly nine times out of ten in our data. HOST: Nine out of ten! And the two-minute rule everyone quotes? DR RUIZ: Useful, slightly overrated. Starting small matters less than starting at the same time. The clock does the remembering for you. HOST: One habit you'd recommend to everyone? DR RUIZ: A ten-minute walk after lunch. Boring, free, and — according to everything we know — the closest thing to a miracle we've measured.", questions = listOf(Exercise(id = "en-listen-podcast-habits-q1", kind = "choice", prompt = "Why do most resolutions fail, according to Dr Ruiz?", options = listOf("They're ambitions, not systems", "January is too cold", "People are lazy", "Gyms are expensive"), answers = listOf("They're ambitions, not systems"), explain = "'I'll get fit' is a wish; a system is 'I run on Tuesdays with Sam.'"), Exercise(id = "en-listen-podcast-habits-q2", kind = "written", prompt = "What beats motivation in her data?", options = listOf(), answers = listOf("accountability", "the friend", "accountability beats motivation"), explain = "Accountability beats motivation nine times out of ten."), Exercise(id = "en-listen-podcast-habits-q3", kind = "choice", prompt = "What does she think of the two-minute rule?", options = listOf("Useful, slightly overrated", "Completely wrong", "The best idea", "Dangerous"), answers = listOf("Useful, slightly overrated"), explain = "Starting small matters less than starting at the same time."), Exercise(id = "en-listen-podcast-habits-q4", kind = "written", prompt = "What does the clock do, according to Dr Ruiz?", options = listOf(), answers = listOf("the remembering for you", "does the remembering", "remembers for you"), explain = "The clock does the remembering for you."), Exercise(id = "en-listen-podcast-habits-q5", kind = "choice", prompt = "What habit does she recommend to everyone?", options = listOf("A ten-minute walk after lunch", "Running on Tuesdays", "Going to the gym", "Journaling"), answers = listOf("A ten-minute walk after lunch"), explain = "Boring, free, and the closest thing to a miracle they've measured."), Exercise(id = "en-listen-podcast-habits-q6", kind = "choice", prompt = "What makes this sound like a podcast rather than an essay?", options = listOf("The host's interruptions and quick exchanges", "The long sentences", "The passive voice", "The statistics only"), answers = listOf("The host's interruptions and quick exchanges"), explain = "Turn-taking, reactions and short questions are the podcast register.")), skills = listOf("listening:connected-speech", "listening:inference", "grammar:first-conditional", "function:talk-about-routines")),
    ListeningText(id = "en-listen-keynote", languageID = "en", title = "The keynote", level = "C1", topic = "work", unitID = "en-foundations-nuance", text = "Good afternoon. I'd like to begin with a confession: everything I believed about attention five years ago has aged badly. The research I'll present today — conducted across four countries, with the caveats that such breadth demands — suggests something uncomfortable: our capacity for sustained focus hasn't declined so much as our tolerance for discomfort has collapsed. Now, I appreciate that's a strong claim. The evidence runs like this. In conditions where devices were removed — not silenced, removed — reading comprehension recovered to pre-smartphone baselines within nine days. What participants reported, however, was not relief but a kind of withdrawal, which raises the question I'd like to leave you with: if a tool has rewritten our baseline for what feels bearable, is it a tool any more? I'll let you sit with that. Thank you.", questions = listOf(Exercise(id = "en-listen-keynote-q1", kind = "choice", prompt = "How does the speaker open the keynote?", options = listOf("With a confession", "With a joke", "With data", "With thanks"), answers = listOf("With a confession"), explain = "Everything I believed five years ago has aged badly — a confession opener."), Exercise(id = "en-listen-keynote-q2", kind = "written", prompt = "What has collapsed, according to the research?", options = listOf(), answers = listOf("Our tolerance for discomfort"), explain = "Not our focus — our tolerance for discomfort has collapsed."), Exercise(id = "en-listen-keynote-q3", kind = "choice", prompt = "How does she flag the strength of her claim?", options = listOf("Now, I appreciate that's a strong claim", "Obviously", "Everyone knows", "She doesn't"), answers = listOf("Now, I appreciate that's a strong claim"), explain = "Naming the claim's strength is the C1 move: hedge before you hit."), Exercise(id = "en-listen-keynote-q4", kind = "written", prompt = "What recovered within nine days when devices were removed?", options = listOf(), answers = listOf("reading comprehension", "comprehension recovered to pre-smartphone baselines", "reading"), explain = "Reading comprehension recovered to pre-smartphone baselines."), Exercise(id = "en-listen-keynote-q5", kind = "choice", prompt = "What did participants report feeling?", options = listOf("A kind of withdrawal", "Relief", "Nothing", "Happiness"), answers = listOf("A kind of withdrawal"), explain = "Not relief — a kind of withdrawal."), Exercise(id = "en-listen-keynote-q6", kind = "choice", prompt = "What is the closing question really about?", options = listOf("Whether a tool that rewrites our baseline is still a tool", "Device batteries", "Reading speed", "Four countries"), answers = listOf("Whether a tool that rewrites our baseline is still a tool"), explain = "She leaves the redefinition question with the audience.")), skills = listOf("listening:connected-speech", "listening:inference", "function:express-opinion", "grammar:connectors")),
    ListeningText(id = "en-listen-radio-debate", languageID = "en", title = "The radio debate", level = "C1", topic = "work", unitID = "en-foundations-nuance", text = "Radio phone-in, two guests, one question: should cities ban cars from their centres? The urbanist goes first: 'The evidence tends to support it. Air quality improves, shops report more foot traffic. I wouldn't say it solves everything — admittedly, delivery logistics need rethinking — but the direction is clear.' The taxi representative is unimpressed: 'That's a very comfortable position for someone with a parking space. It is often claimed that everyone supports these bans. My members do not.' The host steps in: 'Let me bring you both together. If — and at this stage it's an if — the city invested in night deliveries, would that change your position?' A long pause. 'It would certainly change mine,' the taxi man admits. The urbanist laughs: 'Then we have something to build on.'", questions = listOf(Exercise(id = "en-listen-radio-debate-q1", kind = "choice", prompt = "What is the urbanist's position?", options = listOf("The evidence tends to support the ban", "The ban solves everything", "The ban is tyranny", "She has no position"), answers = listOf("The evidence tends to support the ban"), explain = "Hedged: tends to support, not solves everything."), Exercise(id = "en-listen-radio-debate-q2", kind = "written", prompt = "What does the urbanist concede?", options = listOf(), answers = listOf("delivery logistics need rethinking", "deliveries are a problem"), explain = "Admittedly, delivery logistics need rethinking."), Exercise(id = "en-listen-radio-debate-q3", kind = "choice", prompt = "What does 'It is often claimed that everyone supports these bans' imply?", options = listOf("The claim is exaggerated", "Everyone supports them", "It is a fact", "Nobody supports them"), answers = listOf("The claim is exaggerated"), explain = "The passive + often claims distance the speaker from the claim."), Exercise(id = "en-listen-radio-debate-q4", kind = "written", prompt = "What is the host's conditional question?", options = listOf(), answers = listOf("if the city invested in night deliveries", "whether the city invested in night deliveries"), explain = "If the city invested in night deliveries, would positions change?"), Exercise(id = "en-listen-radio-debate-q5", kind = "choice", prompt = "How does the taxi man respond at the end?", options = listOf("It would certainly change mine", "Never", "He leaves", "He agrees fully"), answers = listOf("It would certainly change mine"), explain = "A conditional concession — something to build on."), Exercise(id = "en-listen-radio-debate-q6", kind = "choice", prompt = "What does the urbanist's laugh suggest?", options = listOf("A starting point for agreement", "She is mocking him", "She disagrees", "She is nervous"), answers = listOf("A starting point for agreement"), explain = "'Then we have something to build on.'")), skills = listOf("grammar:second-conditional", "function:negotiate", "grammar:connectors", "function:express-opinion"), exposureSkills = listOf("grammar:first-conditional")),
    ListeningText(id = "en-listen-viewpoint-interview", languageID = "en", title = "The viewpoint interview", level = "B2", topic = "work", unitID = "en-foundations-viewpoints", text = "Interviewer: 'You've argued that the five-day office week is obsolete. But many CEOs disagree.' Marta: 'They do, and I understand why. Commercial leases are expensive. Middle managers built careers on supervision. But the data — and I'd point to the Stanford study of sixteen thousand workers — shows remote workers are 13% more productive.' Interviewer: 'What about young employees who need mentorship?' Marta: 'Fair point. My answer is structured onboarding, not forced presence. You can mentor on Tuesday and Thursday without watching someone's desk on Monday.' Interviewer: 'If you were CEO of a Fortune 500, what would you do first?' Marta: 'I'd scrap the office policy entirely and rebuild it around outcomes, not hours.'", questions = listOf(Exercise(id = "en-listen-viewpoint-interview-q1", kind = "choice", prompt = "What does Marta argue?", options = listOf("The five-day office week is obsolete", "CEOs are always right", "Remote work is perfect", "Ban all offices"), answers = listOf("The five-day office week is obsolete"), explain = "She argues the five-day office week is obsolete."), Exercise(id = "en-listen-viewpoint-interview-q2", kind = "written", prompt = "What study does Marta cite?", options = listOf(), answers = listOf("the stanford study", "stanford"), explain = "The Stanford study of 16,000 workers."), Exercise(id = "en-listen-viewpoint-interview-q3", kind = "choice", prompt = "What does Marta propose instead of forced presence?", options = listOf("Structured onboarding", "More offices", "Higher salaries", "Fewer meetings"), answers = listOf("Structured onboarding"), explain = "Her answer is structured onboarding, not forced presence."), Exercise(id = "en-listen-viewpoint-interview-q4", kind = "written", prompt = "What would Marta do first as CEO?", options = listOf(), answers = listOf("scrap the office policy"), explain = "Scrap the office policy and rebuild around outcomes."), Exercise(id = "en-listen-viewpoint-interview-q5", kind = "choice", prompt = "What does Marta concede about young employees?", options = listOf("They need mentorship", "They are less productive", "They prefer offices", "They need more money"), answers = listOf("They need mentorship"), explain = "Fair point: young employees need mentorship."), Exercise(id = "en-listen-viewpoint-interview-q6", kind = "choice", prompt = "How does Marta handle the CEO hypothetical?", options = listOf("She gives a direct answer", "She refuses", "She laughs", "She changes topic"), answers = listOf("She gives a direct answer"), explain = "If I were CEO, I'd scrap the office policy — direct and structured.")), skills = listOf("grammar:second-conditional", "function:express-opinion", "grammar:connectors", "vocab:work"), exposureSkills = listOf("grammar:passive-intro")),
    ListeningText(id = "en-listen-hospital-stories", languageID = "en", title = "Stories from the ward", level = "B2", topic = "health", unitID = "en-foundations-viewpoints", text = "Nurse Rosa has worked the night shift for twelve years, and she's collected stories the way other people collect stamps. There was the man who sang opera to his IV drip — he said it was Puccini or nothing. And the woman who refused to sleep until she'd taught every nurse on the ward to make paella. 'It took three nights,' Rosa remembers. 'But the paella was excellent.' The hardest stories, she says, are the quiet ones — the patients who ask the same question over and over because they're more afraid of the answer than the illness. 'You answer it every time. That's the job. You answer, and you stay.'", questions = listOf(Exercise(id = "en-listen-hospital-stories-q1", kind = "choice", prompt = "How long has Rosa worked nights?", options = listOf("Twelve years", "Two years", "Twenty years", "Ten years"), answers = listOf("Twelve years"), explain = "Twelve years on the night shift."), Exercise(id = "en-listen-hospital-stories-q2", kind = "written", prompt = "What did the opera man sing to his IV drip?", options = listOf(), answers = listOf("puccini", "opera"), explain = "Puccini — or nothing."), Exercise(id = "en-listen-hospital-stories-q3", kind = "choice", prompt = "How many nights did the paella lesson take?", options = listOf("Three", "One", "Two", "Five"), answers = listOf("Three"), explain = "Three nights — but the paella was excellent."), Exercise(id = "en-listen-hospital-stories-q4", kind = "choice", prompt = "What are the hardest stories?", options = listOf("The quiet ones — patients afraid of the answer", "The loud ones", "The opera singers", "The long shifts"), answers = listOf("The quiet ones — patients afraid of the answer"), explain = "Patients afraid of the answer than the illness."), Exercise(id = "en-listen-hospital-stories-q5", kind = "written", prompt = "What is the job, according to Rosa?", options = listOf(), answers = listOf("answer and stay"), explain = "You answer, and you stay."), Exercise(id = "en-listen-hospital-stories-q6", kind = "choice", prompt = "What does Rosa collect?", options = listOf("Stories", "Stamps", "IV drips", "Recipes"), answers = listOf("Stories"), explain = "Stories, like others collect stamps.")), skills = listOf("listening:inference", "grammar:past-continuous", "function:talk-about-health", "vocab:health"), exposureSkills = listOf("grammar:used-to")),
    ListeningText(id = "en-listen-podcast-nuance", languageID = "en", title = "The nuance episode", level = "C1", topic = "work", unitID = "en-foundations-nuance", text = "HOST: You've written that 'nuance is the first casualty of urgency.' That's a great line — but what does it mean? AUTHOR: It means that when we're in a hurry, we flatten complex positions into for-and-against. And most interesting problems are neither. HOST: Give me an example. AUTHOR: Take remote work. The productive question isn't 'is it good or bad?' — it's 'which parts of which jobs benefit from which conditions?' That's a harder question, and the answer is boring: it depends. HOST: So nuance is just… saying it depends? AUTHOR: [laughs] No — it depends is where nuance starts, not where it ends. The next step is specifying: depends on what, for whom, under what conditions. HOST: And that's the book? AUTHOR: That's the book.", questions = listOf(Exercise(id = "en-listen-podcast-nuance-q1", kind = "choice", prompt = "What is the first casualty of urgency?", options = listOf("Nuance", "Data", "Humour", "Time"), answers = listOf("Nuance"), explain = "Nuance is the first casualty of urgency."), Exercise(id = "en-listen-podcast-nuance-q2", kind = "written", prompt = "What does urgency do to complex positions?", options = listOf(), answers = listOf("flattens them into for-and-against"), explain = "It flattens complex positions into for-and-against."), Exercise(id = "en-listen-podcast-nuance-q3", kind = "choice", prompt = "What's the productive question about remote work?", options = listOf("Which parts benefit from which conditions", "Is it good or bad", "Should everyone be remote", "Why do people hate it"), answers = listOf("Which parts benefit from which conditions"), explain = "Not good-or-bad, but which parts of which jobs benefit from which conditions."), Exercise(id = "en-listen-podcast-nuance-q4", kind = "written", prompt = "What's the boring answer?", options = listOf(), answers = listOf("it depends"), explain = "The answer is boring: it depends."), Exercise(id = "en-listen-podcast-nuance-q5", kind = "choice", prompt = "Where does nuance start and end?", options = listOf("Starts at it depends, ends with specification", "Starts with data", "Starts and ends with it depends", "Never starts"), answers = listOf("Starts at it depends, ends with specification"), explain = "It depends is where nuance starts; specifying conditions is where it goes."), Exercise(id = "en-listen-podcast-nuance-q6", kind = "choice", prompt = "What's the book about?", options = listOf("Specifying what nuance depends on", "Remote work", "Urgency", "Podcasts"), answers = listOf("Specifying what nuance depends on"), explain = "Depends on what, for whom, under what conditions.")), skills = listOf("listening:inference", "grammar:connectors", "function:express-opinion", "vocab:collocations")),
    ListeningText(id = "es-listen-cafe-morning", languageID = "es", title = "Un café antes del trabajo", level = "A1", topic = "rutina", unitID = "es-foundations-u1", text = "Cada mañana, Marta camina hasta una cafetería pequeña cerca de su piso. El camarero sabe su nombre, así que nunca tiene que pedir. Hoy se sienta junto a la ventana con un café y un croissant. Su autobús sale a las ocho y media, pero no está preocupada. La cafetería es muy tranquila a esta hora. Bebe su café despacio y mira cómo la ciudad despierta.", questions = listOf(Exercise(id = "es-listen-cafe-morning-q1", kind = "choice", prompt = "¿Adónde va Marta cada mañana?", options = listOf("A una cafetería pequeña", "A su oficina", "A la estación de autobuses", "A un parque"), answers = listOf("A una cafetería pequeña"), explain = "Camina hasta una cafetería pequeña cerca de su piso."), Exercise(id = "es-listen-cafe-morning-q2", kind = "choice", prompt = "¿Qué desayuna hoy?", options = listOf("Un café y un croissant", "Té y tostadas", "Zumo de naranja", "Nada"), answers = listOf("Un café y un croissant"), explain = "Se sienta junto a la ventana con un café y un croissant."), Exercise(id = "es-listen-cafe-morning-q3", kind = "written", prompt = "¿A qué hora sale su autobús?", options = listOf(), answers = listOf("a las ocho y media", "las ocho y media", "ocho y media"), explain = "Su autobús sale a las ocho y media."), Exercise(id = "es-listen-cafe-morning-q4", kind = "choice", prompt = "¿Cómo se siente con el tiempo?", options = listOf("No está preocupada", "Está muy tarde", "Está enfadada", "Tiene sueño"), answers = listOf("No está preocupada"), explain = "El texto dice que no está preocupada."), Exercise(id = "es-listen-cafe-morning-q5", kind = "choice", prompt = "¿Quién sabe su nombre?", options = listOf("El camarero", "El conductor del autobús", "Su jefe", "Un vecino"), answers = listOf("El camarero"), explain = "El camarero sabe su nombre, así que nunca tiene que pedir."), Exercise(id = "es-listen-cafe-morning-q6", kind = "written", prompt = "¿Dónde se sienta hoy?", options = listOf(), answers = listOf("junto a la ventana", "al lado de la ventana", "en la ventana"), explain = "Hoy se sienta junto a la ventana.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")),
    ListeningText(id = "es-listen-language-class", languageID = "es", title = "La clase de idiomas", level = "A1", topic = "presentaciones", unitID = "es-foundations-u1", text = "Marta asiste a su primera clase de portugués en un instituto pequeño. En la clase hay seis personas y todas quieren hablar. La profesora pide presentaciones. «Me llamo Marta y soy de Bolivia», dice una señora. «Yo soy Andrés, soy de Perú y trabajo en un restaurante», dice un chico joven. Marta también se presenta: «Soy Marta, soy de Argentina y soy enfermera». La profesora es de Madrid y enseña con mucho humor. Al final de la clase, los estudiantes intercambian números de teléfono. No son amigos todavía, pero la próxima semana van a tomar un café juntos y practicar.", questions = listOf(Exercise(id = "es-listen-language-class-q1", kind = "choice", prompt = "¿Cuántas personas hay en la clase?", options = listOf("Seis", "Tres", "Diez", "Catorce"), answers = listOf("Seis"), explain = "En la clase hay seis personas."), Exercise(id = "es-listen-language-class-q2", kind = "choice", prompt = "¿De dónde es Andrés?", options = listOf("De Perú", "De Bolivia", "De Argentina", "De México"), answers = listOf("De Perú"), explain = "Andrés es de Perú y trabaja en un restaurante."), Exercise(id = "es-listen-language-class-q3", kind = "choice", prompt = "¿Cuál es el trabajo de Marta?", options = listOf("Enfermera", "Profesora", "Camarera", "Estudiante"), answers = listOf("Enfermera"), explain = "Marta es de Argentina y es enfermera."), Exercise(id = "es-listen-language-class-q4", kind = "written", prompt = "¿De dónde es la profesora?", options = listOf(), answers = listOf("madrid", "de madrid", "es de madrid"), explain = "La profesora es de Madrid."), Exercise(id = "es-listen-language-class-q5", kind = "choice", prompt = "¿Qué hacen al final de la clase?", options = listOf("Intercambian números de teléfono", "Vuelven a casa solos", "Hacen un examen", "Cenan en un restaurante"), answers = listOf("Intercambian números de teléfono"), explain = "Los estudiantes intercambian números de teléfono."), Exercise(id = "es-listen-language-class-q6", kind = "written", prompt = "¿Qué van a hacer la próxima semana?", options = listOf(), answers = listOf("tomar un café", "van a tomar un café", "tomar un café juntos"), explain = "La próxima semana van a tomar un café juntos y practicar.")), skills = listOf("listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself")),
    ListeningText(id = "es-listen-little-sister", languageID = "es", title = "Mi hermana pequeña", level = "A1", topic = "familia", unitID = "es-foundations-u1", text = "Mi hermana pequeña se llama Carla y tiene nueve años. Es muy simpática y muy habladora. Carla no es callada: habla con todo el mundo, con los vecinos, con los profesores y con los perros del parque. Es rubia, como nuestra madre, y tiene los ojos marrones como mi padre. No es alta para su edad, pero es muy rápida y le encanta el fútbol. Su equipo no es muy bueno, pero a ella no le importa. «Yo no soy profesional», dice ella, «yo solo soy feliz con la pelota». Mi hermana es pequeña, pero su alegría es enorme.", questions = listOf(Exercise(id = "es-listen-little-sister-q1", kind = "choice", prompt = "¿Cuántos años tiene Carla?", options = listOf("Nueve", "Diecinueve", "Siete", "Diez"), answers = listOf("Nueve"), explain = "Carla tiene nueve años."), Exercise(id = "es-listen-little-sister-q2", kind = "choice", prompt = "¿Cómo es Carla?", options = listOf("Simpática y habladora", "Tímida y callada", "Seria", "Triste"), answers = listOf("Simpática y habladora"), explain = "Es muy simpática y muy habladora."), Exercise(id = "es-listen-little-sister-q3", kind = "written", prompt = "¿De qué color son sus ojos?", options = listOf(), answers = listOf("marrones", "marrón", "los ojos marrones"), explain = "Tiene los ojos marrones como su padre."), Exercise(id = "es-listen-little-sister-q4", kind = "choice", prompt = "¿Cómo es su pelo?", options = listOf("Rubio, como su madre", "Moreno, como su padre", "Pelirrojo", "Corto y negro"), answers = listOf("Rubio, como su madre"), explain = "Es rubia, como nuestra madre."), Exercise(id = "es-listen-little-sister-q5", kind = "choice", prompt = "¿Qué le encanta?", options = listOf("El fútbol", "La natación", "La música", "Los videojuegos"), answers = listOf("El fútbol"), explain = "Es muy rápida y le encanta el fútbol."), Exercise(id = "es-listen-little-sister-q6", kind = "written", prompt = "¿Cómo es su alegría?", options = listOf(), answers = listOf("enorme", "muy grande", "grande"), explain = "Su alegría es enorme.")), skills = listOf("listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family")),
    ListeningText(id = "es-listen-new-flatmate", languageID = "es", title = "Un nuevo compañero de piso", level = "A1", topic = "casa", unitID = "es-foundations-u1", text = "Tom tiene un compañero de piso nuevo. Se llama Leo y tiene veintitrés años. Leo viene de un pueblo pequeño del norte, pero ahora trabaja en la ciudad. Tiene dos cajas, una guitarra y una bicicleta. El piso tiene dos habitaciones y una cocina luminosa. Tom espera que a Leo le guste cocinar, porque a Tom no le gusta nada.", questions = listOf(Exercise(id = "es-listen-new-flatmate-q1", kind = "choice", prompt = "¿Cuántos años tiene Leo?", options = listOf("Veintitrés", "Treinta y dos", "Veinte", "Treinta"), answers = listOf("Veintitrés"), explain = "Leo tiene veintitrés años."), Exercise(id = "es-listen-new-flatmate-q2", kind = "choice", prompt = "¿Qué NO tiene Leo?", options = listOf("Un televisor", "Dos cajas", "Una guitarra", "Una bicicleta"), answers = listOf("Un televisor"), explain = "Tiene dos cajas, una guitarra y una bicicleta — sin televisor."), Exercise(id = "es-listen-new-flatmate-q3", kind = "written", prompt = "¿Qué odia hacer Tom?", options = listOf(), answers = listOf("cocinar", "odia cocinar", "tom odia cocinar"), explain = "A Tom no le gusta nada cocinar."), Exercise(id = "es-listen-new-flatmate-q4", kind = "choice", prompt = "¿Cómo es el piso?", options = listOf("Dos habitaciones y una cocina luminosa", "Un dormitorio y un balcón", "Un jardín", "Dos baños"), answers = listOf("Dos habitaciones y una cocina luminosa"), explain = "El piso tiene dos habitaciones y una cocina luminosa."), Exercise(id = "es-listen-new-flatmate-q5", kind = "choice", prompt = "¿Dónde trabaja Leo ahora?", options = listOf("En la ciudad", "En un pueblo", "En el norte", "No trabaja"), answers = listOf("En la ciudad"), explain = "Viene de un pueblo pequeño, pero ahora trabaja en la ciudad."), Exercise(id = "es-listen-new-flatmate-q6", kind = "written", prompt = "¿Qué instrumento tiene Leo?", options = listOf(), answers = listOf("una guitarra", "la guitarra", "guitarra"), explain = "Leo tiene una guitarra.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")),
    ListeningText(id = "es-listen-new-neighbour", languageID = "es", title = "La vecina nueva", level = "A1", topic = "gente", unitID = "es-foundations-u1", text = "En el edificio hay una vecina nueva. Se llama Amélie y es de Francia. No es estudiante; es fotógrafa. No trabaja en una oficina: trabaja en casa y viaja mucho. Los vecinos son curiosos, pero también son tímidos, así que no le hablan. Entonces, una mañana, Ben la encuentra en la puerta. «¿Eres tú la vecina nueva?», pregunta él. «Sí, soy yo», contesta ella, «y estoy contenta de estar aquí». Ahora son amigos, y ella ya no está sola en el edificio.", questions = listOf(Exercise(id = "es-listen-new-neighbour-q1", kind = "choice", prompt = "¿De dónde es Amélie?", options = listOf("De Francia", "De Italia", "De Japón", "De Brasil"), answers = listOf("De Francia"), explain = "Amélie es de Francia."), Exercise(id = "es-listen-new-neighbour-q2", kind = "choice", prompt = "¿Cuál es su trabajo?", options = listOf("Es fotógrafa", "Es estudiante", "Trabaja en una oficina", "Es profesora"), answers = listOf("Es fotógrafa"), explain = "No es estudiante; es fotógrafa."), Exercise(id = "es-listen-new-neighbour-q3", kind = "choice", prompt = "¿Trabaja en una oficina?", options = listOf("No, trabaja en casa", "Sí, todos los días", "Solo en verano", "No lo dice"), answers = listOf("No, trabaja en casa"), explain = "No trabaja en una oficina: trabaja en casa."), Exercise(id = "es-listen-new-neighbour-q4", kind = "written", prompt = "¿Por qué no le hablan los vecinos?", options = listOf(), answers = listOf("son tímidos", "porque son tímidos", "tímidos"), explain = "Son curiosos, pero también son tímidos."), Exercise(id = "es-listen-new-neighbour-q5", kind = "choice", prompt = "¿Dónde la encuentra Ben?", options = listOf("En la puerta", "En el ascensor", "En la calle", "En la cafetería"), answers = listOf("En la puerta"), explain = "Una mañana, Ben la encuentra en la puerta."), Exercise(id = "es-listen-new-neighbour-q6", kind = "written", prompt = "¿Cómo se siente Amélie al final?", options = listOf(), answers = listOf("contenta", "feliz", "está contenta"), explain = "Dice que está contenta de estar aquí.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")),
    ListeningText(id = "es-listen-sunday-market", languageID = "es", title = "El mercado del domingo", level = "A1", topic = "compras", unitID = "es-foundations-u1", text = "Los domingos hay un mercado en la plaza del pueblo. Ana y su padre van allí a las nueve, antes de que se llene. Compran fruta, pan y flores. Ana quiere unas fresas, pero su padre dice que esta semana son muy caras. Al final se llevan una bolsa grande de naranjas y unas rosas blancas para la mesa de la cocina.", questions = listOf(Exercise(id = "es-listen-sunday-market-q1", kind = "choice", prompt = "¿Cuándo van Ana y su padre al mercado?", options = listOf("A las nueve", "Al mediodía", "Por la tarde", "A las seis y media"), answers = listOf("A las nueve"), explain = "Van a las nueve, antes de que se llene."), Exercise(id = "es-listen-sunday-market-q2", kind = "written", prompt = "¿Por qué no compra Ana las fresas?", options = listOf(), answers = listOf("son muy caras", "muy caras", "porque son muy caras"), explain = "Su padre dice que son muy caras esta semana."), Exercise(id = "es-listen-sunday-market-q3", kind = "choice", prompt = "¿Qué se llevan a casa?", options = listOf("Naranjas y rosas", "Fresas y pan", "Manzanas y tulipanes", "Pan y queso"), answers = listOf("Naranjas y rosas"), explain = "Se llevan naranjas y rosas blancas."), Exercise(id = "es-listen-sunday-market-q4", kind = "choice", prompt = "¿Dónde está el mercado?", options = listOf("En la plaza del pueblo", "Junto al río", "En la estación", "En un supermercado"), answers = listOf("En la plaza del pueblo"), explain = "Hay un mercado en la plaza del pueblo los domingos."), Exercise(id = "es-listen-sunday-market-q5", kind = "choice", prompt = "¿Qué compran?", options = listOf("Fruta, pan y flores", "Pescado y verduras", "Queso y carne", "Solo flores"), answers = listOf("Fruta, pan y flores"), explain = "Compran fruta, pan y flores."), Exercise(id = "es-listen-sunday-market-q6", kind = "written", prompt = "¿Qué quiere Ana?", options = listOf(), answers = listOf("fresas", "unas fresas", "quiere fresas"), explain = "Ana quiere unas fresas.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")),
    ListeningText(id = "es-listen-piso-elegido", languageID = "es", title = "El piso elegido", level = "A2", topic = "pisos", unitID = "es-foundations-u7", text = "Lucía y Pablo buscan piso en la app. El primero es más barato, pero está peor situado: a cuarenta minutos del centro. El segundo cuesta cien euros más al mes, pero es más luminoso y tiene balcón. Lucía opina que la luz es lo más importante, porque trabaja desde casa. Al final deciden pedir visita al segundo: es más caro, pero es el mejor de los dos para ellos.", questions = listOf(Exercise(id = "es-listen-piso-elegido-q1", kind = "choice", prompt = "¿Cuántos pisos comparan?", options = listOf("Dos", "Tres", "Cuatro"), answers = listOf("Dos"), explain = "Comparan dos pisos en la app."), Exercise(id = "es-listen-piso-elegido-q2", kind = "choice", prompt = "¿Qué problema tiene el más barato?", options = listOf("Está lejos del centro", "No tiene balcón", "Es muy caro", "Es pequeño"), answers = listOf("Está lejos del centro"), explain = "A cuarenta minutos del centro."), Exercise(id = "es-listen-piso-elegido-q3", kind = "written", prompt = "¿Cuánto cuesta más el segundo al mes?", options = listOf(), answers = listOf("cien euros", "100 euros"), explain = "Cuesta cien euros más al mes."), Exercise(id = "es-listen-piso-elegido-q4", kind = "choice", prompt = "¿Qué es lo más importante para Lucía?", options = listOf("La luz", "El precio", "El balcón", "La cocina"), answers = listOf("La luz"), explain = "Trabaja desde casa y la luz es lo más importante."), Exercise(id = "es-listen-piso-elegido-q5", kind = "choice", prompt = "¿Qué deciden al final?", options = listOf("Pedir visita al segundo", "Quedarse con el primero", "Seguir buscando", "Pedir descuento"), answers = listOf("Pedir visita al segundo"), explain = "Deciden pedir visita al segundo."), Exercise(id = "es-listen-piso-elegido-q6", kind = "written", prompt = "¿Para quién es el mejor?", options = listOf(), answers = listOf("para ellos"), explain = "Es el mejor de los dos para ellos.")), skills = listOf("listening:gist", "listening:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")),
    ListeningText(id = "es-listen-plan-sabado", languageID = "es", title = "El sábado, organizado", level = "A2", topic = "planes", unitID = "es-foundations-u7", text = "Elena llama a su hermano para organizar el sábado. Él propone ir a la montaña, pero va a llover, así que Elena sugiere el museo nuevo. Van a quedar a las diez en la entrada principal y van a comer en el mercado de al lado, que es más barato que los restaurantes del centro. Por la noche no tienen plan: van a decidir sobre la marcha, cuando sepan qué tiempo hace.", questions = listOf(Exercise(id = "es-listen-plan-sabado-q1", kind = "choice", prompt = "¿Quién propone la montaña?", options = listOf("El hermano", "Elena", "Su madre", "Un amigo"), answers = listOf("El hermano"), explain = "Su hermano propone ir a la montaña."), Exercise(id = "es-listen-plan-sabado-q2", kind = "choice", prompt = "¿Por qué no van a la montaña?", options = listOf("Va a llover", "Están cansados", "El museo es gratis", "La montaña está lejos"), answers = listOf("Va a llover"), explain = "Va a llover, así que van al museo."), Exercise(id = "es-listen-plan-sabado-q3", kind = "written", prompt = "¿A qué hora van a quedar?", options = listOf(), answers = listOf("a las diez", "las diez"), explain = "Van a quedar a las diez."), Exercise(id = "es-listen-plan-sabado-q4", kind = "choice", prompt = "¿Dónde van a comer?", options = listOf("En el mercado de al lado", "En un restaurante del centro", "En casa", "En el museo"), answers = listOf("En el mercado de al lado"), explain = "Es más barato que los restaurantes del centro."), Exercise(id = "es-listen-plan-sabado-q5", kind = "choice", prompt = "¿Qué van a hacer por la noche?", options = listOf("Decidir sobre la marcha", "Ir al cine", "Volver temprano", "Quedar con amigos"), answers = listOf("Decidir sobre la marcha"), explain = "Van a decidir cuando sepan el tiempo.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("grammar:future-forms")),
    ListeningText(id = "es-listen-primera-vez", languageID = "es", title = "Cosas que no he hecho", level = "B1", topic = "viajes", unitID = "es-foundations-u5", text = "En la cocina de un hostal, tres viajeros comparan vidas. Diego ha visitado veinte países, pero nunca ha aprendido a nadar: «Lo sé, es ridículo». Valeria ha buceado dos veces con tortugas, pero no ha salido de América Latina hasta este viaje. Y Marta, que lleva seis años en la carretera, nunca ha volado: cruza los océanos en barco y las fronteras en autobús. «¿Nunca?», pregunta Diego. «Nunca. El miedo es más viejo que yo.» Se ríen de lo que no han hecho, y Marta dice algo que se quedan todos: «No hace falta haberlo hecho todo. Basta con seguir queriendo».", questions = listOf(Exercise(id = "es-listen-primera-vez-q1", kind = "choice", prompt = "¿Qué no ha hecho nunca Diego?", options = listOf("Aprender a nadar", "Visitar veinte países", "Cruzar en barco", "Salir de América"), answers = listOf("Aprender a nadar"), explain = "Ha visitado veinte países, pero nunca ha aprendido a nadar."), Exercise(id = "es-listen-primera-vez-q2", kind = "written", prompt = "¿Cuántas veces ha buceado Valeria?", options = listOf(), answers = listOf("dos veces", "2 veces", "dos"), explain = "Valeria ha buceado dos veces con tortugas."), Exercise(id = "es-listen-primera-vez-q3", kind = "choice", prompt = "¿Cómo cruza Marta los océanos?", options = listOf("En barco", "En avión", "En autobús", "A pie"), answers = listOf("En barco"), explain = "Cruza los océanos en barco y las fronteras en autobús."), Exercise(id = "es-listen-primera-vez-q4", kind = "choice", prompt = "¿Qué dice Marta sobre el miedo?", options = listOf("Es más viejo que ella", "Es más joven que ella", "Es ridículo", "Se ha ido"), answers = listOf("Es más viejo que ella"), explain = "El miedo es más viejo que yo."), Exercise(id = "es-listen-primera-vez-q5", kind = "written", prompt = "¿Qué basta, según Marta?", options = listOf(), answers = listOf("seguir queriendo", "con seguir queriendo"), explain = "Basta con seguir queriendo."), Exercise(id = "es-listen-primera-vez-q6", kind = "choice", prompt = "¿Cómo reaccionan los tres?", options = listOf("Se ríen", "Se enfadan", "Se van", "Lloran"), answers = listOf("Se ríen"), explain = "Se ríen de lo que no han hecho.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")),
    ListeningText(id = "es-listen-cambio-pueblo", languageID = "es", title = "De la ciudad al pueblo", level = "B1", topic = "cambios", unitID = "es-foundations-u5", text = "Nacho explica por qué dejó Madrid. Antes vivía en un piso pequeño y trabajaba once horas al día: «Ganaba bien, pero no tenía vida». Un invierno se puso enfermo, y entonces entendió que algo tenía que cambiar. Ahora vive en un pueblo de mil habitantes, trabaja desde casa por las mañanas y cultiva un huerto por las tardes. «Gano menos, pero me sobra tiempo.» Al principio sus padres no lo entendían; ahora vienen cada mes. «¿Te arrepientes de algo?», le pregunta su amiga. «De no haberlo hecho antes».", questions = listOf(Exercise(id = "es-listen-cambio-pueblo-q1", kind = "choice", prompt = "¿Dónde vivía Nacho antes?", options = listOf("En Madrid", "En un pueblo", "En Barcelona", "En un hostal"), answers = listOf("En Madrid"), explain = "Nacho explica por qué dejó Madrid."), Exercise(id = "es-listen-cambio-pueblo-q2", kind = "written", prompt = "¿Cuántas horas trabajaba al día?", options = listOf(), answers = listOf("once horas", "11 horas", "once"), explain = "Trabajaba once horas al día."), Exercise(id = "es-listen-cambio-pueblo-q3", kind = "choice", prompt = "¿Qué le hizo cambiar?", options = listOf("Se puso enfermo", "Perdió el trabajo", "Ganó la lotería", "Conoció a alguien"), answers = listOf("Se puso enfermo"), explain = "Un invierno se puso enfermo, y entonces entendió que tenía que cambiar."), Exercise(id = "es-listen-cambio-pueblo-q4", kind = "choice", prompt = "¿Qué hace por las tardes ahora?", options = listOf("Cultiva un huerto", "Trabaja más horas", "Viaja cada mes", "Estudia"), answers = listOf("Cultiva un huerto"), explain = "Trabaja desde casa por las mañanas y cultiva un huerto por las tardes."), Exercise(id = "es-listen-cambio-pueblo-q5", kind = "written", prompt = "¿Qué se arrepiente Nacho?", options = listOf(), answers = listOf("de no haberlo hecho antes", "no haberlo hecho antes"), explain = "«De no haberlo hecho antes».")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions")),
    ListeningText(id = "es-listen-regateo-mesa", languageID = "es", title = "El regateo de la mesa", level = "B2", topic = "negocios", unitID = "es-foundations-u8", text = "En una app de segunda mano, Clara quiere una mesa de madera que cuesta 80 euros. « ¿Y si nos viéramos en 60 ? », propone ella. El vendedor no acepta: « Solo si te la llevas hoy ». Clara lo piensa: « Te daría 65 si incluyes la silla ». « Imposible », ríe él, « pero te dejaría la mesa en 70 y te la subiría al piso ». Clara no lo duda: « ¿La subirías tú sola ? ». « Tengo un carro », responde. « Trato hecho », dice ella, y añade: « Si me gusta tanto como en la foto, te dejo una reseña de cinco estrellas ».", questions = listOf(Exercise(id = "es-listen-regateo-mesa-q1", kind = "choice", prompt = "¿Cuánto pide el vendedor por la mesa ?", options = listOf("80 euros", "60 euros", "70 euros", "65 euros"), answers = listOf("80 euros"), explain = "La mesa cuesta 80 euros."), Exercise(id = "es-listen-regateo-mesa-q2", kind = "written", prompt = "¿Qué propone Clara primero ?", options = listOf(), answers = listOf("60 euros", "sesenta euros", "nos vieramos en 60", "nos viéramos en 60"), explain = "« ¿Y si nos viéramos en 60 ? »."), Exercise(id = "es-listen-regateo-mesa-q3", kind = "choice", prompt = "¿Qué condición pone el vendedor ?", options = listOf("Llevarla hoy", "Pagar en efectivo", "Añadir una reseña", "Volver mañana"), answers = listOf("Llevarla hoy"), explain = "« Solo si te la llevas hoy »."), Exercise(id = "es-listen-regateo-mesa-q4", kind = "choice", prompt = "¿Qué ofrece el vendedor por 70 ?", options = listOf("Subirle la mesa al piso", "Añadir la silla", "Bajar a 60", "Darle un carro"), answers = listOf("Subirle la mesa al piso"), explain = "« Te la subiría al piso »."), Exercise(id = "es-listen-regateo-mesa-q5", kind = "written", prompt = "¿Qué promete Clara si le gusta ?", options = listOf(), answers = listOf("una resena de cinco estrellas", "una reseña de cinco estrellas", "resena cinco estrellas"), explain = "Una reseña de cinco estrellas.")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors")),
    ListeningText(id = "es-listen-noticia-barrio", languageID = "es", title = "La noticia del barrio", level = "B2", topic = "noticias", unitID = "es-foundations-u9", text = "En el mercado, Ana y Luis comentan lo que se dice. « Se dice que van a peatonalizar la calle Mayor », cuenta Ana. « ¿Otra vez ? », se ríe Luis. « La noticia que leí dice que empiezan en primavera ». Según el ayuntamiento, serían solo los sábados, pero los comerciantes, cuyo negocio dependería del turismo, ya se han manifestado. « Es cierto que bajaría el ruido », reconoce Luis, « pero, ¿y el aparcamiento ? ». Ana defiende la medida: « Por un lado, más gente caminaría; por otro, los autobuses llegarían a la puerta ». Se quedan sin resolverlo, pero prometen volver a hablarlo cuando se publique el plan.", questions = listOf(Exercise(id = "es-listen-noticia-barrio-q1", kind = "choice", prompt = "¿Qué se dice de la calle Mayor ?", options = listOf("Que la peatonalizarán", "Que la ampliarán", "Que la cerrarán", "Que cambiará de nombre"), answers = listOf("Que la peatonalizarán"), explain = "« Se dice que van a peatonalizar la calle Mayor »."), Exercise(id = "es-listen-noticia-barrio-q2", kind = "written", prompt = "¿Cuándo empezarían ?", options = listOf(), answers = listOf("en primavera", "primavera"), explain = "« La noticia que leí dice que empiezan en primavera »."), Exercise(id = "es-listen-noticia-barrio-q3", kind = "choice", prompt = "¿Qué dice el ayuntamiento ?", options = listOf("Solo los sábados", "Todos los días", "Solo en verano", "Los festivos"), answers = listOf("Solo los sábados"), explain = "Según el ayuntamiento, serían solo los sábados."), Exercise(id = "es-listen-noticia-barrio-q4", kind = "choice", prompt = "¿Quién se ha manifestado ?", options = listOf("Los comerciantes", "Los vecinos", "Los taxistas", "El ayuntamiento"), answers = listOf("Los comerciantes"), explain = "Los comerciantes ya se han manifestado."), Exercise(id = "es-listen-noticia-barrio-q5", kind = "written", prompt = "¿Qué prometen Ana y Luis ?", options = listOf(), answers = listOf("volver a hablarlo", "hablarlo otra vez", "volverlo a hablar"), explain = "Prometen volver a hablarlo cuando se publique el plan.")), skills = listOf("listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors")),
    ListeningText(id = "fr-listen-cafe-morning", languageID = "fr", title = "Un café avant le travail", level = "A1", topic = "routine", unitID = "fr-foundations-u1", text = "Chaque matin, Marta marche jusqu'à un petit café près de chez elle. Le serveur connaît son nom, alors elle n'a jamais besoin de commander. Aujourd'hui, elle s'assoit près de la fenêtre avec un café et un croissant. Son bus part à huit heures et demie, mais elle ne s'inquiète pas. Le café est très calme à cette heure-là. Elle boit son café lentement et regarde la ville se réveiller.", questions = listOf(Exercise(id = "fr-listen-cafe-morning-q1", kind = "choice", prompt = "Où Marta va-t-elle chaque matin ?", options = listOf("Dans un petit café", "À son bureau", "À la gare routière", "Dans un parc"), answers = listOf("Dans un petit café"), explain = "Elle marche jusqu'à un petit café près de chez elle."), Exercise(id = "fr-listen-cafe-morning-q2", kind = "choice", prompt = "Qu'est-ce qu'elle prend ce matin ?", options = listOf("Un café et un croissant", "Un thé et des toasts", "Du jus d'orange", "Rien"), answers = listOf("Un café et un croissant"), explain = "Elle s'assoit avec un café et un croissant."), Exercise(id = "fr-listen-cafe-morning-q3", kind = "written", prompt = "À quelle heure part son bus ?", options = listOf(), answers = listOf("à huit heures et demie", "huit heures et demie", "huit heures et demi"), explain = "Son bus part à huit heures et demie."), Exercise(id = "fr-listen-cafe-morning-q4", kind = "choice", prompt = "Comment se sent-elle par rapport à l'heure ?", options = listOf("Elle ne s'inquiète pas", "Elle est très en retard", "Elle est fâchée", "Elle a sommeil"), answers = listOf("Elle ne s'inquiète pas"), explain = "Le texte dit qu'elle ne s'inquiète pas."), Exercise(id = "fr-listen-cafe-morning-q5", kind = "choice", prompt = "Qui connaît son nom ?", options = listOf("Le serveur", "Le conducteur du bus", "Son patron", "Un voisin"), answers = listOf("Le serveur"), explain = "Le serveur connaît son nom, alors elle n'a jamais besoin de commander."), Exercise(id = "fr-listen-cafe-morning-q6", kind = "written", prompt = "Où s'assoit-elle aujourd'hui ?", options = listOf(), answers = listOf("près de la fenêtre", "à côté de la fenêtre", "vers la fenêtre"), explain = "Aujourd'hui, elle s'assoit près de la fenêtre.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")),
    ListeningText(id = "fr-listen-language-class", languageID = "fr", title = "Le cours de langue", level = "A1", topic = "présentations", unitID = "fr-foundations-u1", text = "Marta assiste à son premier cours de portugais dans un petit institut. Dans la classe, il y a six personnes et tout le monde veut parler. La professeure demande les présentations. « Je m'appelle Marta et je suis de Bolivie », dit une dame. « Moi, c'est Andrés, je suis du Pérou et je travaille dans un restaurant », dit un jeune homme. Marta se présente aussi : « Je suis Marta, je suis argentine et je suis infirmière. » La professeure est de Madrid et elle enseigne avec beaucoup d'humour. À la fin du cours, les étudiants échangent leurs numéros de téléphone. Ils ne sont pas encore amis, mais la semaine prochaine, ils vont prendre un café ensemble et pratiquer.", questions = listOf(Exercise(id = "fr-listen-language-class-q1", kind = "choice", prompt = "Combien de personnes y a-t-il dans la classe ?", options = listOf("Six", "Trois", "Dix", "Quatorze"), answers = listOf("Six"), explain = "Dans la classe, il y a six personnes."), Exercise(id = "fr-listen-language-class-q2", kind = "choice", prompt = "D'où vient Andrés ?", options = listOf("Du Pérou", "De Bolivie", "D'Argentine", "Du Mexique"), answers = listOf("Du Pérou"), explain = "Andrés vient du Pérou et il travaille dans un restaurant."), Exercise(id = "fr-listen-language-class-q3", kind = "choice", prompt = "Quel est le métier de Marta ?", options = listOf("Infirmière", "Professeure", "Serveuse", "Étudiante"), answers = listOf("Infirmière"), explain = "Marta est argentine et elle est infirmière."), Exercise(id = "fr-listen-language-class-q4", kind = "written", prompt = "De quelle ville est la professeure ?", options = listOf(), answers = listOf("madrid", "de madrid", "elle est de madrid"), explain = "La professeure est de Madrid."), Exercise(id = "fr-listen-language-class-q5", kind = "choice", prompt = "Que font-ils à la fin du cours ?", options = listOf("Ils échangent leurs numéros de téléphone", "Ils rentrent seuls", "Ils font un examen", "Ils dînent au restaurant"), answers = listOf("Ils échangent leurs numéros de téléphone"), explain = "Les étudiants échangent leurs numéros de téléphone."), Exercise(id = "fr-listen-language-class-q6", kind = "written", prompt = "Que vont-ils faire la semaine prochaine ?", options = listOf(), answers = listOf("prendre un café", "ils vont prendre un café", "prendre un café ensemble"), explain = "La semaine prochaine, ils vont prendre un café ensemble et pratiquer.")), skills = listOf("listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself")),
    ListeningText(id = "fr-listen-little-sister", languageID = "fr", title = "Ma petite sœur", level = "A1", topic = "famille", unitID = "fr-foundations-u1", text = "Ma petite sœur s'appelle Carla et elle a neuf ans. Elle est très gentille et très bavarde. Carla n'est pas discrète : elle parle avec tout le monde, avec les voisins, avec les professeurs et avec les chiens du parc. Elle est blonde, comme notre mère, et elle a les yeux marron comme mon père. Elle n'est pas grande pour son âge, mais elle est très rapide et elle adore le football. Son équipe n'est pas très bonne, mais cela ne la dérange pas. « Je ne suis pas professionnelle », dit-elle, « moi, je suis juste heureuse avec le ballon ». Ma sœur est petite, mais sa joie est énorme.", questions = listOf(Exercise(id = "fr-listen-little-sister-q1", kind = "choice", prompt = "Quel âge a Carla ?", options = listOf("Neuf ans", "Dix-neuf ans", "Sept ans", "Dix ans"), answers = listOf("Neuf ans"), explain = "Carla a neuf ans."), Exercise(id = "fr-listen-little-sister-q2", kind = "choice", prompt = "Comment est Carla ?", options = listOf("Gentille et bavarde", "Timide et discrète", "Sérieuse", "Triste"), answers = listOf("Gentille et bavarde"), explain = "Elle est très gentille et très bavarde."), Exercise(id = "fr-listen-little-sister-q3", kind = "written", prompt = "De quelle couleur sont ses yeux ?", options = listOf(), answers = listOf("marron", "les yeux marron", "marron comme son père"), explain = "Elle a les yeux marron comme son père."), Exercise(id = "fr-listen-little-sister-q4", kind = "choice", prompt = "Comment sont ses cheveux ?", options = listOf("Blonds, comme sa mère", "Bruns, comme son père", "Roux", "Courts et noirs"), answers = listOf("Blonds, comme sa mère"), explain = "Elle est blonde, comme notre mère."), Exercise(id = "fr-listen-little-sister-q5", kind = "choice", prompt = "Qu'est-ce qu'elle adore ?", options = listOf("Le football", "La natation", "La musique", "Les jeux vidéo"), answers = listOf("Le football"), explain = "Elle est très rapide et elle adore le football."), Exercise(id = "fr-listen-little-sister-q6", kind = "written", prompt = "Comment est sa joie ?", options = listOf(), answers = listOf("énorme", "très grande", "grande"), explain = "Sa joie est énorme.")), skills = listOf("listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family")),
    ListeningText(id = "fr-listen-new-flatmate", languageID = "fr", title = "Un nouveau colocataire", level = "A1", topic = "maison", unitID = "fr-foundations-u1", text = "Tom a un nouveau colocataire. Il s'appelle Léo et il a vingt-trois ans. Léo vient d'une petite ville du nord, mais il travaille maintenant en ville. Il a deux cartons, une guitare et un vélo. L'appartement a deux chambres et une cuisine très lumineuse. Tom espère que Léo aime cuisiner, parce que Tom, lui, déteste ça.", questions = listOf(Exercise(id = "fr-listen-new-flatmate-q1", kind = "choice", prompt = "Quel âge a Léo ?", options = listOf("Vingt-trois ans", "Trente-deux ans", "Vingt ans", "Trente ans"), answers = listOf("Vingt-trois ans"), explain = "Léo a vingt-trois ans."), Exercise(id = "fr-listen-new-flatmate-q2", kind = "choice", prompt = "Qu'est-ce que Léo n'a PAS ?", options = listOf("Une télévision", "Deux cartons", "Une guitare", "Un vélo"), answers = listOf("Une télévision"), explain = "Il a deux cartons, une guitare et un vélo — pas de télévision."), Exercise(id = "fr-listen-new-flatmate-q3", kind = "written", prompt = "Qu'est-ce que Tom déteste faire ?", options = listOf(), answers = listOf("cuisiner", "il déteste cuisiner", "tom déteste cuisiner"), explain = "Tom déteste cuisiner."), Exercise(id = "fr-listen-new-flatmate-q4", kind = "choice", prompt = "Comment est l'appartement ?", options = listOf("Deux chambres et une cuisine lumineuse", "Une chambre et un balcon", "Un jardin", "Deux salles de bain"), answers = listOf("Deux chambres et une cuisine lumineuse"), explain = "L'appartement a deux chambres et une cuisine très lumineuse."), Exercise(id = "fr-listen-new-flatmate-q5", kind = "choice", prompt = "Où Léo travaille-t-il maintenant ?", options = listOf("En ville", "Dans un petit village", "Dans le nord", "Il ne travaille pas"), answers = listOf("En ville"), explain = "Il vient d'une petite ville du nord, mais il travaille maintenant en ville."), Exercise(id = "fr-listen-new-flatmate-q6", kind = "written", prompt = "Quel instrument Léo a-t-il ?", options = listOf(), answers = listOf("une guitare", "la guitare", "guitare"), explain = "Léo a une guitare.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")),
    ListeningText(id = "fr-listen-new-neighbour", languageID = "fr", title = "La nouvelle voisine", level = "A1", topic = "gens", unitID = "fr-foundations-u1", text = "Dans l'immeuble, il y a une nouvelle voisine. Elle s'appelle Amélie et elle est de France. Elle n'est pas étudiante ; elle est photographe. Elle ne travaille pas dans un bureau : elle travaille chez elle et elle voyage beaucoup. Les voisins sont curieux, mais ils sont aussi timides, alors ils ne lui parlent pas. Puis, un matin, Ben la rencontre à la porte. « C'est vous, la nouvelle voisine ? », demande-t-il. « Oui, c'est moi », répond-elle, « et je suis contente d'être ici. » Maintenant, ils sont amis, et elle n'est plus seule dans l'immeuble.", questions = listOf(Exercise(id = "fr-listen-new-neighbour-q1", kind = "choice", prompt = "D'où vient Amélie ?", options = listOf("De France", "D'Italie", "Du Japon", "Du Brésil"), answers = listOf("De France"), explain = "Amélie est de France."), Exercise(id = "fr-listen-new-neighbour-q2", kind = "choice", prompt = "Quel est son métier ?", options = listOf("Photographe", "Étudiante", "Employée de bureau", "Professeure"), answers = listOf("Photographe"), explain = "Elle n'est pas étudiante ; elle est photographe."), Exercise(id = "fr-listen-new-neighbour-q3", kind = "choice", prompt = "Travaille-t-elle dans un bureau ?", options = listOf("Non, elle travaille chez elle", "Oui, tous les jours", "Seulement en été", "Elle ne le dit pas"), answers = listOf("Non, elle travaille chez elle"), explain = "Elle ne travaille pas dans un bureau : elle travaille chez elle."), Exercise(id = "fr-listen-new-neighbour-q4", kind = "written", prompt = "Pourquoi les voisins ne lui parlent-ils pas ?", options = listOf(), answers = listOf("ils sont timides", "parce qu'ils sont timides", "timides"), explain = "Ils sont curieux, mais ils sont aussi timides."), Exercise(id = "fr-listen-new-neighbour-q5", kind = "choice", prompt = "Où Ben la rencontre-t-il ?", options = listOf("À la porte", "Dans l'ascenseur", "Dans la rue", "Au café"), answers = listOf("À la porte"), explain = "Un matin, Ben la rencontre à la porte."), Exercise(id = "fr-listen-new-neighbour-q6", kind = "written", prompt = "Comment Amélie se sent-elle à la fin ?", options = listOf(), answers = listOf("contente", "heureuse", "elle est contente"), explain = "Elle dit qu'elle est contente d'être ici.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")),
    ListeningText(id = "fr-listen-sunday-market", languageID = "fr", title = "Le marché du dimanche", level = "A1", topic = "achats", unitID = "fr-foundations-u1", text = "Le dimanche, il y a un marché sur la place du village. Anna et son père y vont à neuf heures, avant que ce soit trop bondé. Ils achètent des fruits, du pain et des fleurs. Anna veut des fraises, mais son père dit qu'elles sont trop chères cette semaine. À la fin, ils rentrent avec un grand sac d'oranges et des roses blanches pour la table de la cuisine.", questions = listOf(Exercise(id = "fr-listen-sunday-market-q1", kind = "choice", prompt = "Quand Anna et son père vont-ils au marché ?", options = listOf("À neuf heures", "À midi", "Dans l'après-midi", "À six heures et demie"), answers = listOf("À neuf heures"), explain = "Ils y vont à neuf heures, avant que ce soit trop bondé."), Exercise(id = "fr-listen-sunday-market-q2", kind = "written", prompt = "Pourquoi Anna n'a-t-elle pas de fraises ?", options = listOf(), answers = listOf("elles sont trop chères", "trop chères", "parce qu'elles sont trop chères"), explain = "Son père dit qu'elles sont trop chères cette semaine."), Exercise(id = "fr-listen-sunday-market-q3", kind = "choice", prompt = "Qu'est-ce qu'ils ramènent à la maison ?", options = listOf("Des oranges et des roses", "Des fraises et du pain", "Des pommes et des tulipes", "Du pain et du fromage"), answers = listOf("Des oranges et des roses"), explain = "Ils rentrent avec des oranges et des roses blanches."), Exercise(id = "fr-listen-sunday-market-q4", kind = "choice", prompt = "Où est le marché ?", options = listOf("Sur la place du village", "Près de la rivière", "À la gare", "Dans un supermarché"), answers = listOf("Sur la place du village"), explain = "Il y a un marché sur la place du village le dimanche."), Exercise(id = "fr-listen-sunday-market-q5", kind = "choice", prompt = "Qu'est-ce qu'ils achètent ?", options = listOf("Des fruits, du pain et des fleurs", "Du poisson et des légumes", "Du fromage et de la viande", "Uniquement des fleurs"), answers = listOf("Des fruits, du pain et des fleurs"), explain = "Ils achètent des fruits, du pain et des fleurs."), Exercise(id = "fr-listen-sunday-market-q6", kind = "written", prompt = "Qu'est-ce qu'Anna veut ?", options = listOf(), answers = listOf("des fraises", "les fraises", "elle veut des fraises"), explain = "Anna veut des fraises.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")),
    ListeningText(id = "fr-listen-appart-choisi", languageID = "fr", title = "L'appartement choisi", level = "A2", topic = "appartements", unitID = "fr-foundations-u4", text = "Camille et Théo cherchent un appartement. Le premier est moins cher, mais il est plus loin de la gare : quarante minutes à pied. Le second coûte cent euros de plus, mais il est plus lumineux et il a un balcon. Pour Camille, la lumière est le plus important, parce qu'elle travaille à la maison. Ils décident de demander une visite du second : il est plus cher, mais c'est le meilleur des deux pour eux.", questions = listOf(Exercise(id = "fr-listen-appart-choisi-q1", kind = "choice", prompt = "Combien d'appartements comparent-ils ?", options = listOf("Deux", "Trois", "Quatre"), answers = listOf("Deux"), explain = "Ils comparent deux appartements."), Exercise(id = "fr-listen-appart-choisi-q2", kind = "choice", prompt = "Quel est le problème du moins cher ?", options = listOf("Il est loin de la gare", "Il n'a pas de balcon", "Il est très cher", "Il est petit"), answers = listOf("Il est loin de la gare"), explain = "Quarante minutes à pied de la gare."), Exercise(id = "fr-listen-appart-choisi-q3", kind = "written", prompt = "Combien coûte le second en plus par mois ?", options = listOf(), answers = listOf("cent euros", "100 euros"), explain = "Cent euros de plus par mois."), Exercise(id = "fr-listen-appart-choisi-q4", kind = "choice", prompt = "Qu'est-ce qui est le plus important pour Camille ?", options = listOf("La lumière", "Le prix", "Le balcon", "La cuisine"), answers = listOf("La lumière"), explain = "Elle travaille à la maison."), Exercise(id = "fr-listen-appart-choisi-q5", kind = "choice", prompt = "Que décident-ils ?", options = listOf("Demander une visite du second", "Garder le premier", "Continuer à chercher", "Demander une réduction"), answers = listOf("Demander une visite du second"), explain = "C'est le meilleur des deux pour eux.")), skills = listOf("listening:gist", "listening:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")),
    ListeningText(id = "fr-listen-samedi-organise", languageID = "fr", title = "Le samedi organisé", level = "A2", topic = "projets", unitID = "fr-foundations-u4", text = "Léa appelle son frère pour organiser samedi. Il propose la montagne, mais il va pleuvoir, alors Léa suggère le nouveau musée. Ils vont se retrouver à dix heures à l'entrée principale et déjeuner au marché à côté, qui est moins cher que les restaurants du centre. Le soir, ils n'ont pas de projet : ils vont décider sur place, quand ils connaîtront la météo.", questions = listOf(Exercise(id = "fr-listen-samedi-organise-q1", kind = "choice", prompt = "Qui propose la montagne ?", options = listOf("Le frère", "Léa", "Leur mère", "Un ami"), answers = listOf("Le frère"), explain = "Son frère propose la montagne."), Exercise(id = "fr-listen-samedi-organise-q2", kind = "choice", prompt = "Pourquoi pas la montagne ?", options = listOf("Il va pleuvoir", "Ils sont fatigués", "Le musée est gratuit", "La montagne est loin"), answers = listOf("Il va pleuvoir"), explain = "Il va pleuvoir, alors ils vont au musée."), Exercise(id = "fr-listen-samedi-organise-q3", kind = "written", prompt = "À quelle heure vont-ils se retrouver ?", options = listOf(), answers = listOf("a dix heures", "à dix heures", "dix heures"), explain = "À dix heures à l'entrée principale."), Exercise(id = "fr-listen-samedi-organise-q4", kind = "choice", prompt = "Où vont-ils déjeuner ?", options = listOf("Au marché à côté", "Dans un restaurant du centre", "Chez eux", "Au musée"), answers = listOf("Au marché à côté"), explain = "Moins cher que les restaurants du centre."), Exercise(id = "fr-listen-samedi-organise-q5", kind = "choice", prompt = "Que vont-ils faire le soir ?", options = listOf("Décider sur place", "Aller au cinéma", "Rentrer tôt", "Voir des amis"), answers = listOf("Décider sur place"), explain = "Ils vont décider selon la météo.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("grammar:future-forms")),
    ListeningText(id = "fr-listen-jamais-fait", languageID = "fr", title = "Ce que je n'ai jamais fait", level = "B1", topic = "voyages", unitID = "fr-foundations-u6", text = "Dans la cuisine d'une auberge, trois voyageurs comparent leurs vies. Théo a visité vingt pays, mais il n'a jamais appris à nager : « Je sais, c'est ridicule ». Aïcha a déjà plongé deux fois avec des tortues, mais elle n'a jamais quitté l'Afrique avant ce voyage. Et Léa, qui est sur la route depuis six ans, n'a jamais pris l'avion : elle traverse les océans en bateau et les frontières en bus. « Jamais ? » demande Théo. « Jamais. La peur est plus vieille que moi. » Ils rient de ce qu'ils n'ont pas fait, et Léa dit quelque chose qui reste : « Il ne faut pas avoir tout fait. Il suffit de vouloir encore ».", questions = listOf(Exercise(id = "fr-listen-jamais-fait-q1", kind = "choice", prompt = "Qu'est-ce que Théo n'a jamais fait ?", options = listOf("Apprendre à nager", "Visiter vingt pays", "Traverser en bateau", "Quitter l'Afrique"), answers = listOf("Apprendre à nager"), explain = "Il a visité vingt pays, mais il n'a jamais appris à nager."), Exercise(id = "fr-listen-jamais-fait-q2", kind = "written", prompt = "Combien de fois Aïcha a-t-elle plongé ?", options = listOf(), answers = listOf("deux fois", "2 fois", "deux"), explain = "Aïcha a déjà plongé deux fois avec des tortues."), Exercise(id = "fr-listen-jamais-fait-q3", kind = "choice", prompt = "Comment Léa traverse-t-elle les océans ?", options = listOf("En bateau", "En avion", "En bus", "À pied"), answers = listOf("En bateau"), explain = "Elle traverse les océans en bateau et les frontières en bus."), Exercise(id = "fr-listen-jamais-fait-q4", kind = "choice", prompt = "Que dit Léa sur la peur ?", options = listOf("Elle est plus vieille qu'elle", "Elle est plus jeune", "C'est ridicule", "Elle est partie"), answers = listOf("Elle est plus vieille qu'elle"), explain = "La peur est plus vieille que moi."), Exercise(id = "fr-listen-jamais-fait-q5", kind = "written", prompt = "Qu'est-ce qui suffit, selon Léa ?", options = listOf(), answers = listOf("vouloir encore", "de vouloir encore"), explain = "Il suffit de vouloir encore.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")),
    ListeningText(id = "fr-listen-ville-village", languageID = "fr", title = "De la ville au village", level = "B1", topic = "changements", unitID = "fr-foundations-u6", text = "Nicolas explique pourquoi il a quitté Paris. Avant, il vivait dans un petit appartement et travaillait onze heures par jour : « Je gagnais bien, mais je n'avais pas de vie ». Un hiver, il est tombé malade, et là il a compris qu'il fallait changer. Maintenant il habite dans un village de mille habitants, il travaille de chez lui le matin et cultive un potager l'après-midi. « Je gagne moins, mais j'ai du temps. » Au début, ses parents ne comprenaient pas ; maintenant ils viennent chaque mois. « Tu regrettes quelque chose ? » demande son amie. « De ne pas l'avoir fait plus tôt ».", questions = listOf(Exercise(id = "fr-listen-ville-village-q1", kind = "choice", prompt = "Où habitait Nicolas avant ?", options = listOf("À Paris", "Dans un village", "À Lyon", "Dans une auberge"), answers = listOf("À Paris"), explain = "Nicolas explique pourquoi il a quitté Paris."), Exercise(id = "fr-listen-ville-village-q2", kind = "written", prompt = "Combien d'heures travaillait-il par jour ?", options = listOf(), answers = listOf("onze heures", "11 heures", "onze"), explain = "Il travaillait onze heures par jour."), Exercise(id = "fr-listen-ville-village-q3", kind = "choice", prompt = "Qu'est-ce qui l'a fait changer ?", options = listOf("Il est tombé malade", "Il a perdu son travail", "Il a gagné à la loterie", "Il a rencontré quelqu'un"), answers = listOf("Il est tombé malade"), explain = "Un hiver, il est tombé malade, et là il a compris."), Exercise(id = "fr-listen-ville-village-q4", kind = "choice", prompt = "Que fait-il l'après-midi maintenant ?", options = listOf("Il cultive un potager", "Il travaille plus d'heures", "Il voyage chaque mois", "Il étudie"), answers = listOf("Il cultive un potager"), explain = "Il travaille le matin et cultive un potager l'après-midi."), Exercise(id = "fr-listen-ville-village-q5", kind = "written", prompt = "Que regrette Nicolas ?", options = listOf(), answers = listOf("de ne pas l'avoir fait plus tot", "de ne pas l'avoir fait plus tôt", "ne pas l'avoir fait plus tôt"), explain = "« De ne pas l'avoir fait plus tôt ».")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions")),
    ListeningText(id = "fr-listen-marche-table", languageID = "fr", title = "Le marchandage de la table", level = "B2", topic = "négociation", unitID = "fr-foundations-u7", text = "Sur une app d'occasion, Camille veut une table en bois à 80 euros. « Et si on se retrouvait à 60 ? », propose-t-elle. Le vendeur refuse : « Seulement si vous la prenez aujourd'hui ». Camille réfléchit : « Je vous donnerais 65 si vous ajoutez la chaise ». « Impossible », rit-il, « mais je vous laisserais la table à 70 et je vous la monterais à l'étage ». Camille n'hésite pas : « Vous la monteriez tout seul ? ». « J'ai un diable », répond-il. « Marché conclu », dit-elle, et elle ajoute : « Si elle est aussi belle que sur la photo, je laisse cinq étoiles ».", questions = listOf(Exercise(id = "fr-listen-marche-table-q1", kind = "choice", prompt = "Combien le vendeur demande-t-il ?", options = listOf("80 euros", "60 euros", "70 euros", "65 euros"), answers = listOf("80 euros"), explain = "La table coûte 80 euros."), Exercise(id = "fr-listen-marche-table-q2", kind = "written", prompt = "Que propose Camille d'abord ?", options = listOf(), answers = listOf("60 euros", "soixante euros", "se retrouver a 60", "se retrouver à 60"), explain = "« Et si on se retrouvait à 60 ? »."), Exercise(id = "fr-listen-marche-table-q3", kind = "choice", prompt = "Quelle condition le vendeur pose-t-il ?", options = listOf("La prendre aujourd'hui", "Payer en espèces", "Laisser cinq étoiles", "Revenir demain"), answers = listOf("La prendre aujourd'hui"), explain = "« Seulement si vous la prenez aujourd'hui »."), Exercise(id = "fr-listen-marche-table-q4", kind = "choice", prompt = "Qu'offre le vendeur pour 70 ?", options = listOf("Monter la table à l'étage", "Ajouter la chaise", "Descendre à 60", "Prêter un diable"), answers = listOf("Monter la table à l'étage"), explain = "« Je vous la monterais à l'étage »."), Exercise(id = "fr-listen-marche-table-q5", kind = "written", prompt = "Que promet Camille si la table plaît ?", options = listOf(), answers = listOf("cinq etoiles", "cinq étoiles", "une note de cinq etoiles"), explain = "Cinq étoiles.")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors")),
    ListeningText(id = "fr-listen-info-quartier", languageID = "fr", title = "L'info du quartier", level = "B2", topic = "actualité", unitID = "fr-foundations-u8", text = "Au marché, Anaïs et Marc commentent ce qu'on dit. « On dit qu'ils vont piétonniser la rue principale », raconte Anaïs. « Encore ? », rit Marc. « La nouvelle que j'ai lue dit que ça commence au printemps ». D'après la mairie, ce serait seulement le samedi, mais les commerçants, dont le chiffre d'affaires dépendrait du tourisme, ont déjà manifesté. « C'est vrai que le bruit baisserait », concède Marc, « mais, et le parking ? ». Anaïs défend la mesure : « D'un côté, plus de gens marcheraient ; de l'autre, les bus s'arrêteraient à la porte ». Ils ne trancheent pas, mais promettent d'en reparler quand le plan sera publié.", questions = listOf(Exercise(id = "fr-listen-info-quartier-q1", kind = "choice", prompt = "Que dit-on de la rue principale ?", options = listOf("Qu'on la piétonnisera", "Qu'on l'élargira", "Qu'on la fermera", "Qu'on la rebaptisera"), answers = listOf("Qu'on la piétonnisera"), explain = "« On dit qu'ils vont piétonniser la rue principale »."), Exercise(id = "fr-listen-info-quartier-q2", kind = "written", prompt = "Quand est-ce que ça commencerait ?", options = listOf(), answers = listOf("au printemps", "printemps"), explain = "« La nouvelle que j'ai lue dit que ça commence au printemps »."), Exercise(id = "fr-listen-info-quartier-q3", kind = "choice", prompt = "Que dit la mairie ?", options = listOf("Seulement le samedi", "Tous les jours", "Seulement en été", "Les jours fériés"), answers = listOf("Seulement le samedi"), explain = "D'après la mairie, ce serait seulement le samedi."), Exercise(id = "fr-listen-info-quartier-q4", kind = "choice", prompt = "Qui a manifesté ?", options = listOf("Les commerçants", "Les habitants", "Les taxi", "La mairie"), answers = listOf("Les commerçants"), explain = "Les commerçants ont déjà manifesté."), Exercise(id = "fr-listen-info-quartier-q5", kind = "written", prompt = "Que promettent Anaïs et Marc ?", options = listOf(), answers = listOf("d'en reparler", "en reparler", "reparler du plan"), explain = "Ils promettent d'en reparler quand le plan sera publié.")), skills = listOf("listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors")),
    ListeningText(id = "it-listen-cafe-morning", languageID = "it", title = "Un caffè prima del lavoro", level = "A1", topic = "routine", unitID = "it-foundations-u1", text = "Ogni mattina, Marta cammina fino a un piccolo caffè vicino a casa sua. Il cameriere conosce il suo nome, così non deve mai ordinare. Oggi si siede vicino alla finestra con un caffè e un cornetto. Il suo autobus parte alle otto e mezza, ma non è preoccupata. Il caffè è molto tranquillo a quell'ora. Beve il caffè lentamente e guarda la città che si sveglia.", questions = listOf(Exercise(id = "it-listen-cafe-morning-q1", kind = "choice", prompt = "Dove va Marta ogni mattina?", options = listOf("In un piccolo caffè", "Al suo ufficio", "Alla stazione degli autobus", "In un parco"), answers = listOf("In un piccolo caffè"), explain = "Cammina fino a un piccolo caffè vicino a casa sua."), Exercise(id = "it-listen-cafe-morning-q2", kind = "choice", prompt = "Cosa fa colazione oggi?", options = listOf("Un caffè e un cornetto", "Tè e toast", "Succo d'arancia", "Niente"), answers = listOf("Un caffè e un cornetto"), explain = "Si siede vicino alla finestra con un caffè e un cornetto."), Exercise(id = "it-listen-cafe-morning-q3", kind = "written", prompt = "A che ora parte il suo autobus?", options = listOf(), answers = listOf("alle otto e mezza", "otto e mezza"), explain = "Il suo autobus parte alle otto e mezza."), Exercise(id = "it-listen-cafe-morning-q4", kind = "choice", prompt = "Come si sente per l'orario?", options = listOf("Non è preoccupata", "È in grandissimo ritardo", "È arrabbiata", "Ha sonno"), answers = listOf("Non è preoccupata"), explain = "Il testo dice che non è preoccupata."), Exercise(id = "it-listen-cafe-morning-q5", kind = "choice", prompt = "Chi conosce il suo nome?", options = listOf("Il cameriere", "L'autista dell'autobus", "Il suo capo", "Un vicino"), answers = listOf("Il cameriere"), explain = "Il cameriere conosce il suo nome, così non deve mai ordinare."), Exercise(id = "it-listen-cafe-morning-q6", kind = "written", prompt = "Dove si siede oggi?", options = listOf(), answers = listOf("vicino alla finestra", "accanto alla finestra", "alla finestra"), explain = "Oggi si siede vicino alla finestra.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")),
    ListeningText(id = "it-listen-language-class", languageID = "it", title = "Il corso di lingua", level = "A1", topic = "presentazioni", unitID = "it-foundations-u1", text = "Marta partecipa alla sua prima lezione di portoghese in un piccolo istituto. In classe ci sono sei persone e tutti vogliono parlare. L'insegnante chiede le presentazioni. « Mi chiamo Marta e sono della Bolivia », dice una signora. « Io sono Andrés, sono del Perù e lavoro in un ristorante », dice un ragazzo. Marta si presenta anche lei: « Sono Marta, sono argentina e sono infermiera ». L'insegnante è di Madrid e insegna con molto humour. Alla fine della lezione, gli studenti si scambiano i numeri di telefono. Non sono ancora amici, ma la prossima settimana vanno a prendere un caffè insieme per praticare.", questions = listOf(Exercise(id = "it-listen-language-class-q1", kind = "choice", prompt = "Quante persone ci sono in classe?", options = listOf("Sei", "Tre", "Dieci", "Quattordici"), answers = listOf("Sei"), explain = "In classe ci sono sei persone."), Exercise(id = "it-listen-language-class-q2", kind = "choice", prompt = "Di dov'è Andrés?", options = listOf("Del Perù", "Della Bolivia", "Dell'Argentina", "Del Messico"), answers = listOf("Del Perù"), explain = "Andrés è del Perù e lavora in un ristorante."), Exercise(id = "it-listen-language-class-q3", kind = "choice", prompt = "Qual è il lavoro di Marta?", options = listOf("Infermiera", "Insegnante", "Cameriera", "Studentessa"), answers = listOf("Infermiera"), explain = "Marta è argentina ed è infermiera."), Exercise(id = "it-listen-language-class-q4", kind = "written", prompt = "Di che città è l'insegnante?", options = listOf(), answers = listOf("madrid", "di madrid", "è di madrid"), explain = "L'insegnante è di Madrid."), Exercise(id = "it-listen-language-class-q5", kind = "choice", prompt = "Cosa fanno alla fine della lezione?", options = listOf("Si scambiano i numeri di telefono", "Tornano a casa da soli", "Fanno un esame", "Cenano al ristorante"), answers = listOf("Si scambiano i numeri di telefono"), explain = "Gli studenti si scambiano i numeri di telefono."), Exercise(id = "it-listen-language-class-q6", kind = "written", prompt = "Cosa fanno la prossima settimana?", options = listOf(), answers = listOf("prendere un caffè", "vanno a prendere un caffè", "prendere un caffè insieme"), explain = "La prossima settimana vanno a prendere un caffè insieme per praticare.")), skills = listOf("listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself")),
    ListeningText(id = "it-listen-little-sister", languageID = "it", title = "Mia sorella piccola", level = "A1", topic = "famiglia", unitID = "it-foundations-u1", text = "Mia sorella piccola si chiama Carla e ha nove anni. È molto simpatica e molto chiacchierona. Carla non è riservata: parla con tutti, con i vicini, con gli insegnanti e con i cani del parco. È bionda, come nostra madre, e ha gli occhi castani come mio padre. Non è alta per la sua età, ma è molto veloce e le piace tantissimo il calcio. La sua squadra non è molto buona, ma a lei non importa. « Non sono professionista », dice, « io sono solo felice con il pallone ». Mia sorella è piccola, ma la sua gioia è enorme.", questions = listOf(Exercise(id = "it-listen-little-sister-q1", kind = "choice", prompt = "Quanti anni ha Carla?", options = listOf("Nove", "Diciannove", "Sette", "Dieci"), answers = listOf("Nove"), explain = "Carla ha nove anni."), Exercise(id = "it-listen-little-sister-q2", kind = "choice", prompt = "Com'è Carla?", options = listOf("Simpatica e chiacchierona", "Timida e riservata", "Seria", "Triste"), answers = listOf("Simpatica e chiacchierona"), explain = "È molto simpatica e molto chiacchierona."), Exercise(id = "it-listen-little-sister-q3", kind = "written", prompt = "Di che colore sono i suoi occhi?", options = listOf(), answers = listOf("castani", "gli occhi castani", "castani come suo padre"), explain = "Ha gli occhi castani come suo padre."), Exercise(id = "it-listen-little-sister-q4", kind = "choice", prompt = "Che capelli ha?", options = listOf("Biondi, come sua madre", "Scuri, come suo padre", "Rossi", "Corti e neri"), answers = listOf("Biondi, come sua madre"), explain = "È bionda, come nostra madre."), Exercise(id = "it-listen-little-sister-q5", kind = "choice", prompt = "Che cosa le piace tantissimo?", options = listOf("Il calcio", "Il nuoto", "La musica", "I videogiochi"), answers = listOf("Il calcio"), explain = "È molto veloce e le piace tantissimo il calcio."), Exercise(id = "it-listen-little-sister-q6", kind = "written", prompt = "Com'è la sua gioia?", options = listOf(), answers = listOf("enorme", "molto grande", "grande"), explain = "La sua gioia è enorme.")), skills = listOf("listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family")),
    ListeningText(id = "it-listen-new-flatmate", languageID = "it", title = "Un nuovo coinquilino", level = "A1", topic = "casa", unitID = "it-foundations-u1", text = "Tom ha un nuovo coinquilino. Si chiama Leo e ha ventitré anni. Leo viene da un piccolo paese del nord, ma ora lavora in città. Ha due scatole, una chitarra e una bicicletta. L'appartamento ha due camere e una cucina molto luminosa. Tom spera che a Leo piaccia cucinare, perché a Tom non piace per niente.", questions = listOf(Exercise(id = "it-listen-new-flatmate-q1", kind = "choice", prompt = "Quanti anni ha Leo?", options = listOf("Ventitré", "Trentadue", "Venti", "Trenta"), answers = listOf("Ventitré"), explain = "Leo ha ventitré anni."), Exercise(id = "it-listen-new-flatmate-q2", kind = "choice", prompt = "Cosa NON ha Leo?", options = listOf("Una televisione", "Due scatole", "Una chitarra", "Una bicicletta"), answers = listOf("Una televisione"), explain = "Ha due scatole, una chitarra e una bicicletta — niente televisione."), Exercise(id = "it-listen-new-flatmate-q3", kind = "written", prompt = "Cosa odia fare Tom?", options = listOf(), answers = listOf("cucinare", "odia cucinare", "tom odia cucinare"), explain = "A Tom non piace per niente cucinare."), Exercise(id = "it-listen-new-flatmate-q4", kind = "choice", prompt = "Com'è l'appartamento?", options = listOf("Due camere e una cucina luminosa", "Una camera e un balcone", "Un giardino", "Due bagni"), answers = listOf("Due camere e una cucina luminosa"), explain = "L'appartamento ha due camere e una cucina molto luminosa."), Exercise(id = "it-listen-new-flatmate-q5", kind = "choice", prompt = "Dove lavora Leo adesso?", options = listOf("In città", "In un piccolo paese", "Al nord", "Non lavora"), answers = listOf("In città"), explain = "Viene da un piccolo paese del nord, ma ora lavora in città."), Exercise(id = "it-listen-new-flatmate-q6", kind = "written", prompt = "Quale strumento ha Leo?", options = listOf(), answers = listOf("una chitarra", "la chitarra", "chitarra"), explain = "Leo ha una chitarra.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")),
    ListeningText(id = "it-listen-new-neighbour", languageID = "it", title = "La nuova vicina", level = "A1", topic = "gente", unitID = "it-foundations-u1", text = "Nel palazzo c'è una nuova vicina. Si chiama Amélie ed è della Francia. Non è studentessa; è fotografa. Non lavora in ufficio: lavora a casa e viaggia molto. I vicini sono curiosi, ma sono anche timidi, quindi non le parlano. Poi, una mattina, Ben la incontra alla porta. « Sei tu la nuova vicina? », chiede lui. « Sì, sono io », risponde lei, « e sono contenta di essere qui ». Adesso sono amici, e lei non è più sola nel palazzo.", questions = listOf(Exercise(id = "it-listen-new-neighbour-q1", kind = "choice", prompt = "Di dov'è Amélie?", options = listOf("Della Francia", "Dell'Italia", "Del Giappone", "Del Brasile"), answers = listOf("Della Francia"), explain = "Amélie è della Francia."), Exercise(id = "it-listen-new-neighbour-q2", kind = "choice", prompt = "Qual è il suo lavoro?", options = listOf("È fotografa", "È studentessa", "Lavora in ufficio", "È insegnante"), answers = listOf("È fotografa"), explain = "Non è studentessa; è fotografa."), Exercise(id = "it-listen-new-neighbour-q3", kind = "choice", prompt = "Lavora in ufficio?", options = listOf("No, lavora a casa", "Sì, tutti i giorni", "Solo in estate", "Non lo dice"), answers = listOf("No, lavora a casa"), explain = "Non lavora in ufficio: lavora a casa."), Exercise(id = "it-listen-new-neighbour-q4", kind = "written", prompt = "Perché i vicini non le parlano?", options = listOf(), answers = listOf("sono timidi", "perché sono timidi", "timidi"), explain = "Sono curiosi, ma sono anche timidi."), Exercise(id = "it-listen-new-neighbour-q5", kind = "choice", prompt = "Dove la incontra Ben?", options = listOf("Alla porta", "All'ascensore", "Per strada", "Al caffè"), answers = listOf("Alla porta"), explain = "Una mattina, Ben la incontra alla porta."), Exercise(id = "it-listen-new-neighbour-q6", kind = "written", prompt = "Come si sente Amélie alla fine?", options = listOf(), answers = listOf("contenta", "felice", "è contenta"), explain = "Dice che è contenta di essere qui.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")),
    ListeningText(id = "it-listen-sunday-market", languageID = "it", title = "Il mercato della domenica", level = "A1", topic = "acquisti", unitID = "it-foundations-u1", text = "La domenica c'è un mercato nella piazza del paese. Anna e suo padre vanno lì alle nove, prima che si riempia. Comprano frutta, pane e fiori. Anna vuole delle fragole, ma suo padre dice che questa settimana sono troppo care. Alla fine portano a casa un grande sacco di arance e delle rose bianche per il tavolo della cucina.", questions = listOf(Exercise(id = "it-listen-sunday-market-q1", kind = "choice", prompt = "Quando Anna e suo padre vanno al mercato?", options = listOf("Alle nove", "A mezzogiorno", "Nel pomeriggio", "Alle sei e mezza"), answers = listOf("Alle nove"), explain = "Vanno alle nove, prima che si riempia."), Exercise(id = "it-listen-sunday-market-q2", kind = "written", prompt = "Perché Anna non prende le fragole?", options = listOf(), answers = listOf("sono troppo care", "troppo care", "perché sono troppo care"), explain = "Suo padre dice che sono troppo care questa settimana."), Exercise(id = "it-listen-sunday-market-q3", kind = "choice", prompt = "Cosa portano a casa?", options = listOf("Arance e rose", "Fragole e pane", "Mele e tulipani", "Pane e formaggio"), answers = listOf("Arance e rose"), explain = "Portano a casa arance e rose bianche."), Exercise(id = "it-listen-sunday-market-q4", kind = "choice", prompt = "Dov'è il mercato?", options = listOf("Nella piazza del paese", "Vicino al fiume", "Alla stazione", "In un supermercato"), answers = listOf("Nella piazza del paese"), explain = "La domenica c'è un mercato nella piazza del paese."), Exercise(id = "it-listen-sunday-market-q5", kind = "choice", prompt = "Cosa comprano?", options = listOf("Frutta, pane e fiori", "Pesce e verdure", "Formaggio e carne", "Solo fiori"), answers = listOf("Frutta, pane e fiori"), explain = "Comprano frutta, pane e fiori."), Exercise(id = "it-listen-sunday-market-q6", kind = "written", prompt = "Cosa vuole Anna?", options = listOf(), answers = listOf("delle fragole", "fragole", "vuole delle fragole"), explain = "Anna vuole delle fragole.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")),
    ListeningText(id = "it-listen-appartamento-scelto", languageID = "it", title = "L'appartamento scelto", level = "A2", topic = "appartamenti", unitID = "it-foundations-u4", text = "Giulia e Marco cercano appartamento su un annuncio. Il primo è meno costoso, ma è più lontano dalla stazione: quaranta minuti a piedi. Il secondo costa cento euro in più al mese, ma è più luminoso e ha il balcone. Per Giulia la luce è la cosa più importante, perché lavora da casa. Alla fine decidono di chiedere una visita del secondo: costa di più, ma è il migliore dei due per loro.", questions = listOf(Exercise(id = "it-listen-appartamento-scelto-q1", kind = "choice", prompt = "Quanti appartamenti confrontano ?", options = listOf("Due", "Tre", "Quattro"), answers = listOf("Due"), explain = "Confrontano due appartamenti."), Exercise(id = "it-listen-appartamento-scelto-q2", kind = "choice", prompt = "Qual è il problema del meno costoso ?", options = listOf("È lontano dalla stazione", "Non ha il balcone", "È molto costoso", "È piccolo"), answers = listOf("È lontano dalla stazione"), explain = "Quaranta minuti a piedi dalla stazione."), Exercise(id = "it-listen-appartamento-scelto-q3", kind = "written", prompt = "Quanto costa in più il secondo al mese ?", options = listOf(), answers = listOf("cento euro", "100 euro"), explain = "Cento euro in più al mese."), Exercise(id = "it-listen-appartamento-scelto-q4", kind = "choice", prompt = "Cos'è più importante per Giulia ?", options = listOf("La luce", "Il prezzo", "Il balcone", "La cucina"), answers = listOf("La luce"), explain = "Lavora da casa."), Exercise(id = "it-listen-appartamento-scelto-q5", kind = "choice", prompt = "Cosa decidono alla fine ?", options = listOf("Chiedere una visita del secondo", "Tenere il primo", "Continuare a cercare", "Chiedere uno sconto"), answers = listOf("Chiedere una visita del secondo"), explain = "È il migliore dei due per loro.")), skills = listOf("listening:gist", "listening:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")),
    ListeningText(id = "it-listen-sabato-organizzato", languageID = "it", title = "Il sabato organizzato", level = "A2", topic = "progetti", unitID = "it-foundations-u4", text = "Sara chiama suo fratello per organizzare il sabato. Lui propone la montagna, ma pioverà, quindi Sara suggerisce il museo nuovo. Si vedranno alle dieci all'ingresso principale e pranzeranno al mercato accanto, che è meno caro dei ristoranti del centro. La sera non hanno programmi: decideranno sul posto, quando sapranno che tempo fa.", questions = listOf(Exercise(id = "it-listen-sabato-organizzato-q1", kind = "choice", prompt = "Chi propone la montagna ?", options = listOf("Il fratello", "Sara", "La loro madre", "Un amico"), answers = listOf("Il fratello"), explain = "Suo fratello propone la montagna."), Exercise(id = "it-listen-sabato-organizzato-q2", kind = "choice", prompt = "Perché non la montagna ?", options = listOf("Pioverà", "Sono stanchi", "Il museo è gratis", "La montagna è lontana"), answers = listOf("Pioverà"), explain = "Pioverà, quindi vanno al museo."), Exercise(id = "it-listen-sabato-organizzato-q3", kind = "written", prompt = "A che ora si vedranno ?", options = listOf(), answers = listOf("alle dieci", "dieci"), explain = "Alle dieci all'ingresso principale."), Exercise(id = "it-listen-sabato-organizzato-q4", kind = "choice", prompt = "Dove pranzeranno ?", options = listOf("Al mercato accanto", "In un ristorante del centro", "A casa", "Al museo"), answers = listOf("Al mercato accanto"), explain = "Meno caro dei ristoranti del centro."), Exercise(id = "it-listen-sabato-organizzato-q5", kind = "choice", prompt = "Cosa faranno la sera ?", options = listOf("Decideranno sul posto", "Andranno al cinema", "Torneranno presto", "Vedranno amici"), answers = listOf("Decideranno sul posto"), explain = "Decideranno secondo il tempo.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("grammar:future-forms")),
    ListeningText(id = "it-listen-mai-fatto", languageID = "it", title = "Cose che non ho mai fatto", level = "B1", topic = "viaggi", unitID = "it-foundations-u6", text = "Nella cucina di un ostello, tre viaggiatori paragonano le loro vite. Luca ha visitato venti paesi, ma non ha mai imparato a nuotare: « Lo so, è ridicolo ». Sara ha già fatto snorkeling due volte con le tartarughe, ma non è mai uscita dall'Europa prima di questo viaggio. E Elena, che è in viaggio da sei anni, non ha mai preso l'aereo: attraversa gli oceani in nave e i confini in autobus. « Mai ? » chiede Luca. « Mai. La paura è più vecchia di me. » Ridono delle cose che non hanno fatto, ed Elena dice una frase che resta: « Non serve aver fatto tutto. Basta avere ancora voglia ».", questions = listOf(Exercise(id = "it-listen-mai-fatto-q1", kind = "choice", prompt = "Cosa non ha mai fatto Luca ?", options = listOf("Imparare a nuotare", "Visitare venti paesi", "Attraversare in nave", "Uscire dall'Europa"), answers = listOf("Imparare a nuotare"), explain = "Ha visitato venti paesi, ma non ha mai imparato a nuotare."), Exercise(id = "it-listen-mai-fatto-q2", kind = "written", prompt = "Quante volte ha fatto snorkeling Sara ?", options = listOf(), answers = listOf("due volte", "2 volte", "due"), explain = "Sara ha già fatto snorkeling due volte con le tartarughe."), Exercise(id = "it-listen-mai-fatto-q3", kind = "choice", prompt = "Come attraversa Elena gli oceani ?", options = listOf("In nave", "In aereo", "In autobus", "A piedi"), answers = listOf("In nave"), explain = "Attraversa gli oceani in nave e i confini in autobus."), Exercise(id = "it-listen-mai-fatto-q4", kind = "choice", prompt = "Cosa dice Elena della paura ?", options = listOf("È più vecchia di lei", "È più giovane", "È ridicola", "Se n'è andata"), answers = listOf("È più vecchia di lei"), explain = "La paura è più vecchia di me."), Exercise(id = "it-listen-mai-fatto-q5", kind = "written", prompt = "Cosa basta, secondo Elena ?", options = listOf(), answers = listOf("avere ancora voglia", "aver voglia"), explain = "Basta avere ancora voglia.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")),
    ListeningText(id = "it-listen-citta-paese", languageID = "it", title = "Dalla città al paese", level = "B1", topic = "cambiamenti", unitID = "it-foundations-u6", text = "Marco racconta perché ha lasciato Milano. Prima viveva in un appartamento piccolo e lavorava undici ore al giorno: « Guadagnavo bene, ma non avevo vita ». Un inverno si è ammalato, e allora ha capito che doveva cambiare. Adesso vive in un paese di mille abitanti, lavora da casa la mattina e coltiva un orto nel pomeriggio. « Guadagno meno, ma mi avanza tempo. » All'inizio i suoi genitori non capivano; adesso vengono ogni mese. « Ti penti di qualcosa ? » gli chiede l'amica. « Di non averlo fatto prima ».", questions = listOf(Exercise(id = "it-listen-citta-paese-q1", kind = "choice", prompt = "Dove viveva Marco prima ?", options = listOf("A Milano", "In un paese", "A Roma", "In un ostello"), answers = listOf("A Milano"), explain = "Marco racconta perché ha lasciato Milano."), Exercise(id = "it-listen-citta-paese-q2", kind = "written", prompt = "Quante ore lavorava al giorno ?", options = listOf(), answers = listOf("undici ore", "11 ore", "undici"), explain = "Lavorava undici ore al giorno."), Exercise(id = "it-listen-citta-paese-q3", kind = "choice", prompt = "Cosa l'ha fatto cambiare ?", options = listOf("Si è ammalato", "Ha perso il lavoro", "Ha vinto alla lotteria", "Ha conosciuto qualcuno"), answers = listOf("Si è ammalato"), explain = "Un inverno si è ammalato, e allora ha capito."), Exercise(id = "it-listen-citta-paese-q4", kind = "choice", prompt = "Cosa fa nel pomeriggio adesso ?", options = listOf("Coltiva un orto", "Lavora più ore", "Viaggia ogni mese", "Studia"), answers = listOf("Coltiva un orto"), explain = "Lavora la mattina e coltiva un orto nel pomeriggio."), Exercise(id = "it-listen-citta-paese-q5", kind = "written", prompt = "Di cosa si pente Marco ?", options = listOf(), answers = listOf("di non averlo fatto prima", "non averlo fatto prima"), explain = "« Di non averlo fatto prima ».")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions")),
    ListeningText(id = "it-listen-trattativa-tavolo", languageID = "it", title = "La trattativa del tavolo", level = "B2", topic = "negoziazione", unitID = "it-foundations-u7", text = "Su un'app di usato, Chiara vuole un tavolo di legno da 80 euro. « E se chiudessimo a 60 ? », propone. Il venditore rifiuta: « Solo se la ritiri oggi ». Chiara riflette: « Le darei 65 se aggiunge la sedia ». « Impossibile », ride lui, « ma le lascerei il tavolo a 70 e glielo salirei al piano ». Chiara non dubita: « Lo salirebbe da solo ? ». « Ho una carriola », risponde. « Affare fatto », dice lei, e aggiunge: « Se è bello come in foto, le lascio cinque stelle ».", questions = listOf(Exercise(id = "it-listen-trattativa-tavolo-q1", kind = "choice", prompt = "Quanto chiede il venditore ?", options = listOf("80 euro", "60 euro", "70 euro", "65 euro"), answers = listOf("80 euro"), explain = "Il tavolo costa 80 euro."), Exercise(id = "it-listen-trattativa-tavolo-q2", kind = "written", prompt = "Cosa propone Chiara all'inizio ?", options = listOf(), answers = listOf("60 euro", "sessanta euro", "chiudere a 60"), explain = "« E se chiudessimo a 60 ? »."), Exercise(id = "it-listen-trattativa-tavolo-q3", kind = "choice", prompt = "Che condizione mette il venditore ?", options = listOf("Ritirarla oggi", "Pagare in contanti", "Lasciare cinque stelle", "Tornare domani"), answers = listOf("Ritirarla oggi"), explain = "« Solo se la ritiri oggi »."), Exercise(id = "it-listen-trattativa-tavolo-q4", kind = "choice", prompt = "Cosa offre il venditore per 70 ?", options = listOf("Salire il tavolo al piano", "Aggiungere la sedia", "Scendere a 60", "Prestare la carriola"), answers = listOf("Salire il tavolo al piano"), explain = "« Glielo salirei al piano »."), Exercise(id = "it-listen-trattativa-tavolo-q5", kind = "written", prompt = "Cosa promette Chiara se il tavolo le piace ?", options = listOf(), answers = listOf("cinque stelle", "5 stelle", "una recensione di cinque stelle"), explain = "Cinque stelle.")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors")),
    ListeningText(id = "it-listen-notizia-quartiere", languageID = "it", title = "La notizia del quartiere", level = "B2", topic = "notizie", unitID = "it-foundations-u8", text = "Al mercato, Giulia e Paolo commentano quello che si dice. « Si dice che pedonalizzeranno la via principale », racconta Giulia. « Di nuovo ? », ride Paolo. « La notizia che ho letto dice che partono in primavera ». Secondo il comune, sarebbe solo il sabato, ma i negozianti, il cui fatturato dipenderebbe dal turismo, sono già scesi in piazza. « È vero che il rumore calerebbe », ammette Paolo, « ma, e il parcheggio ? ». Giulia difende la misura: « Da un lato, più gente camminerebbe; dall'altro, gli autobus arriverebbero all'angolo ». Non la decidono, ma promettono di riparlarne quando uscirà il piano.", questions = listOf(Exercise(id = "it-listen-notizia-quartiere-q1", kind = "choice", prompt = "Cosa si dice della via principale ?", options = listOf("Che la pedonalizzeranno", "Che la allargheranno", "Che la chiuderanno", "Che cambierà nome"), answers = listOf("Che la pedonalizzeranno"), explain = "« Si dice che pedonalizzeranno la via principale »."), Exercise(id = "it-listen-notizia-quartiere-q2", kind = "written", prompt = "Quando partirebbe ?", options = listOf(), answers = listOf("in primavera", "primavera"), explain = "« La notizia che ho letto dice che partono in primavera »."), Exercise(id = "it-listen-notizia-quartiere-q3", kind = "choice", prompt = "Cosa dice il comune ?", options = listOf("Solo il sabato", "Tutti i giorni", "Solo d'estate", "I festivi"), answers = listOf("Solo il sabato"), explain = "Secondo il comune, sarebbe solo il sabato."), Exercise(id = "it-listen-notizia-quartiere-q4", kind = "choice", prompt = "Chi è sceso in piazza ?", options = listOf("I negozianti", "I residenti", "I tassisti", "Il comune"), answers = listOf("I negozianti"), explain = "I negozianti sono già scesi in piazza."), Exercise(id = "it-listen-notizia-quartiere-q5", kind = "written", prompt = "Cosa promettono Giulia e Paolo ?", options = listOf(), answers = listOf("di riparlarne", "ripdirlo", "riparlarne quando uscira il piano"), explain = "Promettono di riparlarne quando uscirà il piano.")), skills = listOf("listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors")),
    ListeningText(id = "pt-listen-cafe-morning", languageID = "pt", title = "Um café antes do trabalho", level = "A1", topic = "rotina", unitID = "pt-foundations-u1", text = "Todas as manhãs, Marta caminha até uma cafeteria pequena perto do apartamento dela. O garçom sabe o nome dela, então ela nunca precisa pedir. Hoje ela senta perto da janela com um café e um pão de queijo. O ônibus dela sai às oito e meia, mas ela não está preocupada. A cafeteria é muito tranquila nessa hora. Ela bebe o café devagar e vê a cidade acordar.", questions = listOf(Exercise(id = "pt-listen-cafe-morning-q1", kind = "choice", prompt = "Para onde a Marta vai todas as manhãs?", options = listOf("Para uma cafeteria pequena", "Para o escritório dela", "Para o ponto de ônibus", "Para um parque"), answers = listOf("Para uma cafeteria pequena"), explain = "Ela caminha até uma cafeteria pequena perto do apartamento dela."), Exercise(id = "pt-listen-cafe-morning-q2", kind = "choice", prompt = "O que ela toma no café da manhã hoje?", options = listOf("Um café e um pão de queijo", "Chá e torradas", "Suco de laranja", "Nada"), answers = listOf("Um café e um pão de queijo"), explain = "Ela senta perto da janela com um café e um pão de queijo."), Exercise(id = "pt-listen-cafe-morning-q3", kind = "written", prompt = "A que horas sai o ônibus dela?", options = listOf(), answers = listOf("às oito e meia", "oito e meia"), explain = "O ônibus dela sai às oito e meia."), Exercise(id = "pt-listen-cafe-morning-q4", kind = "choice", prompt = "Como ela se sente com o horário?", options = listOf("Não está preocupada", "Está muito atrasada", "Está com raiva", "Está com sono"), answers = listOf("Não está preocupada"), explain = "O texto diz que ela não está preocupada."), Exercise(id = "pt-listen-cafe-morning-q5", kind = "choice", prompt = "Quem sabe o nome dela?", options = listOf("O garçom", "O motorista do ônibus", "O chefe dela", "Um vizinho"), answers = listOf("O garçom"), explain = "O garçom sabe o nome dela, então ela nunca precisa pedir."), Exercise(id = "pt-listen-cafe-morning-q6", kind = "written", prompt = "Onde ela senta hoje?", options = listOf(), answers = listOf("perto da janela", "ao lado da janela", "na janela"), explain = "Hoje ela senta perto da janela.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")),
    ListeningText(id = "pt-listen-language-class", languageID = "pt", title = "A aula de idiomas", level = "A1", topic = "apresentações", unitID = "pt-foundations-u1", text = "Marta participa da primeira aula de português para estrangeiros em um instituto pequeno. Na turma há seis pessoas e todas querem conversar. A professora pede as apresentações. “Meu nome é Marta e sou da Bolívia”, diz uma senhora. “Eu sou o Andrés, sou do Peru e trabalho em um restaurante”, diz um rapaz. Marta também se apresenta: “Sou a Marta, sou argentina e sou enfermeira”. A professora é de Madri e ensina com muito bom humor. No final da aula, os alunos trocam os números de telefone. Ainda não são amigos, mas na próxima semana vão tomar um café juntos e praticar.", questions = listOf(Exercise(id = "pt-listen-language-class-q1", kind = "choice", prompt = "Quantas pessoas há na turma?", options = listOf("Seis", "Três", "Dez", "Quatorze"), answers = listOf("Seis"), explain = "Na turma há seis pessoas."), Exercise(id = "pt-listen-language-class-q2", kind = "choice", prompt = "De onde é o Andrés?", options = listOf("Do Peru", "Da Bolívia", "Da Argentina", "Do México"), answers = listOf("Do Peru"), explain = "O Andrés é do Peru e trabalha em um restaurante."), Exercise(id = "pt-listen-language-class-q3", kind = "choice", prompt = "Qual é o trabalho da Marta?", options = listOf("Enfermeira", "Professora", "Garçonete", "Estudante"), answers = listOf("Enfermeira"), explain = "A Marta é argentina e é enfermeira."), Exercise(id = "pt-listen-language-class-q4", kind = "written", prompt = "De onde é a professora?", options = listOf(), answers = listOf("madril", "de madri", "madri", "madrid", "de madrid"), explain = "A professora é de Madri."), Exercise(id = "pt-listen-language-class-q5", kind = "choice", prompt = "O que eles fazem no final da aula?", options = listOf("Trocam os números de telefone", "Voltam para casa sozinhos", "Fazem uma prova", "Jantam em um restaurante"), answers = listOf("Trocam os números de telefone"), explain = "Os alunos trocam os números de telefone."), Exercise(id = "pt-listen-language-class-q6", kind = "written", prompt = "O que eles vão fazer na próxima semana?", options = listOf(), answers = listOf("tomar um café", "vão tomar um café", "tomar um café juntos"), explain = "Na próxima semana vão tomar um café juntos e praticar.")), skills = listOf("listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself")),
    ListeningText(id = "pt-listen-little-sister", languageID = "pt", title = "Minha irmã mais nova", level = "A1", topic = "família", unitID = "pt-foundations-u1", text = "Minha irmã mais nova se chama Carla e tem nove anos. É muito simpática e muito falante. Carla não é tímida: fala com todo mundo, com os vizinhos, com os professores e com os cachorros do parque. É loira, como a nossa mãe, e tem olhos castanhos como o meu pai. Não é alta para a idade dela, mas é muito rápida e adora futebol. O time dela não é muito bom, mas isso não é importante para ela. “Não sou profissional”, diz ela, “só sou feliz com a bola”. Minha irmã é pequena, mas a alegria dela é enorme.", questions = listOf(Exercise(id = "pt-listen-little-sister-q1", kind = "choice", prompt = "Quantos anos a Carla tem?", options = listOf("Nove", "Dezenove", "Sete", "Dez"), answers = listOf("Nove"), explain = "A Carla tem nove anos."), Exercise(id = "pt-listen-little-sister-q2", kind = "choice", prompt = "Como é a Carla?", options = listOf("Simpática e falante", "Tímida e calada", "Séria", "Triste"), answers = listOf("Simpática e falante"), explain = "É muito simpática e muito falante."), Exercise(id = "pt-listen-little-sister-q3", kind = "written", prompt = "De que cor são os olhos dela?", options = listOf(), answers = listOf("castanhos", "olhos castanhos", "castanhos como o pai dela"), explain = "Ela tem olhos castanhos como o pai dela."), Exercise(id = "pt-listen-little-sister-q4", kind = "choice", prompt = "Como é o cabelo dela?", options = listOf("Loiro, como o da mãe", "Escuro, como o do pai", "Ruivo", "Curto e preto"), answers = listOf("Loiro, como o da mãe"), explain = "É loira, como a nossa mãe."), Exercise(id = "pt-listen-little-sister-q5", kind = "choice", prompt = "O que ela adora?", options = listOf("Futebol", "Natação", "Música", "Videogame"), answers = listOf("Futebol"), explain = "É muito rápida e adora futebol."), Exercise(id = "pt-listen-little-sister-q6", kind = "written", prompt = "Como é a alegria dela?", options = listOf(), answers = listOf("enorme", "muito grande", "grande"), explain = "A alegria dela é enorme.")), skills = listOf("listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family")),
    ListeningText(id = "pt-listen-new-flatmate", languageID = "pt", title = "Um novo colega de apartamento", level = "A1", topic = "casa", unitID = "pt-foundations-u1", text = "Tom tem um colega de apartamento novo. O nome dele é Leo e ele tem vinte e três anos. Leo vem de uma cidade pequena do interior, mas agora trabalha na capital. Ele tem duas caixas, um violão e uma bicicleta. O apartamento tem dois quartos e uma cozinha clara. Tom espera que Leo goste de cozinhar, porque o Tom não gosta nem um pouco.", questions = listOf(Exercise(id = "pt-listen-new-flatmate-q1", kind = "choice", prompt = "Quantos anos o Leo tem?", options = listOf("Vinte e três", "Trinta e dois", "Vinte", "Trinta"), answers = listOf("Vinte e três"), explain = "O Leo tem vinte e três anos."), Exercise(id = "pt-listen-new-flatmate-q2", kind = "choice", prompt = "O que o Leo NÃO tem?", options = listOf("Uma televisão", "Duas caixas", "Um violão", "Uma bicicleta"), answers = listOf("Uma televisão"), explain = "Ele tem duas caixas, um violão e uma bicicleta — sem televisão."), Exercise(id = "pt-listen-new-flatmate-q3", kind = "written", prompt = "O que o Tom odeia fazer?", options = listOf(), answers = listOf("cozinhar", "ele odeia cozinhar", "tom odeia cozinhar"), explain = "O Tom não gosta nem um pouco de cozinhar."), Exercise(id = "pt-listen-new-flatmate-q4", kind = "choice", prompt = "Como é o apartamento?", options = listOf("Dois quartos e uma cozinha clara", "Um quarto e uma varanda", "Um jardim", "Dois banheiros"), answers = listOf("Dois quartos e uma cozinha clara"), explain = "O apartamento tem dois quartos e uma cozinha clara."), Exercise(id = "pt-listen-new-flatmate-q5", kind = "choice", prompt = "Onde o Leo trabalha agora?", options = listOf("Na capital", "Em uma cidade pequena", "No interior", "Ele não trabalha"), answers = listOf("Na capital"), explain = "Ele vem de uma cidade pequena do interior, mas agora trabalha na capital."), Exercise(id = "pt-listen-new-flatmate-q6", kind = "written", prompt = "Que instrumento o Leo tem?", options = listOf(), answers = listOf("um violão", "o violão", "violão"), explain = "O Leo tem um violão.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")),
    ListeningText(id = "pt-listen-new-neighbour", languageID = "pt", title = "A nova vizinha", level = "A1", topic = "pessoas", unitID = "pt-foundations-u1", text = "No prédio há uma vizinha nova. Ela se chama Amélie e é da França. Não é estudante; é fotógrafa. Não trabalha em um escritório: trabalha em casa e viaja muito. Os vizinhos são curiosos, mas também são tímidos, por isso não falam com ela. Então, uma manhã, Ben a encontra na porta. “Você é a vizinha nova?”, pergunta ele. “Sim, sou eu”, responde ela, “e estou contente de estar aqui”. Agora são amigos, e ela não está mais sozinha no prédio.", questions = listOf(Exercise(id = "pt-listen-new-neighbour-q1", kind = "choice", prompt = "De onde é a Amélie?", options = listOf("Da França", "Da Itália", "Do Japão", "Do Brasil"), answers = listOf("Da França"), explain = "A Amélie é da França."), Exercise(id = "pt-listen-new-neighbour-q2", kind = "choice", prompt = "Qual é o trabalho dela?", options = listOf("É fotógrafa", "É estudante", "Trabalha em um escritório", "É professora"), answers = listOf("É fotógrafa"), explain = "Não é estudante; é fotógrafa."), Exercise(id = "pt-listen-new-neighbour-q3", kind = "choice", prompt = "Ela trabalha em um escritório?", options = listOf("Não, trabalha em casa", "Sim, todos os dias", "Só no verão", "Ela não diz"), answers = listOf("Não, trabalha em casa"), explain = "Não trabalha em um escritório: trabalha em casa."), Exercise(id = "pt-listen-new-neighbour-q4", kind = "written", prompt = "Por que os vizinhos não falam com ela?", options = listOf(), answers = listOf("são tímidos", "porque são tímidos", "tímidos"), explain = "São curiosos, mas também são tímidos."), Exercise(id = "pt-listen-new-neighbour-q5", kind = "choice", prompt = "Onde o Ben a encontra?", options = listOf("Na porta", "No elevador", "Na rua", "No café"), answers = listOf("Na porta"), explain = "Uma manhã, o Ben a encontra na porta."), Exercise(id = "pt-listen-new-neighbour-q6", kind = "written", prompt = "Como a Amélie se sente no final?", options = listOf(), answers = listOf("contente", "feliz", "está contente"), explain = "Ela diz que está contente de estar aqui.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")),
    ListeningText(id = "pt-listen-sunday-market", languageID = "pt", title = "A feira de domingo", level = "A1", topic = "compras", unitID = "pt-foundations-u1", text = "Aos domingos tem uma feira na praça do bairro. A Ana e o pai dela vão para lá às nove horas, antes de ficar cheio. Eles compram fruta, pão e flores. A Ana quer morangos, mas o pai dela diz que estão muito caros nesta semana. No final, eles levam para casa um saco grande de laranjas e rosas brancas para a mesa da cozinha.", questions = listOf(Exercise(id = "pt-listen-sunday-market-q1", kind = "choice", prompt = "Quando a Ana e o pai dela vão à feira?", options = listOf("Às nove horas", "Ao meio-dia", "À tarde", "Às seis e meia"), answers = listOf("Às nove horas"), explain = "Eles vão às nove horas, antes de ficar cheio."), Exercise(id = "pt-listen-sunday-market-q2", kind = "written", prompt = "Por que a Ana não leva os morangos?", options = listOf(), answers = listOf("estão muito caros", "muito caros", "porque estão muito caros"), explain = "O pai diz que estão muito caros nesta semana."), Exercise(id = "pt-listen-sunday-market-q3", kind = "choice", prompt = "O que eles levam para casa?", options = listOf("Laranjas e rosas", "Morangos e pão", "Maçãs e tulipas", "Pão e queijo"), answers = listOf("Laranjas e rosas"), explain = "Eles levam laranjas e rosas brancas."), Exercise(id = "pt-listen-sunday-market-q4", kind = "choice", prompt = "Onde fica a feira?", options = listOf("Na praça do bairro", "Perto do rio", "Na estação", "Num supermercado"), answers = listOf("Na praça do bairro"), explain = "Aos domingos tem uma feira na praça do bairro."), Exercise(id = "pt-listen-sunday-market-q5", kind = "choice", prompt = "O que eles compram?", options = listOf("Fruta, pão e flores", "Peixe e legumes", "Queijo e carne", "Somente flores"), answers = listOf("Fruta, pão e flores"), explain = "Eles compram fruta, pão e flores."), Exercise(id = "pt-listen-sunday-market-q6", kind = "written", prompt = "O que a Ana quer?", options = listOf(), answers = listOf("morangos", "quer morangos"), explain = "A Ana quer morangos.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")),
    ListeningText(id = "pt-listen-apartamento-escolhido", languageID = "pt", title = "O apartamento escolhido", level = "A2", topic = "apartamentos", unitID = "pt-foundations-u4", text = "Bia e Rafa procuram apartamento no aplicativo. O primeiro é mais barato, mas fica mais longe da estação: quarenta minutos a pé. O segundo custa cem reais a mais por mês, mas é mais claro e tem varanda. Para a Bia, a luz é o mais importante, porque ela trabalha de casa. No final, decidem pedir uma visita ao segundo: é mais caro, mas é o melhor dos dois para eles.", questions = listOf(Exercise(id = "pt-listen-apartamento-escolhido-q1", kind = "choice", prompt = "Quantos apartamentos eles comparam ?", options = listOf("Dois", "Três", "Quatro"), answers = listOf("Dois"), explain = "Comparam dois apartamentos no aplicativo."), Exercise(id = "pt-listen-apartamento-escolhido-q2", kind = "choice", prompt = "Qual é o problema do mais barato ?", options = listOf("Fica longe da estação", "Não tem varanda", "É muito caro", "É pequeno"), answers = listOf("Fica longe da estação"), explain = "Quarenta minutos a pé da estação."), Exercise(id = "pt-listen-apartamento-escolhido-q3", kind = "written", prompt = "Quanto custa a mais o segundo por mês ?", options = listOf(), answers = listOf("cem reais", "100 reais"), explain = "Cem reais a mais por mês."), Exercise(id = "pt-listen-apartamento-escolhido-q4", kind = "choice", prompt = "O que é mais importante para a Bia ?", options = listOf("A luz", "O preço", "A varanda", "A cozinha"), answers = listOf("A luz"), explain = "Ela trabalha de casa."), Exercise(id = "pt-listen-apartamento-escolhido-q5", kind = "choice", prompt = "O que eles decidem no final ?", options = listOf("Pedir visita ao segundo", "Ficar com o primeiro", "Continuar procurando", "Pedir desconto"), answers = listOf("Pedir visita ao segundo"), explain = "É o melhor dos dois para eles.")), skills = listOf("listening:gist", "listening:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")),
    ListeningText(id = "pt-listen-sabado-organizado", languageID = "pt", title = "O sábado organizado", level = "A2", topic = "planos", unitID = "pt-foundations-u4", text = "Lu liga para o irmão para organizar o sábado. Ele sugere a montanha, mas vai chover, então Lu propõe o museu novo. Vão se encontrar às dez na entrada principal e almoçar na feira ao lado, que é mais barata que os restaurantes do centro. À noite não têm plano: vão decidir lá, quando souberem como vai estar o tempo.", questions = listOf(Exercise(id = "pt-listen-sabado-organizado-q1", kind = "choice", prompt = "Quem sugere a montanha ?", options = listOf("O irmão", "Lu", "A mãe", "Um amigo"), answers = listOf("O irmão"), explain = "O irmão sugere a montanha."), Exercise(id = "pt-listen-sabado-organizado-q2", kind = "choice", prompt = "Por que não a montanha ?", options = listOf("Vai chover", "Estão cansados", "O museu é grátis", "A montanha é longe"), answers = listOf("Vai chover"), explain = "Vai chover, então vão ao museu."), Exercise(id = "pt-listen-sabado-organizado-q3", kind = "written", prompt = "A que horas vão se encontrar ?", options = listOf(), answers = listOf("as dez", "às dez", "dez horas"), explain = "Às dez na entrada principal."), Exercise(id = "pt-listen-sabado-organizado-q4", kind = "choice", prompt = "Onde vão almoçar ?", options = listOf("Na feira ao lado", "Num restaurante do centro", "Em casa", "No museu"), answers = listOf("Na feira ao lado"), explain = "Mais barata que os restaurantes do centro."), Exercise(id = "pt-listen-sabado-organizado-q5", kind = "choice", prompt = "O que vão fazer à noite ?", options = listOf("Decidir lá", "Ir ao cinema", "Voltar cedo", "Encontrar amigos"), answers = listOf("Decidir lá"), explain = "Dependendo do tempo.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("grammar:future-forms")),
    ListeningText(id = "pt-listen-nunca-fez", languageID = "pt", title = "Coisas que nunca fiz", level = "B1", topic = "viagens", unitID = "pt-foundations-u6", text = "Na cozinha de um hostel, três viajantes comparam as vidas. Caio já visitou vinte países, mas nunca aprendeu a nadar: « Eu sei, é ridículo ». Marina já mergulhou duas vezes com tartarugas, mas não tinha saído do Brasil antes desta viagem. E Beatriz, que está na estrada há seis anos, nunca pegou avião: ela atravessa os oceanos de navio e as fronteiras de ônibus. « Nunca ? » pergunta Caio. « Nunca. O medo é mais velho do que eu. » Eles riem das coisas que não fizeram, e Beatriz diz uma frase que fica: « Não precisa ter feito tudo. Basta ainda querer ».", questions = listOf(Exercise(id = "pt-listen-nunca-fez-q1", kind = "choice", prompt = "O que Caio nunca fez ?", options = listOf("Aprender a nadar", "Visitar vinte países", "Atravessar de navio", "Sair do Brasil"), answers = listOf("Aprender a nadar"), explain = "Já visitou vinte países, mas nunca aprendeu a nadar."), Exercise(id = "pt-listen-nunca-fez-q2", kind = "written", prompt = "Quantas vezes Marina mergulhou ?", options = listOf(), answers = listOf("duas vezes", "2 vezes", "duas"), explain = "Marina já mergulhou duas vezes com tartarugas."), Exercise(id = "pt-listen-nunca-fez-q3", kind = "choice", prompt = "Como Beatriz atravessa os oceanos ?", options = listOf("De navio", "De avião", "De ônibus", "A pé"), answers = listOf("De navio"), explain = "Ela atravessa os oceanos de navio e as fronteiras de ônibus."), Exercise(id = "pt-listen-nunca-fez-q4", kind = "choice", prompt = "O que Beatriz diz sobre o medo ?", options = listOf("É mais velho do que ela", "É mais jovem", "É ridículo", "Se foi"), answers = listOf("É mais velho do que ela"), explain = "O medo é mais velho do que eu."), Exercise(id = "pt-listen-nunca-fez-q5", kind = "written", prompt = "O que basta, segundo Beatriz ?", options = listOf(), answers = listOf("ainda querer", "basta ainda querer"), explain = "Basta ainda querer.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")),
    ListeningText(id = "pt-listen-cidade-interior", languageID = "pt", title = "Da cidade para o interior", level = "B1", topic = "mudanças", unitID = "pt-foundations-u6", text = "Pedro conta por que saiu de São Paulo. Antes ele morava num apartamento pequeno e trabalhava onze horas por dia: « Eu ganhava bem, mas não tinha vida ». Num inverno ele adoeceu, e aí entendeu que precisava mudar. Agora mora num vilarejo de mil habitantes, trabalha de casa pela manhã e cuida de uma horta à tarde. « Ganho menos, mas sobra tempo. » No começo os pais não entendiam; agora vêm todo mês. « Você se arrepende de algo ? », pergunta a amiga. « De não ter feito isso antes ».", questions = listOf(Exercise(id = "pt-listen-cidade-interior-q1", kind = "choice", prompt = "Onde Pedro morava antes ?", options = listOf("Em São Paulo", "Num vilarejo", "No Rio de Janeiro", "Num hostel"), answers = listOf("Em São Paulo"), explain = "Pedro conta por que saiu de São Paulo."), Exercise(id = "pt-listen-cidade-interior-q2", kind = "written", prompt = "Quantas horas ele trabalhava por dia ?", options = listOf(), answers = listOf("onze horas", "11 horas", "onze"), explain = "Trabalhava onze horas por dia."), Exercise(id = "pt-listen-cidade-interior-q3", kind = "choice", prompt = "O que o fez mudar ?", options = listOf("Ele adoeceu", "Perdeu o emprego", "Ganhou na loteria", "Conheceu alguém"), answers = listOf("Ele adoeceu"), explain = "Num inverno ele adoeceu, e aí entendeu."), Exercise(id = "pt-listen-cidade-interior-q4", kind = "choice", prompt = "O que ele faz à tarde agora ?", options = listOf("Cuida de uma horta", "Trabalha mais horas", "Viaja todo mês", "Estuda"), answers = listOf("Cuida de uma horta"), explain = "Trabalha pela manhã e cuida de uma horta à tarde."), Exercise(id = "pt-listen-cidade-interior-q5", kind = "written", prompt = "De que Pedro se arrepende ?", options = listOf(), answers = listOf("de nao ter feito isso antes", "de não ter feito isso antes", "nao ter feito antes", "não ter feito antes"), explain = "« De não ter feito isso antes ».")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions")),
    ListeningText(id = "pt-listen-pechincha-mesa", languageID = "pt", title = "A pechincha da mesa", level = "B2", topic = "negociação", unitID = "pt-foundations-u7", text = "Num aplicativo de usados, Bia quer uma mesa de madeira por 80 reais. « E se combinarmos em 60 ? », propõe ela. O vendedor recusa: « Só se você levar hoje ». Bia pensa: « Eu lhe daria 65 se incluir a cadeira ». « Impossível », ri ele, « mas eu deixaria a mesa por 70 e a subitaria para você ». Bia não hesita: « Você a subiria sozinho ? ». « Tenho um carrinho », responde. « Fechado », diz ela, e acrescenta: « Se ela for tão bonita quanto na foto, você ganha cinco estrelas ».", questions = listOf(Exercise(id = "pt-listen-pechincha-mesa-q1", kind = "choice", prompt = "Quanto o vendedor pede ?", options = listOf("80 reais", "60 reais", "70 reais", "65 reais"), answers = listOf("80 reais"), explain = "A mesa custa 80 reais."), Exercise(id = "pt-listen-pechincha-mesa-q2", kind = "written", prompt = "O que Bia propõe primeiro ?", options = listOf(), answers = listOf("60 reais", "sessenta reais", "combinar em 60"), explain = "« E se combinarmos em 60 ? »."), Exercise(id = "pt-listen-pechincha-mesa-q3", kind = "choice", prompt = "Que condição o vendedor põe ?", options = listOf("Levar hoje", "Pagar à vista", "Dar cinco estrelas", "Voltar amanhã"), answers = listOf("Levar hoje"), explain = "« Só se você levar hoje »."), Exercise(id = "pt-listen-pechincha-mesa-q4", kind = "choice", prompt = "O que o vendedor oferece por 70 ?", options = listOf("Subir a mesa", "Incluir a cadeira", "Baixar para 60", "Emprestar o carrinho"), answers = listOf("Subir a mesa"), explain = "« Eu a subitaria para você »."), Exercise(id = "pt-listen-pechincha-mesa-q5", kind = "written", prompt = "O que Bia promete se gostar ?", options = listOf(), answers = listOf("cinco estrelas", "5 estrelas"), explain = "Cinco estrelas.")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors")),
    ListeningText(id = "pt-listen-noticia-bairro", languageID = "pt", title = "A notícia do bairro", level = "B2", topic = "notícias", unitID = "pt-foundations-u8", text = "Na feira, Camila e Rafael comentam o que se diz. « Dizem que vão peatonalizar a rua principal », conta Camila. « De novo ? », ri Rafael. « A notícia que li diz que começa na primavera ». Segundo a prefeitura, seria só aos sábados, mas os comerciantes, cujo faturamento dependeria do turismo, já se manifestaram. « É verdade que o barulho cairia », admite Rafael, « mas, e o estacionamento ? ». Camila defende a medida: « Por um lado, mais gente caminharia; por outro, os ônibus parariam na porta ». Eles não decidem nada, mas prometem voltar a falar disso quando o plano sair.", questions = listOf(Exercise(id = "pt-listen-noticia-bairro-q1", kind = "choice", prompt = "O que dizem da rua principal ?", options = listOf("Que será peatonalizada", "Que será alargada", "Que será fechada", "Que mudará de nome"), answers = listOf("Que será peatonalizada"), explain = "« Dizem que vão peatonalizar a rua principal »."), Exercise(id = "pt-listen-noticia-bairro-q2", kind = "written", prompt = "Quando começaria ?", options = listOf(), answers = listOf("na primavera", "primavera"), explain = "« A notícia que li diz que começa na primavera »."), Exercise(id = "pt-listen-noticia-bairro-q3", kind = "choice", prompt = "O que diz a prefeitura ?", options = listOf("Só aos sábados", "Todos os dias", "Só no verão", "Nos feriados"), answers = listOf("Só aos sábados"), explain = "Seria só aos sábados."), Exercise(id = "pt-listen-noticia-bairro-q4", kind = "choice", prompt = "Quem se manifestou ?", options = listOf("Os comerciantes", "Os moradores", "Os taxistas", "A prefeitura"), answers = listOf("Os comerciantes"), explain = "Os comerciantes já se manifestaram."), Exercise(id = "pt-listen-noticia-bairro-q5", kind = "written", prompt = "O que Camila e Rafael prometem ?", options = listOf(), answers = listOf("voltar a falar disso", "falar disso de novo"), explain = "Prometem voltar a falar disso quando o plano sair.")), skills = listOf("listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors"))
) }
